pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead" — penalize them heavily.
    let dead_threshold = 10u32; // smallest item size possible
    if post_residual < dead_threshold && post_residual > 0 {
        score += 200.0 * (dead_threshold - post_residual) as f64;
    }

    // Non-linear penalty for tight-but-wasteful fits: a small but usable
    // gap is worse than a clean fill or a comfortable remainder.
    if post_residual > 0 && post_residual <= 20 {
        score += 30.0 * (20 - post_residual) as f64;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, spreading is cheap.
    let bin_pressure = open_bins_count as f64 / (mean_residual.max(1.0));
    score += bin_pressure * 5.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer bins that keep flexible space.
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 40.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to the known next item.
            score += 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual. Only make
    // it attractive when existing bins would be badly fragmented or when
    // the item barely fits anywhere. Penalize the fresh bin by default via
    // its large post_residual, but give a discount when current mean
    // residual is small (open bins nearly full).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // If open bins are nearly exhausted, a new bin is fine.
        if open_bins_count > 0 && mean_r < item_size as f64 * 1.2 {
            score -= 60.0;
        } else if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // Existing bins fit: discourage opening a new one unless the
            // fit would leave tiny dead space.
            score += 25.0;
        }
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (long stream ahead, flexibility matters); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            score += 60.0 * (11.0 - gap); // tiny dead space is worst outcome
        } else if gap <= 20.0 {
            score += 25.0 * (21.0 - gap) / 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 2.5 * open_bins_count as f64;

    // If the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next == 0 {
            score -= 70.0;
        } else if leftover_after_next <= 10 {
            score += 20.0; // would create tiny dead space next step
        } else {
            score -= 10.0;
        }
    }

    // Compare against mean residual: bins with residual far below mean are tighter; prefer them.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin pressure is high; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 55.0; // nothing fits: open new bin
        } else if open_bins_count > 6 {
            score -= 15.0 * (open_bins_count as f64 - 6.0).min(4.0);
        } else {
            score += 40.0; // discourage opening new bins when open ones can fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0; // unusable sliver
    }
    // Penalize gaps too small for the known next item (lookahead-aware dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 200.0 + (next_item_size as f64 - post_residual as f64) * 5.0;
    }
    // Reward tight fits (small useful post_residual)
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    }

    // Slight preference for fuller bins relative to mean residual
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Late-stream: prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: bins whose residual lands on a "friendly" multiple of 10
    // are more reusable for future items (sizes 1..100 often cluster mod 10).
    let harmonic = post_residual % 10;
    score -= harmonic as f64 * 3.0;

    // Integer-division class of post_residual: coarse buckets of reusability.
    let class = post_residual / 10;
    score -= class as f64 * 2.0;

    // Lookahead coupling: reward when next item fits the post-residual exactly
    // or nearly; penalize when post-residual is just barely too small (dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 400.0; // chain of perfect fits
            } else {
                score -= 40.0 * (1.0 - slack as f64 / 50.0).max(0.0);
            }
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 60.0; // placing here would block the next item
        }
    }

    // Penalize tiny unusable residuals (dead space) unless item is large.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make empty bin moderately attractive only when
    // existing residuals are poor fits (item leaves awkward remainder).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when item is large and would leave big dead space elsewhere,
        // or late in the stream when spreading load reduces fragmentation.
        score -= 120.0 * (item_size as f64 / 100.0);
        score -= 100.0 * progress;
        score -= mean_residual * 0.5;
        if waste < 20.0 {
            score += 150.0; // item fits tightly somewhere already -> use it
        }
    }

    // Mild preference for filling fuller bins among equals.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Nonlinear penalty for growing dead space beyond the minimum item size.
    if post_residual > 0 && post_residual < item_size as f64 * 0.5 {
        score += 25.0 + (10 - post_residual.min(10)) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open bins pressure: discourage spreading across many bins when few needed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late when open bins are fragmented.
        score += 20.0 + 30.0 * (1.0 - progress) - open_bins_count as f64 * 2.0;
        // If existing fits are very poor, opening a new bin is acceptable.
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to avoid opening a new bin.
        score -= 35.0;
    }

    // Prefer bins with residuals close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    // Mean residual coupling: if mean residual is high, favor using existing space.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Lookahead: if next item could use the post residual, reward leaving it.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward placements that leave little but usable residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; mild penalty unless residual is tiny.
            score += 3.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer reusing bins over opening new ones.
    score += 0.5 * open_bins_count as f64;

    // Global residual pressure: if mean residual is large, prefer bins above mean (consolidate).
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early on, be conservative about dead space; late, exploit tight fits.
    score += (1.0 - progress) * 0.05 * post_residual as f64;
    score -= progress * 5.0 * tightness;

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted as the stream progresses.
        score = 40.0 - 15.0 * progress;
        // If only the new bin can fit the item, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Large items justify fresh bins more (less dead-space risk).
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is costly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (near-perfect packing).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 50.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving medium dead space.
        score += 10.0;
    }

    // Mean residual coupling: penalize bins far below mean residual (wasteful pick).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: prefer opening fresh bin only if no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else {
            // Slight penalty so existing decent fits win; new bin only wins on bad fits.
            score += 15.0 + open_bins_count as f64 * -0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item are pure waste. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize small-but-marginal gaps that few future items can use.
    if post_residual > 0 && post_residual < 25 {
