    }

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count <= 2 {
        score -= 15.0; // last-chance bin: strongly prefer using it
    } else {
        score += (open_bins_count as f64) * 0.8;
    }

    // Prefer bins with below-average residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // current fit is poor or many bins are open.
    if bin_residual == bin_capacity {
        score += 5.0;
        if post_residual > 0 && post_residual < 10 {
            // empty bin avoids creating a dead gap
        }
        score -= (open_bins_count as f64) * 0.3;
    }

    // Late-stream tightening: waste matters more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is unusable
    // (smallest item is ~10), so heavily penalize creating such gaps.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    }
    // Post-residual just above the minimum item size is also risky if the
    // next item cannot use it; scale penalty by how "awkward" the gap is.
    if post_residual >= 10 && post_residual <= 19 {
        score += 12.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild pressure to spread load, avoid over-hoarding
    // one bin (mild open-bins pressure handled below).
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins; opening new bins is penalized via the empty-bin
    // candidate below.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a decent existing fit.
        score = bin_capacity as f64 - 10.0;
        // If this bin is the last chance, opening new bin is bad.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0;
        }
        // Lookahead: if next item is large, a fresh bin with full residual
        // is valuable.
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 10.0;
        }
        // Few open bins early in the stream: new bins are cheap.
        if open_bins_count < 3 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize dead space more.
        score += 8.0;
    }

    // Progress-based mild adaptation: late in the stream, be more
    // conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end with zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the post-residual exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + gap);
        if gap == 0.0 {
            score -= 500.0; // two-item perfect chain
        }
    }

    // Penalize post_residual that is dangerously close to next_item_size
    // (dead space: next item almost fits but not quite)
    if next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 150.0 * (1.0 - miss / 10.0);
        }
    }

    // Penalize small unusable residuals (< 10, nothing can fit later)
    if post_residual < 10 && post_residual > 0 {
        score += 300.0;
    }

    // Relative-to-mean coupling: prefer bins tighter or looser than average
    // depending on whether we want to consolidate or spread.
    let mr = mean_residual;
    if (post_residual as f64) < mr {
        score -= (mr - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mr) * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // fragmented (high mean residual spread) or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if fragmentation > 20.0 || (large_item && next_item_size == 0) {
            score -= 100.0 + progress * 50.0;
        } else {
            score += 400.0; // prefer reusing open bins
        }
    }

    // Mild penalty for opening bins early in the stream
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are toxic.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual < dead_threshold && post_residual > 0 {
        // Unusable sliver: penalize hard, scaled by how small the gap is.
        let tightness = (dead_threshold - post_residual) as f64 / dead_threshold as f64;
        score += 60.0 + 40.0 * tightness;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Sets up an exact fit for the lookahead item.
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual that can host the next item is valuable.
        score -= 15.0 * (post_residual as f64 / dead_threshold as f64).min(3.0);
    }

    // Large residual waste: leaving big gaps when item was small is fine (flexible),
    // but prefer tighter fills mildly: reward smaller post_residual generally.
    score += 0.05 * (post_residual as f64 - mean_residual).abs().signum()
        * (post_residual as f64 - mean_residual).abs();

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: opening a bin is wasteful unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Less pressure to open new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Open-bin pressure: many open bins -> consolidate into existing ones.
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match bonus: next item fits with small waste after this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }

    // Penalize placing the next item now if it would NOT fit afterwards (bad chaining).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Small dead space is worse than large dead space relative to next item.
        let dead = (next_item_size - post_residual) as f64;
        score += 10.0 + dead.min(40.0);
    }

    // Reward packing into bins with residual below mean (tighter bins first),
    // penalize wasting large-residual bins on small items.
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 8.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when this item is huge relative to capacity
    // or the stream is early and many bins are still to come.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = item_size as f64 / bin_capacity as f64;
        score += 45.0;                       // base penalty for opening a new bin
        score -= tight_fit * 40.0;           // huge items justify fresh bins
        score -= (1.0 - progress) * 15.0;    // early stream: fresh bins cheaper
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;                   // fresh bin also fits the next item
        }
    }

    // Mild penalty for leaving awkward mid-range residuals that few items fit.
    if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
