pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions create dead-space classes.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Penalize residuals in "unusable" classes: small leftovers (<10) are dead space
    // unless exactly 0 (perfect fit). Use modulo classes on post_residual.
    if post_residual == 0 {
        score -= 500.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 80.0; // tiny dead space, unusable for typical items
    } else {
        // Modulo-10 class: residuals that are multiples of 10 are more reusable
        let cls = post_residual % 10;
        score += cls as f64 * 1.5;
    }

    // Integer-division thresholds: reward residuals that can still host common sizes
    let halves = post_residual / 2; // integer division threshold
    if halves >= 40 {
        score -= 15.0; // roomy bin, still flexible
    } else if halves >= 20 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, scaled by how tightly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.2;
        } else {
            // next item won't fit here: this bin becomes dead after placement
            score += 30.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (new bin also returns ~post_residual == capacity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current fit is poor (large post_residual, no lookahead fit).
    if bin_residual == bin_capacity {
        // neutral base for new bin; slight penalty so existing bins with good
        // fits win, but bonus if open bins are nearly full on average.
        score = frac * 100.0;
        let pressure = mean_residual / cap; // average fullness slack
        if pressure < 0.15 {
            score -= 20.0; // open bins nearly full -> opening new bin is fine
        }
        if next_item_size > 0 && next_item_size > 90 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: early on, be more willing to open bins (exploration);
    // later, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (post_residual as f64 / cap);

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

