        score = cap * 0.55 + 20.0 * (1.0 - pressure);
        if fitting_bins_count == 1 {
            score += 80.0; // never open new when only one bin fits
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 25.0; // big item coming: fresh bin is useful
        }
    }

    // Late-stream consolidation: tighten bin selection as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / cap));

    // Prefer bins below mean residual (consolidating waste)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let pr = post_residual as f64;
    let dead_zone = 12.0; // gaps below this are likely unusable dead space
    if pr > 0.0 && pr < dead_zone {
        score += (dead_zone - pr) * 6.0; // strong penalty for tiny gaps
    }
    // Perfect fit: big reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: penalize using bins when many are open,
    // encouraging consolidation; but relax when few bins open.
    let pressure = open_bins_count as f64;
    score += 1.5 * pressure * (1.0 - tightness);

    // Last-chance bin: strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if the item is huge relative to
    // capacity or no open bin fits well (avoid proliferating bins).
    if bin_residual == bin_capacity {
        score += 35.0 + 4.0 * pressure;
        if item_size as f64 / cap > 0.8 {
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 35.0;
    }
    // Penalize if post residual cannot fit the lookahead item but could
    // have fit more of it (wasted potential).
    if next_item_size > 0 && pr > 0.0 && (next_item_size as u32) > post_residual {
        score += 8.0;
    }

    // Stream progression: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    // Mean residual coupling: prefer bins below mean residual (more filled).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Post residual slightly below next item size is dead space for the lookahead
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward bins whose post_residual stays close to mean residual (keeps bin spread uniform)
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable residuals (< 10 can never fit any item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Brand-new bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    // Late in the stream, tighten packing: prefer bins with less leftover
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can chain two items.
            score -= 0.35 * next_item_size as f64;
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many open bins when residuals are large.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Time horizon: early in the stream, prefer consolidating into existing bins
    // (keep flexibility); late in the stream, prioritize filling bins completely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps balance), unless it's a near-perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - tightness);

    // New bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 15.0 * desperation + 0.1 * open_bins_count as f64;
        // Late in stream, opening a new bin is cheaper than wasting space.
        score -= 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth coupling: small post-residuals get progressively more attractive
    // as the stream advances (tight packing matters more late).
    let tight = 1.0 - prn;
    score -= 30.0 * tight * tight * (0.5 + progress);

    // Penalize large dead space quadratically, modulated by progress.
    score += 2.0 * prn * prn * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin,
    // smoothly scaled by how well it fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * tight * (1.0 + progress);
    }

    // Prefer bins whose residual is below the mean (consolidating space),
    // smooth interaction with progress.
    score -= 5.0 * ((mean_residual - pr) / cap) * (0.5 + progress);

    // Lookahead: reward leaving room for the next item smoothly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).max(0.0) / cap;
        let cover = if pr >= ns { 1.0 } else { (pr / ns.max(1.0)) as f64 };
        score -= 12.0 * gap * cover;
        score += 6.0 * (1.0 - cover) * prn;
    }

    // Mild dispersion pressure: with many open bins, prefer tighter fits.
    score += 0.05 * (open_bins_count as f64).sqrt() * prn * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (low post_residual) win.

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (dead-space "harmonics").
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let harmonic_penalty: f64 = if post_residual == 0 {
        -30.0 // perfect closure
    } else if post_residual < eighth {
        -12.0 // nearly full, small unusable sliver
    } else if post_residual == quarter || post_residual == half {
        -6.0 // harmonic residual: reusable by common item sizes
    } else if post_residual < quarter {
        0.0
    } else if post_residual < half {
        4.0 // awkward mid-range dead space
    } else {
        10.0 // more than half wasted
    };
    score += harmonic_penalty;

    // Modulo coupling: leftover divisible by small item sizes is reusable.
    if post_residual > 0 {
        let mut reusable = 0u32;
        for s in [10u32, 15, 20, 25, 30, 40, 50] {
            if post_residual % s == 0 && post_residual >= s {
                reusable += s;
            }
        }
        if reusable > 0 {
            score -= (reusable as f64) * 0.15;
        }
        // Non-harmonic leftovers are penalized more strongly as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if post_residual % 10 != 0 {
            score += 6.0 * progress;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual - next_item_size < eighth {
            score -= 10.0;
        }
        // Penalize if the next item would NOT fit here but fits elsewhere (fragmentation risk).
        if next_item_size > post_residual {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bins are crowded
    // or the item would leave a very bad residual everywhere.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 0.6;
        let mean_tight = if mean_residual < 25.0 { 12.0 } else { 0.0 };
        score += 18.0 + crowded + mean_tight;
        // Allow a new bin late in the stream when residuals are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 15.0 && open_bins_count > 3 {
            score -= 10.0 + 8.0 * progress;
        }
    }

    // Mild preference for filling fuller bins first.
    score -= (bin_residual as f64) * 0.05;

    // Tie-break noise-free deterministic nudge toward earlier bins.
    score += (open_bins_count as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are >= 1, but typical streams waste gaps < ~10). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual relative to item).
    score -= 0.5 * (item_size as f64) / (bin_residual as f64).max(1.0) * 10.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins is penalized implicitly by rewarding
    // placement into bins below the mean residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }
    // If next item cannot fit in post_residual but post_residual is large,
    // mild penalty for leaving a stranded mid-size gap.
    if next_item_size > post_residual && post_residual > 15 {
        score += 0.3 * (post_residual as f64 - 15.0);
    }

    // New-bin candidate handling: an empty bin has large post_residual and
    // gets no bonuses; add a mild fixed cost so it only wins when all open
    // fits are poor (dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect 2-step fit: big bonus
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        // Coupling: exact match (slack == 0) is the dream case
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize dead space
        let gap = (next_item_size - post_residual) as f64;
        score += 0.35 * gap.min(60.0);
    }

    // Penalize creating small unusable残 residuals relative to the minimum possible future item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used sparingly
        score += 30.0;
        // But if the item fits snugly in a fresh bin, allow it
        let snug = (bin_capacity - item_size) as f64;
        if snug < 10.0 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer filling fuller bins (tight packing) with a mild non-linear term
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Base: opening a new bin wastes the residual that other bins could absorb.
        score += 12.0;

        // Early in the stream, opening bins is cheap (many future items to fill them);
        // late in the stream, prefer squeezing into existing bins.
        score -= 18.0 * (1.0 - progress);

        // If many bins are open, avoid spreading further.
        score += (open_bins_count as f64).sqrt() * 1.5;

        // If only one bin can fit the item, this bin is the last chance — but a new
        // bin may still be better if the fit here would be terrible.
        if fitting_bins_count == 1 {
            // The single fitting bin's wasted space would be (bin_residual - item_size)
            // for that bin; we don't see it directly, but mean_residual gives a hint.
            // If mean residual is small, existing bins are tight -> new bin less costly.
            score -= 6.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        }

        // Lookahead: if the next item is large, a fresh bin with big residual is valuable.
        if next_item_size > 0 {
            let next_fits_new = next_item_size <= bin_capacity;
            if next_fits_new {
                let leftover_for_next = bin_capacity.saturating_sub(next_item_size);
                score -= 0.10 * leftover_for_next as f64 * (1.0 - progress);
            }
        }
    } else {
        // Reward tight fits: small post_residual is already the base score.
        // Penalize leaving awkward dead space (small but unusable residuals).
        if post_residual > 0 && post_residual < 10 {
            score += 4.0; // creates nearly useless sliver
        }

        // Reward perfect fits strongly.
        if post_residual == 0 {
            score -= 10.0;
        }

        // Last-chance bonus: if this is the only bin that fits, prefer it over a new bin.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }

        // Lookahead synergy: if next item fits exactly into the resulting residual,
        // this placement is excellent.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 7.0;
        }
        // Penalize if next item is large and would not fit the residual, making
        // this bin's leftover likely dead space late in the stream.
        else if next_item_size > post_residual && post_residual > 0 {
            score += 0.05 * post_residual as f64 * progress;
        }

        // Slight preference for placing into bins with above-average residual
        // (keeps tight bins free for tight items).
        let mean_r = mean_residual.max(0.0);
        if (bin_residual as f64) > mean_r {
            score -= 1.0;
        } else {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild penalty on wasted space.
    // Late (progress ~ 1): strong quadratic penalty on dead space.
    let poly = 1.0 + 2.0 * progress + 3.0 * progress * progress;
    score += norm_pr * norm_pr * cap * poly * 0.5;

    // Reward tight fits: post_residual near 0 gets a bonus scaled by progress.
    score -= (1.0 - norm_pr).powi(6) * (10.0 + 20.0 * progress);

    // Lookahead: bonus if next item can use the post-residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack).powi(3) * 15.0;
        } else {
            // next item cannot fit here: penalize residual that strands space
            score += (nxt - pr) / cap * 10.0 * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Deviation from mean residual: prefer bins whose fill diverges from average.
    let dev = (mean_residual - pr) / cap;
    score -= dev * dev * 5.0;

    // New-bin candidate: neutral-ish baseline with progress-dependent penalty
    // (opening new bins is discouraged more as the stream matures).
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * progress) - (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity-fraction buckets.
    let quarter = (bin_capacity / 4) as f64;
    let eighth = (bin_capacity / 8) as f64;
    let post_f = post_residual as f64;

    // Dead-space penalty grows superlinearly when post_residual falls into a
    // "useless" harmonic class (small remainders unlikely to fit future items).
    if post_residual > 0 {
        let class = (post_f / eighth).floor(); // 0..12 harmonic buckets
        let class_penalty = match class as u32 {
            0 => 40.0,                      // 1..12: nearly dead space
            1 => 18.0,                      // 13..24
            2 => 8.0,                       // 25..37
            3 => 3.0,                       // 38..50: half-ish bin, still useful
            4 => 1.0,
            _ => 0.0,
        };
        score += class_penalty;
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Harmonic-friendly fit: next item leaves another small remainder.
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= bin_capacity / 8 {
                score += 6.0; // creates fresh dead space for the future
            } else {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this residual; residual value drops.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current residual
    // is in a bad harmonic class and item is large.
    if bin_residual == bin_capacity {
        let bad_current = bin_residual - item_size < bin_capacity / 8 && bin_residual - item_size > 0;
        if bad_current {
            score -= 10.0; // encourage fresh bin over creating tiny remainder
        } else {
            score += 15.0; // discourage wasting a fresh bin on good fits
        }
    }

    // Late-stream consolidation: as stream progresses, prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_f - quarter).abs() * 0.3;

    // Slight preference to balance residual toward mean (avoid fragmentation).
    score += (post_f - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 12) are dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small-but-alive gaps are risky; mild penalty scaled by gap size.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward very tight fits (post_residual small but usable).
    if post_residual >= 12 && post_residual <= 30 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 20.0 - slack as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 12 {
        score += 25.0; // dead space that the next item cannot use
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 2.0;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: neutral-ish, but open it when open bins are crowded
    // or this is a poor fit; penalize slightly by default to prefer reuse.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.0;
        if post_residual > 40 {
            score += 20.0; // opening a fresh bin for a small item wastes capacity
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let perfect = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - perfect * perfect);

    // 2-step lookahead: if the next item exactly fills the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover slack after that second placement
            let slack2 = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack2 as f64 / bin_capacity as f64);
        } else {
            // next item won't fit in this residual: penalize proportional to mismatch
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss.min(40.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating small unusable dead space (1..=9) that likely wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New empty bin candidate: default is worse than a good existing fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no open bin fits well (few fitting bins), opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    // Mild pressure to reduce number of open bins early.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) < next_item_size {
            // wasted gap smaller than next item: harsher if gap is tiny
            let gap = post_residual as f64;
            score += 8.0 * (1.0 - gap / nxt) * (1.0 - gap / nxt);
        } else {
            // gap can host next item: reward proportionally
            score -= 6.0 * (nxt / (post_residual as f64));
        }
    } else {
        // Last item: any residual is pure waste; strongly prefer tightest bin.
        score += 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more when many bins are open and fragmented mean residual is high.
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 10.0 + 18.0 * fragmentation + 10.0 * (1.0 - progress);
        // If no open bin fits (fitting_bins_count == 0), the new bin is the only option;
        // soften its penalty so it still gets chosen.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into bins with below-average residual (filling the emptiest-feeling bins first).
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.06 * rel;

    // Time horizon: late in the stream, tighten preference for exact fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * tightness;

    // Mild penalty for very large items into nearly-full bins creating slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, with smooth polynomial shaping that penalizes
    // very small dead space quadratically (wasted slivers) and rewards
    // mid-range residuals that remain reusable for future items.
    let mut score = x - 2.0 * x * (1.0 - x);

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight packing into existing bins; late in the
    // stream, dead space matters less so weight post_residual more.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: penalize leaving residuals that neither fit
    // the next item nor are near zero, weighted by progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        let mismatch = gap * gap * (1.0 - gap * gap).max(0.0);
        score += 3.0 * mismatch * (1.0 - progress);
    }

    // Reward using the last fitting bin (avoid opening a new bin),
    // smoothly scaled by how scarce fitting options are.
    if fitting_bins_count <= 2 {
        score -= 2.0 / fitting_bins_count as f64;
    }

    // Penalize bins whose residual deviates from the mean residual
    // (keeps the open-bin pool homogeneous and predictable).
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // Mild reward for consolidating into already-open bins vs new bins.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * 0.01;

    // New-bin candidate: make empty-bin choice less attractive unless
    // the item is large relative to capacity (poor fit elsewhere).
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 1.5 * (1.0 - large * large) + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..=10, i.e. nearly perfect fits) are golden.
    let residue_class = post_residual % 25;
    if post_residual == 0 {
        score -= 200.0; // perfect packing
    } else if residue_class <= 10 {
        score -= 60.0 - (residue_class as f64) * 4.0;
    } else if residue_class <= 20 {
        score += 10.0;
    } else {
        score += 25.0; // dead-space-ish class (21..24 mod 25)
    }

    // Integer-division thresholds: how many size-10 items could still fit?
    let slots = post_residual / 10;
    score -= slots as f64 * 8.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact-class match reward
            if post_residual % next_item_size.max(1) == 0 {
                score -= 45.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: penalize leaving awkward residue
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity or the stream is early and mean residual is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 90.0;                 // base cost of opening a bin
        score -= fill_frac * 120.0;    // big items justify fresh bins
        score += mean_residual * 0.4;  // poor existing residuals favor new bin
        score -= (1.0 - progress) * 10.0;
    }

    // Mild pressure against accumulating many open bins with fat residuals.
    score += open_bins_count as f64 * 0.5;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual stays "usable" (>= 10, the min item size).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Open-bins pressure: when many bins are open, prefer packing into
    // existing bins over opening new ones.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize if next item would leave another dead gap.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 20.0;
    }

    // Mild preference toward tighter-than-average bins.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Early in stream, be slightly more willing to open new bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this placement is ideal — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }
    // If next item fits into post residual, mild reward proportional to fit quality.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64;
    }
    // If next item cannot use the dead space, penalize small unusable leftovers.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize dead space below the smallest plausible item (1..100 range: use 10 as soft floor)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Relative to mean residual: bins with residual close to item usage are attractive.
    let resid_f = bin_residual as f64;
    let tightness = (resid_f - mean_residual) / bin_capacity as f64;
    score += tightness * 40.0;

    // New-bin candidate: neutral-ish baseline; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin keeps flexibility: give it a mild penalty so it's
        // chosen only when existing bins score worse (poor fits / dead space).
        score += 25.0;
        // But if lookahead suggests next item is large and this bin would be near-empty,
        // slightly favor opening fresh capacity.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Late in the stream, consolidate: discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0 * next_item_size as f64 / bin_capacity as f64;
        }
    }

    // Prefer filling bins that are already relatively full.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fullness;

    // Global state: when many bins are open, discourage opening new ones
    // (make the new-bin candidate, residual == capacity, less attractive).
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Early in stream, new bins are cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins with residuals near/below mean
    // (consolidate into fuller bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: late in the stream, be extra greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth polynomial shaping
    let x = post / cap; // in [0,1]
    // Waste potential: post_residual that is small is valuable (tight fit); large is dead space
    let tightness_bonus = -(1.0 - x) * (1.0 - x) * cap * 0.5;
    let dead_space_penalty = x * x * x * cap * 0.35;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer moderate residuals (keep flexibility); late, prefer tight fits strongly
    let coupling = post * (0.5 + 1.5 * progress * progress) * 0.01;

    // Perfect-fit reward (smooth, no hard threshold)
    let perfect_fit = -8.0 * (1.0 - x).powi(6);

    // Last-chance bin reward when few fitting bins
    let last_chance = if fitting_bins_count == 1 { -3.0 } else { 0.0 };

    // Lookahead: penalize if post_residual cannot fit next item (smoothly)
    let lookahead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0);
        0.05 * gap * (1.0 + progress)
    } else {
        0.0
    };

    // Slight preference to fill already-open bins vs opening new ones
    let new_bin_penalty = if bin_residual == bin_capacity {
        2.0 + 4.0 * progress
    } else {
        0.0
    };

    let mut score = post
        + dead_space_penalty
        + coupling
        + lookahead
        + new_bin_penalty
        + tightness_bonus
        + perfect_fit
        + last_chance;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space classes via modulo arithmetic
    let pr = post_residual;
    let class = pr % 10; // decade class of leftover

    // Small leftovers (0..=10) are "perfect closes" -> reward heavily
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 40.0 - (pr as f64);
    } else {
        // Penalize leftovers that no typical item can use: harmonic dead zones
        // Items are 1..=100; leftover usable if some future item ~ matches it.
        // Class residuals in (10, 20] are semi-usable, above 50 nearly always usable later.
        let frac = pr as f64 / cap;
        if frac < 0.25 {
            score += 12.0; // awkward small-medium dead space
        } else if frac < 0.5 {
            score += 4.0;
        } else {
            score -= 6.0; // large residual: bin stays flexible
        }
        // Modulo-10 harmonic penalty: residuals congruent to 1..3 mod 10 are hardest to fill
        if class >= 1 && class <= 3 {
            score += 6.0;
        } else if class >= 8 || class == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            // scaled reward for next item fitting in the remainder
            score -= 10.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use remainder: penalize proportionally to wasted fit
            score += 5.0 * (1.0 - (pr as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred unless they score badly
        score += 45.0;
        // early in stream, opening bins is cheap; late, conserve bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // if many open bins already, discourage one more
        score += 2.0 * open_bins_count as f64;
        // if next item is huge, a fresh bin is valuable
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Tie-break: prefer tighter existing bins (small residual) slightly
    score += (bin_residual as f64) * 0.05;
    // Mild preference toward bins whose residual is below mean (compact packing)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.91;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match within a small window around next_item_size -> graded reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack * 0.2);
    }

    // Dead space: post_residual too small for the next item (unusable for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
    }

    // Reward tight fits relative to the mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Early in the stream, prefer filling existing bins over proliferating bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large or stream is late.
        score += 35.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional dead space: penalize wasted capacity more strongly.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Tight fit reward: small post_residual strongly favored.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if next_item_size > bin_residual {
            // next item won't fit here anyway; slight reward for using space now
            score -= 6.0;
        } else {
            // next item fits here only if we DON'T place current item here;
            // penalize blocking a good future fit.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the fit elsewhere is bad. Penalize the empty-bin candidate.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, be more willing to open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many bins are open, prefer consolidating.
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Global residual state: if mean residual is large, prefer bins that
    // reduce fragmentation (i.e., larger item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= mean_residual / 20.0 * fill_ratio;

    // Late-stream consolidation: prefer reusing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - waste_frac);

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling: waste penalty grows superlinearly
    // with residual, modulated by stream progress.
    let waste_poly = pr_norm * pr_norm * (1.0 + 3.0 * progress);
    score += 40.0 * waste_poly;

    // Cubic interaction term: late in stream, large residuals are very bad
    let late_cube = pr_norm * pr_norm * pr_norm * progress * progress;
    score += 25.0 * late_cube;

    // Lookahead coupling: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_frac = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 12.0 * fit_frac * (1.0 - progress);
    }

    // Penalize dead space that is too small for any plausible item (min 1)
    if pr > 0 && pr < 10 {
        score += 15.0 * (1.0 - pr as f64 / 10.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalize opening a new bin, more so early/mid stream
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score = cap * (1.0 + 0.5 * openness) + 10.0 * (pr_norm - pr_norm * pr_norm);
    }

    // Mild preference toward fuller bins relative to mean residual
    score -= 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Dead-space penalty: residuals that are too small to fit typical items are waste.
    // Harmonic classes via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..10 harmonic class
    let class_penalty = match class {
        0 => 60.0,           // 0-9: nearly unusable dead space
        1 => 35.0,           // 10-19
        2 => 18.0,           // 20-29
        3 => 8.0,            // 30-39
        4 => 3.0,            // 40-49
        5 => 0.0,            // 50-59: sweet spot
        6 => -2.0,           // 60-69
        7 => -4.0,           // 70-79
        8 => -5.0,           // 80-89
        _ => -6.0,           // 90+: nearly empty bin, very flexible
    };
    score += class_penalty;

    // Modulo arithmetic: residuals that are multiples of common item sizes (10s) are valuable.
    let mod10 = post_residual % 10;
    score += mod10 as f64 * 0.6; // prefer residuals aligned to decade grid

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    let is_new_bin = bin_residual == bin_capacity && post_residual < bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin when the current bin's post residual is decent.
        score += 20.0;
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Early in stream, opening bins is cheaper (more items to come to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual; slight penalty proportional to gap class
            let gap_class = (next_item_size - post_residual) / 20;
            score += gap_class as f64 * 2.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins first keeps balance).
    score += (mean_residual - post) * 0.15;

    // Slight preference for tighter fits when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead". Penalize them hard.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        // The smaller (more useless) the gap, the bigger the penalty.
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // consolidation is favored, so slightly reward filling existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= pressure * 2.0;
    }

    // Lookahead coupling: if the next item would fit in the post-residual,
    // this placement keeps the bin productive; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If next item cannot use the leftover space and leftover is dead,
    // penalize extra (chaining dead space).
    if next_item_size > post_residual && (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate handling: a fresh bin leaves 100 - item_size residual,
    // which is usually generous and reusable. Give it a mild handicap so that
    // decent existing fits win, but it still beats dead-space placements.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Large items leave small residuals in a new bin — mildly discourage.
        if item_size > 60 {
            score += 6.0;
        }
    }

    // Slight stream-position term: late in the stream, tightening matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-chain: next item exactly fills this bin.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, reward proportionally to how well it fills post residual.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
            // Penalize leftover after the hypothetical next placement.
            score += 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot follow: penalize dead space creation.
            score += 0.4 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Prefer bins whose residual is already below average (compact them).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for leaving tiny unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in the stream, be more willing to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Prefer tighter fits overall: perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect pairing: post_residual exactly matches next item.
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are used only when needed.
        score += 30.0;
        // If current bin would leave a large unusable gap, new bin becomes attractive.
        if post_residual > 0 && post_residual < item_size.min(30) {
            score -= 25.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer bins below mean residual (spread load evenly, keep large gaps alive).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // Many open bins: favor filling existing ones harder.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - 0.5 * norm_pr * progress * progress;
    score += 3.0 * poly;
    // Reward tight fits, more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 + progress) * 2.0;
    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= 0.5 * (1.0 - (pr - nx) / cap) * progress;
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - norm_pr);
    }
    // Mild preference for consolidating among many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;
    // Deviation from mean residual: prefer bins close to mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 1.5 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post residual: small dead space is fine,
    // mid-range dead space is worst (unusable for typical items).
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,
        1..=10 => -40.0,               // nearly perfect: great
        11..=20 => 30.0,               // dead zone: hard to fill
        21..=34 => -20.0,              // fits small items (10..20)
        35..=49 => 15.0,               // awkward mid gap
        50..=100 => -30.0,             // still half-capacity: reusable
        _ => 0.0,
    };
    score += class;

    // Modulo coupling: post_residual divisible by small item sizes is
    // more likely to be filled later (harmonic classes mod 10).
    if pr % 10 == 0 {
        score -= 25.0;
    } else if pr % 5 == 0 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how snugly
            score -= 20.0 + 0.5 * (pr - next_item_size) as f64;
        } else {
            // next item will NOT fit here: penalize, this bin strands us
            score += 35.0;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        // but if it creates a nasty dead zone, soften the reward
        if pr > 0 && pr < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate: penalize opening a new bin mildly; scale by
    // stream progression (late in the stream, prefer consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 60.0 * progress;
        // but if existing bins all have tiny residuals, new bin is fine
        if mean_residual < item_size as f64 * 0.5 {
            score -= 90.0;
        }
    }

    // Prefer bins with residual close to the item (tight fit) via
    // integer-division threshold on bin_residual.
    let fit_tightness = bin_residual / item_size.max(1);
    if fit_tightness == 1 {
        score -= 15.0; // item fills most of the bin
    } else if fit_tightness >= 5 {
        score += 10.0; // item tiny relative to bin: wasteful
    }

    // Mean residual coupling: placing into a bin far below the mean
    // residual balances the fleet.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never be reused are very costly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Mid-size awkward gaps (10..=20) are mildly penalized.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation.
    let pressure = open_bins_count as f64 * 0.15;
    score += pressure;

    // New-bin candidate handling: empty bin gets a moderate default score,
    // reduced when current bins are nearly full (mean residual low) so a
    // fresh bin is preferred over crushing a large residual.
    if bin_residual == bin_capacity {
        score = 45.0 + pressure;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        // If the next item could use the leftover of this bin, discourage new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Favor bins whose leftover can host the lookahead item.
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover too small for next item: penalize as dead space.
        score += 10.0;
    }

    // Early in stream, slightly prefer spreading into new bins to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let diff = (post_residual as f64 - nr).abs();
        if diff <= 5.0 {
            score -= 60.0 - diff * 4.0; // near-exact chain fit
        } else if post_residual as f64 >= nr {
            score -= 10.0;
        } else {
            // next item can't chain here; penalize wasted space
            score += diff * 0.5;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin before opening a new bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 25.0;
        // new bin is attractive only if no good chain fit exists anywhere
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() > 10.0 {
            score += 5.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 {
        let dead = post_residual as f64;
        // dead space below the smallest plausible item is wasted
        if dead < 10.0 {
            score += 8.0 * (10.0 - dead);
        }
        // usable leftover bonus: leftover close to common item sizes
        if dead >= 10.0 && dead <= 50.0 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Global state: prefer filling bins with large residuals when many bins are open.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 0.05 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be pickier about tight fits; late, just fill.
    score *= 1.0 + 0.3 * (1.0 - t);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 45.0 - 20.0 * desperation + 0.1 * item_size as f64;
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 10.0; // impossible here anyway, shouldn't happen
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: reward small post-residual, with quadratic sharpening
    let mut score = pr + 60.0 * norm_pr * norm_pr * cap;

    // Smooth interaction: as stream progresses, penalize residual more (bin consolidation pressure)
    score *= 1.0 + 0.8 * progress * (1.0 - norm_pr);

    // Penalize post-residual that wastes space relative to remaining item sizes
    let waste_gap = pr - nxt;
    if waste_gap > 0.0 {
        score += 0.35 * waste_gap * (0.5 + progress);
    }

    // Reward leaving room for the next item (smooth sigmoid-like coupling)
    if nxt > 0.0 {
        let fit_next = (pr - nxt).max(0.0);
        score -= 0.5 * fit_next * (1.0 - progress);
    }

    // Last-chance bonus: few fitting bins -> strongly favor using this bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    score += 0.1 * (pr as f64 - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: penalize opening new bins early, allow later when residuals are tight
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64).sqrt();
        if pr > nxt && nxt > 0.0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50

    // Small post_residual classes are highly usable by small items -> reward them.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0; // nearly full, minimal waste
    } else if post_residual < quarter {
        score -= 8.0; // still tight
    } else if post_residual == quarter {
        score -= 15.0; // harmonic quarter class: small items fit exactly
    } else if post_residual == half {
        score -= 12.0; // harmonic half class: very reusable
    } else if post_residual <= half {
        score += 5.0; // awkward middle zone
    } else {
        score += 10.0; // large residual means item was small relative to bin
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 align with item granularity.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Penalize residuals in dead zones (11..19 style slivers where few items 10..80 fit well)
    if post_residual % 10 != 0 && post_residual < 20 {
        score += 7.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // exact harmonic match with next item
            if next_item_size == post_residual {
                score -= 18.0;
            }
            // next item leaves a harmonic class again
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 6.0;
        }
        // If next item is huge, prefer keeping a big residual bin for it
        if next_item_size > half as u32 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well (large item, poor fits).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: reusing bins is usually better.
        score += 45.0;
        // But if the item is huge and no open bin has enough room anyway, opening is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins with low mean residual -> consolidation preferred.
        if mean_residual < 0.25 * cap {
            score += 10.0;
        }
    }

    // Slight preference for tighter existing bins when many bins are open.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead gap is worthless
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // marginal gap, only fits smallest items
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: fully packed bin
    }

    // Reward bins whose post_residual can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // post-residual too small for next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 45.0 + 25.0 * progress + (open_bins_count as f64) * 2.0;
    } else {
        score -= (open_bins_count as f64) * 1.5;
    }

    // Prefer bins tighter than the current mean residual (good fits).
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64 * (30.0 + 60.0 * t);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * (1.5 + t);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    }
    // If next item would leave a tiny unusable gap, penalize.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 15 {
            score += gap as f64 * 0.8;
        }
    }

    // Compare against global mean residual: prefer bins below mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Many open bins: discourage spreading; few open bins: allow opening new ones.
    score += open_bins_count as f64 * 0.6;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals are large and item is big.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        score += 35.0 - item_size as f64 * 0.2 - mean_residual * 0.15 - scarcity * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly non-linear (quadratic dead-space penalty)
    let mut score = pr + 20.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, waste matters less; late, tight fits (small post_residual) rewarded.
    let coupling = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score += 15.0 * coupling * pr_norm;
    score -= 10.0 * progress * progress * (1.0 - pr_norm);

    // Last-chance bonus: strongly prefer the only fitting bin, scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalty when many bins fit (spread items out rather than fragment one bin)
    if fitting_bins_count > 1 {
        score += 3.0 * ((fitting_bins_count - 1) as f64).ln();
    }

    // Lookahead: reward if next item fits in post residual (smooth sigmoid-like term)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = (pr - ns).max(0.0) / cap;
        let tightness = 1.0 - (ns / cap);
        score -= 8.0 * fits_next * tightness;
        // penalize leaving residual that is awkwardly close to next item size
        let gap = (pr - ns) / cap;
        score += 6.0 * (-40.0 * gap * gap).exp() * (1.0 - progress);
    }

    // Prefer filling bins with low mean residual (avoid many half-empty bins)
    score += 2.0 * (mean_residual / cap - pr_norm).abs();

    // Slight preference for using existing bins over opening new ones early
    score += 1.0 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 creates discrete dead-space bands.
    let post_class = (post_residual % 10) as f64;
    score += post_class * 1.7;

    // Integer-division thresholds: small post_residuals are near-perfect packings.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 30.0;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize leaving a mid-range residual
            // that is too small to be useful (dead space band 15..40).
            if post_residual >= 15 && post_residual <= 40 {
                score += 15.0;
            }
        }
    }

    // New-bin candidate handling: only attractive when open bins are all poor fits
    // (large mean residual spread) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread = (mean_residual - post_residual as f64).abs();
        // Fresh bin baseline: slightly worse than a good fit, better than a bad one.
        score = 55.0 - progress * 10.0 - spread * 0.5;
        // A brand-new bin trivially fits any next item; small lookahead credit.
        if next_item_size > 0 {
            score -= 6.0;
        }
    }

    // Mild penalty for accumulating too many open bins with large residuals.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if no future item (min size 1) can plausibly use it well;
    // gaps below 10 are almost always wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 4.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 25.0; // discourage abandoning usable bins
        }
        // Late in the stream, reusing bins matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Open-bin pressure: prefer packing into fewer bins.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: reward leaving a gap that fits the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 8.0; // gap too small for next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match bonus: next item fits with small waste after this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }

    // Penalize placing the next item now if it would NOT fit afterwards (bad chaining).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Small dead space is worse than large dead space relative to next item.
        let dead = (next_item_size - post_residual) as f64;
        score += 10.0 + dead.min(40.0);
    }

    // Reward packing into bins with residual below mean (tighter bins first),
    // penalize wasting large-residual bins on small items.
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 8.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when this item is huge relative to capacity
    // or the stream is early and many bins are still to come.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = item_size as f64 / bin_capacity as f64;
        score += 45.0;                       // base penalty for opening a new bin
        score -= tight_fit * 40.0;           // huge items justify fresh bins
        score -= (1.0 - progress) * 15.0;    // early stream: fresh bins cheaper
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;                   // fresh bin also fits the next item
        }
    }

    // Mild penalty for leaving awkward mid-range residuals that few items fit.
    if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Dead-space penalty: residuals that are too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect two-item packing (item + next fills bin exactly).
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // alternatives exist or the stream is late (few chances to refill it).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 80.0 * progress;
        // If the current bin fits well, opening a new bin is wasteful.
        if bin_residual >= item_size && fitting_bins_count >= 1 {
            score += 20.0;
        }
    }

    // Prefer filling bins whose residual deviates below the mean (consolidate space).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Mild preference for bins with larger residual when many bins are open
    // (keep small-residual bins for small future items).
    if open_bins_count > 4 {
        score += 0.05 * (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr / cap;
    // reward tight fits more as stream progresses
    score -= (1.0 - pr / cap).powi(3) * (0.5 + progress);
    // penalize very small dead space (unusable slivers)
    if pr > 0.0 && pr < 10.0 {
        score += 5.0 * (10.0 - pr) / 10.0;
    }
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 1.5 * (n / cap);
        } else if n > 0.0 {
            score += 0.8 * (1.0 - pr / n.min(cap));
        }
    }
    // last chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }
    // new-bin candidate: penalize mildly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 1.0 + 0.5 * (1.0 - progress);
    }
    // prefer filling bins with larger residuals among many open bins
    score += 0.3 * (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0) / 5.0;
    // smooth coupling with mean residual deviation
    score += 0.2 * ((pr - mean_residual) / cap).powi(2);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum plausible item size are worthless.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits: post_residual close to zero but not dead space.
    if post_residual == 0 {
        score -= 80.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 45.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: it's likely dead space.
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to pressure and mean residual.
        score += 30.0 + pressure * 4.0 + mean_residual * 0.5;
    } else {
        // Filling existing bins is favored slightly more as pressure grows.
        score -= pressure * 0.5;
    }

    // Mild preference for bins with residual close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: this bin's post-residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match for the lookahead item (post_residual slightly above next item).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 200.0 * (1.0 - slack / 10.0);
        }
    }
    // Penalize leaving dead space below the smallest possible item (1..=100 unknown range, use small threshold).
    if post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    }
    // Compare against mean residual: prefer bins tighter than average (good packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for opening a new bin early in the stream (spread load),
    // fading as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if post_residual is large and lookahead fits.
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size { 50.0 } else { 0.0 };
        score += 20.0 * (1.0 - progress) - lookahead_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving small unusable gaps (dead space < smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual,
    // penalize if the post residual is awkward relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual as u32 {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; slight bonus for using this bin now
            score -= 6.0;
        } else {
            let leftover = post - nxt;
            if leftover < 10.0 {
                score += 12.0; // creates dead space for the next item
            } else {
                score -= 8.0 * (nxt / post.max(1.0));
            }
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, keep bins flexible (favor balanced residuals);
    // late in the stream, prioritize closing bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let ideal_post = 0.5 * cap * (1.0 - t);
    score += 0.15 * (post - ideal_post).abs();

    // Global state: if many bins are open, discourage fragmentation (prefer tight fits
    // over spreading); if few bins, opening new ones is cheap.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 0.8 * open_pressure * (post / cap);

    // Mean-residual coupling: prefer bins whose residual is below the mean (more filled),
    // encouraging consolidation into already-loaded bins.
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((bin_res - mean_residual) / cap);
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base penalty so a new bin is chosen only when existing bins score badly.
        score += 15.0 + 30.0 * desperation;
        // Early stream: fresh bins are fine; late stream: avoid opening new bins.
        score += 25.0 * t;
        // If next item is large, a fresh bin is valuable (room for pairing).
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic post-residual term with progress modulation
    let progress_poly = 0.5 + 2.0 * progress * (1.0 - progress) * 2.0;
    score += 0.35 * norm_pr * norm_pr * cap * progress_poly;

    // Penalize large residuals relative to mean residual (dead-space drift)
    let mean_norm = mean_residual / cap;
    score += 0.2 * (norm_pr - mean_norm).abs() * cap * (0.5 + progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_next = (pr >= n) as i32 as f64;
        let gap = ((pr - n).abs()) / cap;
        score -= 6.0 * fit_next * (1.0 - gap) * (1.0 + progress);
        score += 2.0 * gap * cap * (1.0 - fit_next) * (0.5 + progress);
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr) * (0.5 + progress);
    }

    // Scarcity pressure: fewer fitting bins -> favor this one mildly
    if fitting_bins_count > 0 {
        score -= 1.5 / fitting_bins_count as f64 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize opening fresh bins early, more later unless residual tiny
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
        if next_item_size as f64 > cap * 0.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Harmonic class of the post residual: residues modulo capacity fractions ---
    let pr = post_residual;
    // Class A: perfect fit -> huge reward
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: residual too small for the smallest plausible item
        if pr < 10 {
            score += 60.0; // unusable sliver
        }
        // Modulo arithmetic classes on post_residual
        let m8 = pr % 8;
        let m16 = pr % 16;
        // Residues that pair badly with common item sizes get penalized
        score += match m8 {
            0 => -25.0,          // divisible by 8: many item sizes fit exactly later
            1 | 3 | 7 => 12.0,   // odd awkward residues
            2 | 6 => 4.0,
            _ => 0.0,
        };
        if m16 == 0 {
            score -= 15.0;       // strongly divisible class
        }
        // Integer-division thresholds on post_residual (capacity fractions)
        let q = pr / 25; // 0..4 quarters of usable space
        score += match q {
            0 => 20.0,           // < 25 left: nearly dead
            1 => 5.0,
            2 => -5.0,           // half bin left: flexible
            _ => -10.0,          // roomy
        } as f64;
    }

    // --- Lookahead coupling: does next_item_size fit exactly into post_residual? ---
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0; // perfect chain
        } else if next_item_size <= pr {
            // Harmonic class: does next item divide into the residual cleanly?
            if next_item_size > 0 && pr % next_item_size == 0 {
                score -= 40.0;
            }
            score -= 10.0; // at least reusable
        } else {
            // next item cannot use this residual: residual quality matters more
            score += (pr as f64) * 0.15;
            if pr < next_item_size && pr < 10 {
                score += 40.0;
            }
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0; // strongly prefer using the only bin that fits
    }

    // --- New-bin candidate logic (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.55;
        // Prefer a new bin when the current fit leaves a bad harmonic class
        let fit_slack = bin_residual - item_size;
        if fit_slack < 10 {
            score -= 120.0; // placing here would create a sliver anyway
        }
        if next_item_size > 0 && next_item_size > fit_slack && fit_slack > 0 {
            score -= 50.0; // next item won't fit the would-be residual
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        // Many open bins with high mean residual: reuse instead of opening
        if mean_residual > cap * 0.4 && open_bins_count > 2 {
            score += 40.0;
        }
    }

    // --- Mild preference for tighter (fuller) bins overall ---
    score -= (bin_residual as f64 / cap) * 5.0;
    score -= (item_size as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // worst at post_residual = 1
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that the lookahead item can exactly fill.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 10.0; // lookahead cannot use this gap
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow it.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable when few bins are open or mean residual is fragmented.
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 15.0 + pressure * 8.0 - fragmentation * 20.0;
    } else {
        score += pressure * 2.0;
    }

    // Early in the stream, mildly prefer new bins to build diverse residual pools.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that end up nearly full.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if the NEXT item fits exactly into
    // the post residual (a chained perfect fit), mild reward if it fits at all.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 60.0;
            // Extra reward when the next item fills the remainder almost exactly.
            let chain_gap = post_residual - next_item_size;
            if chain_gap <= 5 {
                score -= 150.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize dead space
            // proportionally to how unusable the leftover is.
            score += (post_residual as f64) * 0.5;
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 100.0;
    }

    // Compare against mean residual: prefer bins with residual below the mean
    // (tighter bins) so loose bins stay available for larger future items.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin has a huge residual; make it
    // attractive only when no open bin offers a good (tight) fit.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin: moderate score.
        score = 50.0 + (bin_capacity as f64) * 0.1;
        // If many bins are open and one fits tightly, discourage a new bin.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 40.0;
        }
        // Late in the stream, prefer reusing existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Small penalty for very large items in nearly-empty bins to keep big
    // residuals available for medium items (fragmentation avoidance).
    if item_size >= 70 && bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
