pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress
    let mut score = post * (1.0 + progress * progress * 0.5);

    // Smooth non-linear coupling: residual^2 interaction with progress
    score += 30.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits with smooth exponential term
    score -= 25.0 * (-(1.0 - norm_post).max(0.0) * 4.0).exp() * (1.0 - progress);

    // Penalize leaving residual that neither fits the next item well nor is tiny
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0) / cap;
        score += 20.0 * gap * (1.0 + norm_next) * (1.0 - progress * 0.5);
        // Bonus if post residual exactly accommodates next item (smooth)
        let fit = (post - next_item_size as f64).abs() / cap;
        score -= 15.0 * (-fit * 10.0).exp();
    }

    // Last-chance bin: smooth bonus when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 10.0 * scarcity * (1.0 - norm_post);

    // Deviation from mean residual: prefer bins below mean (fill fuller bins first)
    score += 0.3 * (mean_residual - post);

    // New-bin candidate: smooth penalty scaled by how many open bins exist
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64 * (0.5 + progress) + 40.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space classes
    // Small post-residuals (< smallest item) are dead space -> penalize, but
    // post_residual == 0 already rewarded above.
    let small = post_residual < 10 && post_residual > 0;
    if small {
        score += 40.0;
    }

    // Modulo classes on post_residual relative to capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    if post == quarter || post == half || post == 3 * quarter {
        score += 15.0; // large chunks are reusable; prefer leaving them? Actually prefer using them -> reward elsewhere
    }
    // Reward bins whose residual is close to next item size (lookahead fit)
    if next_item_size > 0 && post >= next_item_size {
        let slack = post - next_item_size;
        // harmonic / integer-division thresholds on slack
        let cls = slack / 5; // coarse classes
        score -= (5.0 - cls as f64).max(0.0) * 8.0;
    }
    // Penalize if next item cannot fit here (it will need another bin anyway)
    if next_item_size > 0 && post < next_item_size && post > 0 {
        score += 10.0;
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer fuller bins generally (tight fit): reward small post_residual
    score -= (bin_capacity - post) as f64 * 0.3;

    // Prefer tight fit relative to item: exact-ish fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // New-bin candidate: make it attractive only when residual is small/dead
    if bin_residual == bin_capacity {
        // base penalty so we prefer existing bins, but relax late in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 - 10.0 * progress;
        // if next item is large and current item small, new bin keeps big space
        if next_item_size > 0 && next_item_size > post + item_size {
            score -= 5.0;
        }
        // avoid new bin when many bins open already
        score += open_bins_count as f64 * 0.5;
        // dead-space trap: if only fitting bin leaves tiny residue, allow new bin
        if fitting_bins_count == 1 && small {
            score -= 25.0;
        }
    }

    // Mean residual coupling: if this bin's residual far below mean, it's an outlier -> use it
    if (bin_residual as f64 - mean_residual).abs() > 30.0 {
        score -= 5.0;
    }

    // Integer-division threshold: post_residual in (0,10) unusable unless exact 0
    if post > 0 && post / 5 == 0 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

