    // A residual gap is "dead" if no plausible future item (1..=100) can use it well;
    // gaps below 10 are almost certainly wasted, gaps 10..30 are risky.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize placements that leave lots of space behind when bins are plentiful).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins;
    // late in the stream, be strict about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // New-bin candidate handling: an empty bin should only win when the fit
    // into open bins is poor. Give it a moderate baseline (post_residual = capacity)
    // plus a penalty that existing good fits can overcome.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if many bins are open and mean residual is high, opening new bins
        // is worse; add extra penalty.
        if open_bins_count > 4 && mean_residual > 40.0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
