        score -= 10.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly anywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins early and when open bins are roomy.
        score += 18.0 + 25.0 * pressure + 10.0 * (1.0 - progress);
        // If item is huge and barely fits a new bin, new bin is efficient (no waste).
        if item_size >= 80 {
            score -= 20.0;
        }
        // Many open bins with low mean residual: consolidation is better.
        if open_bins_count > 3 && mean_residual < 30.0 {
            score += 10.0;
        }
    }

    // Slight preference for bins with residual close to mean (balanced packing).
    score += 0.08 * ((bin_residual as f64 - mean_residual).abs());

    // Mild time decay: late in stream, prefer filling bins fully.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let base = post_residual as f64;

    // Non-linear polynomial coupling: (1 - r^2) peaks reward for tight fits,
    // modulated by stream progress.
    let tightness = 1.0 - r * r;
    let progress_coupling = (1.0 - progress) * r * r + progress * tightness;

    let mut score = base * (1.0 + 0.5 * progress_coupling);

    // Reward near-perfect fills smoothly.
    score -= 40.0 * (1.0 - r).powi(6);

    // Penalize dead space relative to mean residual.
    score += 0.3 * (r * bin_capacity as f64 - mean_residual).max(0.0);

    // Last-chance bonus (smooth, not piecewise).
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * tightness;

    // Lookahead: penalize if next item won't fit the post-residual.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.4 * gap;
        // Reward if next item fits snugly.
        let snug = 1.0 - ((next_item_size as f64 - post_residual as f64).abs() / bin_capacity as f64);
        score -= 10.0 * snug * snug * tightness;
    }

    // Mild penalty for bin proliferation early in the stream.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (capacity fractions) ---
    let pr = post_residual;
    // Class boundaries at 1/4, 1/2, 3/4 of capacity via integer division
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = (bin_capacity * 3) / 4;

    // Dead-space penalty: leftover in (0, 10) is nearly useless
    if pr > 0 && pr < 10 {
        score += 40.0;
    } else if pr < quarter {
        score += 12.0;
    } else if pr < half {
        score += 4.0;
    } else if pr < three_quarter {
        score -= 6.0;
    } else {
        score -= 2.0;
    }

    // Perfect fill reward
    if pr == 0 {
        score -= 100.0;
    }

    // --- Modulo arithmetic on post_residual: small remainders mod 10
    // are "harmonically compatible" with typical item granularities ---
    let m = pr % 10;
    if m == 0 {
        score -= 3.0; // divisible leftover, easy to refill later
    } else if m >= 1 && m <= 3 {
        score += 2.5; // awkward sliver class
    }

    // --- Lookahead coupling: does the next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic class match: next item lands in same residue class
            let class_match = (next_item_size % 10) == (pr % 10);
            if class_match {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here: penalize more if leftover is tiny
            if pr < 10 {
                score += 8.0;
            } else if pr < quarter {
                score += 3.0;
            } else {
                score -= 1.0;
            }
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling: opening a fresh bin is only attractive
    // when current item is large and mean residual is fragmented ---
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        // Prefer new bin when existing residuals are small and item is big
        score += 25.0 * fragmentation - (item_size as f64) * 0.2;
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // --- Stream progression: late in the stream, consolidate more aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / cap);

    // Slight tie-breaker: prefer bins with residual close to item (tight fit)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item
    // (<= ~10% of capacity) are almost certainly wasted.
    let dead_threshold = 0.10 * cap;
    if (post_residual as f64) <= dead_threshold {
        score += 25.0 * (1.0 - (post_residual as f64) / dead_threshold.max(1.0));
    }

    // Reward tight fits: post_residual small relative to capacity.
    score -= 30.0 * (1.0 - (post_residual as f64) / cap);

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (next_item_size as f64 / cap);
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }
    // Penalize if post_residual is too small for the lookahead item (dead space ahead).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Pressure from number of open bins: prefer reusing existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize unless the current bin would leave large dead space
    // or the bin's residual was already very tight.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * open_bins_count as f64;
        // Allow opening a new bin when the item is large (would leave little residual anyway).
        if item_size as f64 >= 0.8 * cap {
            score -= 14.0;
        }
    }

    // Mild preference to fill bins below mean residual (balancing).
    score -= 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // 2-step lookahead: strong reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize if next item cannot fit in post_residual (dead space for lookahead).
        if next_item_size as u32 > post_residual {
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But allow new bin if item is huge relative to mean residual spread.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 45.0;
        }
    }

    // Slight preference late in stream to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < next_item_size.max(10) && next_item_size > 0 {
        // Residual can't fit the lookahead item -> potential dead space.
        score += 8.0;
    }

    // Perfect-fit bonus: bin almost exactly consumed.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose post-residual matches next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - slack / (bin_capacity as f64));
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual < 10 {
            score -= 6.0; // still fine, bin gets closed out
        }
    }

    // Many open bins: discourage spreading into loose bins; prefer consolidation.
    if open_bins_count > 3 {
        let dispersion = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dispersion;
    }

    // Time horizon: late in the stream, be greedy about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // New-bin candidate: opening a bin is only attractive when no open bin
    // fits well or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (bin_capacity as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of a fresh bin, discounted when item is large or bins scarce.
        score = bin_capacity as f64 - 20.0 * pressure - 15.0 * scarcity - 8.0 * progress;
        // If an existing bin would be nearly perfect, keep the new bin unattractive.
        if post_residual_of_best_proxy(item_size, bin_capacity) < 5 {
            score += 40.0;
        }
    }

    score
}

fn post_residual_of_best_proxy(item_size: u32, bin_capacity: u32) -> u32 {
    // Proxy: assume a typical open bin holds ~half capacity; if the item
    // would leave a tiny remainder there, opening a new bin is wasteful.
    let typical_residual = bin_capacity / 2;
    if item_size <= typical_residual { typical_residual - item_size } else { bin_capacity }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual in [0,1]
    let x = post / cap;

    // Smooth polynomial coupling: penalize residual quadratically,
    // modulated by stream progress (later in stream -> waste matters more).
    let mut score = x * (1.0 + 2.0 * progress) + 3.0 * x * x * (0.5 + progress);

    // Tight fits are rewarded with a smooth bonus term.
    let tightness = 1.0 - x;
    score -= 2.5 * tightness * tightness * (1.0 - progress);

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post < 10.0 && post > 0.0 {
        score += 8.0 * (1.0 - post / 10.0) * (1.0 + progress);
    }

    // Lookahead: if next item fits in post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fill = nxt / post.max(1.0);
            score -= 1.5 * fill * fill;
        } else {
            score += 1.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - 0.5 * progress);
    }

    // Mild preference for keeping bin count low; smooth in open_bins_count.
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: favor bins close to the mean for balance.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // New-bin candidate: make it attractive only when open bins would waste space.
    if bin_residual == bin_capacity {
        let waste = (bin_residual as f64 - item_size as f64) / cap;
        score = 5.0 + 6.0 * waste * waste + 2.0 * progress;
        if fitting_bins_count == 1 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of 10
    // are more reusable by typical item sizes, so reward them.
    let residue_class = (post_residual % 10) as f64;
    let class_bonus = if residue_class == 0.0 {
        -8.0
    } else if residue_class <= 2.0 || residue_class >= 8.0 {
        -3.0
    } else {
        2.0
    };
    score += class_bonus;

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward scaled by how tight the fit is.
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 12.0 * tightness;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // Harmonic class of leftover after the hypothetical next placement.
            let chained_left = post_residual - next_item_size;
            let chained_class = (chained_left % 10) as f64;
            score -= 6.0 * (1.0 - chained_class / 10.0);
            if chained_left < 10 {
                score += 8.0;
            }
        } else {
            // Next item cannot follow here; slight penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the stream is young and few bins are open, or the current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        // Penalize new bins more as stream progresses and bins accumulate.
        score += 35.0 + 20.0 * progress + 1.5 * openness;
        // But if mean residual across open bins is tiny, new bin deserves a chance.
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Fractional capacity alignment: reward post_residuals that are large
    // fractions of capacity (more usable space).
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * frac;

    // Mild pressure to consolidate: prefer bins below mean residual
    // (fills the emptiest bins first, keeping tight bins for small items).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Integer-division threshold: bins whose residual halves cleanly
    // (post_residual / 2 >= typical item) are flexible.
    if post_residual / 2 >= 20 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead" — penalize them heavily.
    let dead_threshold = 10u32; // smallest item size possible
    if post_residual < dead_threshold && post_residual > 0 {
        score += 200.0 * (dead_threshold - post_residual) as f64;
    }

    // Non-linear penalty for tight-but-wasteful fits: a small but usable
    // gap is worse than a clean fill or a comfortable remainder.
    if post_residual > 0 && post_residual <= 20 {
        score += 30.0 * (20 - post_residual) as f64;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, spreading is cheap.
    let bin_pressure = open_bins_count as f64 / (mean_residual.max(1.0));
    score += bin_pressure * 5.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer bins that keep flexible space.
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 40.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to the known next item.
            score += 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual. Only make
    // it attractive when existing bins would be badly fragmented or when
    // the item barely fits anywhere. Penalize the fresh bin by default via
    // its large post_residual, but give a discount when current mean
    // residual is small (open bins nearly full).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // If open bins are nearly exhausted, a new bin is fine.
        if open_bins_count > 0 && mean_r < item_size as f64 * 1.2 {
            score -= 60.0;
        } else if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // Existing bins fit: discourage opening a new one unless the
            // fit would leave tiny dead space.
            score += 25.0;
        }
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (long stream ahead, flexibility matters); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-item fill bonus: item + next item exactly fills this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-perfect lookahead: next item fits snugly into post_residual.
    if next_item_size > 0 {
        let slack = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + slack * 0.1);
    }

    // Penalize large dead space beyond what the next item could use.
    if next_item_size > 0 && post_residual > next_item_size {
        let dead = post_residual - next_item_size;
        score += dead as f64 * 0.3;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable gaps (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists (late stream or many bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 10.0 * progress;
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight;

    // Penalize small dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for large post_residual
            score += 0.05 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones.
    score += 0.4 * open_bins_count as f64;

    // Mean residual context: if this bin's residual is far below mean, it's a poor fit target.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev.abs();

    // New-bin candidate handling: empty bin gets a penalty that shrinks over time
    // and when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_pen = 30.0;
        if fitting_bins_count <= 1 {
            new_bin_pen -= 15.0; // no real alternative
        }
        // If item is large relative to capacity, new bin is more attractive.
        new_bin_pen -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // Late in stream, opening bins is cheap.
        new_bin_pen *= 1.0 - 0.5 * progress;
        score += new_bin_pen;
    }

    // Slight preference for bins with larger residual (more room to spare) among open bins.
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize wasted residual, scaled by a smooth progress-dependent exponent
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear coupling: residual squared normalized, modulated by stream progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Reward tight fits (small post_residual relative to item) with smooth term
    score -= 20.0 * norm_item * (1.0 - norm_pr).powi(2);

    // Lookahead: if next item fits in post_residual, reward this bin smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - fit_quality) * (1.0 + progress);
    }

    // Penalize leaving residual that nothing useful can use, smoothly
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 4.0 * gap * gap * cap * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly reward using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open (consolidation pressure)
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Smooth deviation from mean residual: prefer bins near/below mean residual
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap - 2.0 * dev * cap * progress;

    // New-bin candidate: discourage opening a new bin unless residual waste would be severe
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual % 10) as f64;

    // Reward tight fits strongly (small dead space)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else {
        score += class * 0.5; // penalize awkward leftover classes
    }

    // Harmonic divisibility: residual that can be tiled by common item sizes is good
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize wasting large residual
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residuals are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr).abs();
        if mean_residual < 15.0 || open_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 10.0 + fragmentation * 0.2 + progress * 5.0;
        }
    }

    // Mild preference for fuller bins relative to fleet mean
    score -= (cap - pr - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0; // unusable sliver
    }
    // Penalize gaps too small for the known next item (lookahead-aware dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 200.0 + (next_item_size as f64 - post_residual as f64) * 5.0;
    }
    // Reward tight fits (small useful post_residual)
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    }

    // Slight preference for fuller bins relative to mean residual
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Late-stream: prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post-residual exactly matches the next item size
    // (perfect 2-step chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: this creates a dead-end chain; penalize.
        score += 25.0;
    }

    // Penalize tiny unusable dead space (< 10, the minimum useful item size in
    // classic streams, but keep general: small residual = wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer bins tighter than the mean residual (they are "fuller").
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Early in the stream, allow opening bins more freely (better long-run packing);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses.
        score += 30.0 * (0.5 + progress);
        // But if no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Slight preference for bins with larger residual when many bins are open
    // (consolidate usage, close out bins sooner).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio bonus
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * fill * 40.0;

    // Penalize small unusable dead space strongly (waste shaping)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving medium gaps
            score += 6.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        // prefer new bin when mean residual is low (bins mostly full) or few bins open
        score += 55.0 * pressure + 20.0 * (1.0 - crowding);
        // late in stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    } else {
        // slight preference for fuller bins among open ones
        score -= 8.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Discourage scattering across many open bins when mean residual is high
    score += (open_bins_count as f64).ln() * 2.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: post residual, mildly super-linear (dead space penalty grows quadratically)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: as stream progresses, prefer tighter fills (larger item fraction)
    let fill_ratio = item / cap;
    score -= 30.0 * progress * fill_ratio * fill_ratio;

    // Interaction of post-residual with progress: late stream punishes leftover space more
    score += 25.0 * norm_pr * progress;

    // Mean residual coupling: prefer bins whose residual deviates below mean (consolidation)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * (1.0 - progress) - 10.0 * dev * progress;

    // Lookahead: reward residual that can hold next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 20.0 * (1.0 - progress) * (nxt / cap);
        } else {
            score += 12.0 * (1.0 - (pr / nxt)) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only for genuinely poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits, tiny dead space, useful chunks.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if pr <= 5 {
        score -= 30.0; // near-perfect, dead space negligible
    } else if pr >= 90 {
        score -= 45.0; // essentially fresh bin
    } else {
        // Classify leftover by integer division into harmonic bands of 10
        let band = pr / 10; // 1..9
        match band {
            1 | 2 => score += 8.0,   // 10-29: awkward sliver
            3 | 4 => score += 2.0,   // 30-49: usable for small items
            5 | 6 => score -= 6.0,   // 50-69: good chunk
            _ => score -= 3.0,       // 70-89: large chunk
        }
        // Fractional penalty: penalize leftovers that are not multiples of 5
        // (common item sizes align better with 5-granularity)
        if pr % 5 != 0 {
            score += 2.5;
        }
        if pr % 10 != 0 {
            score += 1.5;
        }
    }

    // Lookahead: reward if the next item fits the post-residual (chained placement)
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 14.0;
            // Extra reward for tight chain: next item nearly fills remainder
            let gap = pr - next_item_size;
            if gap <= 5 {
                score -= 10.0;
            } else if gap <= 15 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; penalize if we leave a moderate orphan chunk
            if pr >= 20 && pr <= 60 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation into existing bins
    let open_f = open_bins_count as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= open_f * 1.2 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins tighter than average (best-fit flavor)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 20.0;

    // New-bin candidate: only attractive when current leftovers are all poor fits
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and open count
        score += 35.0 + 20.0 * progress + open_f * 0.5;
        // If next item is huge, a fresh bin is relatively safe
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Tight fit reward: item fills most of the current residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.85 {
        score -= 12.0;
    } else if fill > 0.6 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (<= 12) are nearly worthless — penalize hard.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small-but-usable gaps: mild penalty to discourage squandering space.
        score += 8.0;
    }

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild tie-break toward tighter fits is
        // already captured by post_residual; add small pressure to consolidate.
        score -= 2.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., this call is the empty-bin candidate and fits are scarce).
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            // Opening a fresh bin is reasonable; keep score moderate so a
            // genuinely bad fit in an existing bin loses to it.
            score = (bin_capacity - item_size) as f64 - 10.0;
        } else {
            // Plenty of fitting bins: make new bin clearly unattractive.
            score += 120.0;
        }
    }

    // Open-bins pressure: when many bins are open, discourage fragmenting
    // space further with mediocre fits; when few bins are open, be lenient.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln() * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item would fit snugly into this bin's post_residual,
    // reward; if post_residual is awkward relative to next item, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Next item cannot use the leftover: dead space ahead.
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins with residual below the mean
    // (tighter bins get used first, keeping loose bins flexible).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of next item into leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain (next item fills bin exactly) -> big reward.
        if gap == 0.0 {
            score -= 40.0;
        } else if gap <= 5.0 {
            score -= 20.0;
        } else {
            // reward proportional to how well next item consumes leftover
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill_ratio;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to dead space created.
        score += 5.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Penalize small unusable residuals relative to the mean residual of open bins.
    if post_residual > 0 {
        let frag = if post_residual < 10 { 1.0 } else { 0.0 };
        score += frag * 15.0;
        // Compare residual against mean residual: keeping residual near mean is fine,
        // creating much smaller residual than mean wastes future capacity.
        if (post_residual as f64) < mean_residual * 0.5 {
            score += (mean_residual - post_residual as f64) * 0.2;
        }
    } else {
        // Perfectly closed bin: strong reward.
        score -= 30.0;
    }

    // Last-chance bin (only fitting bin): avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize moderately so it's only chosen when fits are terrible,
    // but keep its raw residual attractive vs. highly fragmented bins.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in the stream, prefer reusing bins (fewer bins to close).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for filling larger-residual bins when many bins are open.
    score -= (bin_residual as f64) * 0.05 * (open_bins_count as f64 / 10.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that can never be filled by typical items (1..100).
    if post_residual > 0 {
        let dead = if post_residual < 1 { 0.0 } else { (post_residual as f64).ln() };
        score += 8.0 * dead;
    }

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: bonus if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Penalize placements that leave residual useless for the next item.
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make it less attractive
    // unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, opening bins is fine; late in the stream, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
        // If many bins are already open, discourage opening yet another.
        score += 3.0 * (open_bins_count as f64).sqrt();
    } else {
        // Mild consolidation pressure: prefer bins below mean residual (already partially filled).
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Slight preference for bins with larger residual when item is large (avoid fragmentation).
    if item_size > bin_capacity / 2 {
        score -= 0.2 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: penalize wasted residual, with progress-dependent curvature
    let mut score = norm_post * (1.0 + 2.5 * progress * progress);

    // Smooth non-linear coupling: quadratic residual term, stronger late in stream
    score += norm_post * norm_post * (3.0 + 4.0 * progress);

    // Reward tight fits via smooth bell around zero post-residual
    let tight = (-norm_post * 8.0).exp();
    score -= 6.0 * tight * (1.0 + progress);

    // Lookahead: reward if next item fits the post residual (smooth ratio)
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let ratio = (next_item_size as f64 / cap).min(1.0);
        score -= 4.0 * fits_next * (1.0 - ratio) * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Mild penalty for too many open bins relative to progress
    score += (open_bins_count as f64).ln1p() * 0.4 * (0.5 + progress);

    // Deviation from mean residual (smooth dispersion penalty)
    score += ((pr - mean_residual) / cap).abs() * 1.5;

    // New-bin candidate: make empty bins mildly unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" modular anchors.
    let post = post_residual;
    if post > 0 {
        // Reward exact quarter/half capacity anchors (dead space that is reusable).
        let anchors = [(0u32, -12.0), (25, -10.0), (50, -8.0), (75, -6.0), (100, -4.0)];
        for (a, r) in anchors.iter() {
            if post % 25 == *a {
                score += r;
                break;
            }
        }
        // Penalize tiny dead-space bands (unusable residuals).
        if post < 10 {
            score += 18.0;
        } else if post < 20 {
            score += 8.0;
        }
        // Integer-division harmonic class of post residual by 10.
        let class = post / 10;
        score -= (class as f64) * 1.5;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 6.0 + (next_item_size as f64) * 0.05;
        } else {
            // Next item won't fit here; penalize more if the miss is small (wasted opportunity).
            let miss = next_item_size - post;
            if miss <= 10 {
                score += 7.0;
            }
        }
        // Harmonic modulo coupling: next item aligns with post residual mod 25.
        if post > 0 && next_item_size % 25 == post % 25 && post >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer it only when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base; small penalty so a decent existing fit wins.
        score += 6.0;
        if post_residual >= 20 {
            score -= 4.0;
        }
        // Late in the stream, opening fresh bins is cheaper (less fragmentation risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 3.0;
    }

    // Crowd control: many open bins with high mean residual -> prefer consolidating.
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 2.0;
    }
    if open_bins_count > 8 {
        score -= (post_residual as f64) * 0.02;
    }

    // Tight-fit reward: item nearly fills the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 9.0;
    } else if fill > 0.75 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1..) are dead space; heavier penalty as the gap
    // shrinks below a "usable" threshold.
    let dead_threshold = 10.0f64; // smallest typical item size
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Non-linear penalty on tiny gaps (harsh on 1-3 unit leftovers).
    if post_residual > 0 && post_residual <= 3 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward post-residual that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 15.0;
        } else if (bin_residual as f64) >= next_item_size as f64 && (post_residual as f64) < next_item_size as f64 {
            // This placement destroys the ability to host the next item: penalize.
            score += 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and this candidate is a fresh empty bin.
    if bin_residual == bin_capacity {
        score += 25.0 + 6.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; later, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If mean residual across open bins is large, no reason to open a new bin.
        score += mean_residual * 0.8;
    } else {
        // Mild reward for using existing bins with high residual (reduces fragmentation).
        score -= (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Penalize leaving a residual just below a mid-range item size band,
    // which is a classic dead zone (e.g., residual 11..19 hard to fill).
    if post_residual >= 11 && post_residual <= 19 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strongly reward
        if post_residual == next_item_size {
            score -= 30.0;
        } else {
            // Reward closeness of post_residual to next item size
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        }
        // Penalize leaving residual that can neither fit next item nor is zero (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post residual)
        score += 0.0;
    }

    // Compare post_residual against mean residual: avoid creating outliers far below mean
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += 0.5 * mean_gap; // bin much emptier than average -> penalize waste
    } else {
        score -= 0.2 * (-mean_gap); // bin still relatively full -> mild reward
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item would fit perfectly in a fresh bin too, soften
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Early in stream: be more willing to open bins (flexibility), late: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * (1.0 - progress);
    }

    // Slight preference for fuller bins overall
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += 3.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: many open bins with slack -> prefer filling existing bins.
    let slack_pressure = mean_residual / cap;
    score += 5.0 * slack_pressure * (open_bins_count as f64).sqrt();

    // Time horizon: late in the stream, avoid opening new bins; early, allow exploration.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = 15.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias - 8.0 * progress;
    }

    // Prefer bins whose residual is close to item size (perfect packing pressure).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 6.0 * fit_gap;

    // Mild preference for bins with residual below mean (consolidate emptier space).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm * (1.0 - pr_norm)
        + 25.0 * pr_norm * pr_norm * pr_norm;

    // Smooth coupling of post-residual with stream progress
    score += 30.0 * pr_norm * progress * (1.0 - progress * 0.5);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let waste = pr - next_item_size as f64;
    if next_item_size > 0.0 as u32 as f64 && waste > 0.0 {
        let waste_norm = waste / cap;
        score += 20.0 * waste_norm * waste_norm * (1.0 - progress);
    }

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= 35.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Last-chance bin bonus: smooth sigmoid-like term
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + (progress - 0.5) * std::f64::consts::PI).sin().abs();
    }

    // Mean residual dispersion coupling (non-linear)
    let mr = mean_residual / cap;
    score += 12.0 * (mr - pr_norm) * (mr - pr_norm);

    // Mild preference for consolidating into fewer bins
    score -= 8.0 * (1.0 - pr_norm) / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction bucket it belongs to
    let item_class = item_size / 10;              // 0..10 harmonic class
    let post_class = post_residual / 10;          // residual class after placement

    // Reward placements where post_residual falls into a "usable" harmonic class,
    // i.e. post_residual can still host common item classes (multiples of 10).
    let usable = (post_residual >= 10) && (post_residual % 10 == 0);
    if usable {
        score -= 8.0;
    }

    // Penalize dead space: post_residual that is small but nonzero (1..10) is waste
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item: reward if next item fits the post-residual class
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into remaining class bucket
            let slack = post_residual - next_item_size;
            score -= (10.0 - (slack % 10) as f64) * 0.8;
            if slack == 0 {
                score -= 20.0; // chained perfect fit
            }
        } else {
            // next item cannot fit: penalize proportionally to overflow class
            let over = next_item_size - post_residual;
            score += (over / 10) as f64 * 6.0 + 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Modulo threshold on bin_residual: bins whose residual is a multiple of 25
    // represent clean quarter-capacity states; keep them tidy.
    if bin_residual % 25 == 0 && bin_residual > 0 {
        score -= 4.0;
    }

    // Large items (> half capacity) should go into bins with large residual
    if item_size > bin_capacity / 2 {
        score -= (bin_residual / 10) as f64 * 2.0;
    }

    // Small items early in the stream: keep big residual bins for big items
    let progress = step_index as f64 / total_items as f64;
    if item_class <= 3 {
        score += (bin_residual / 20) as f64 * (1.5 - progress);
    }

    // New-bin candidate: prefer keeping it closed unless current bin is crowded
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post_residual as f64).abs();
        score += 12.0 + mean_gap * 0.3 - (open_bins_count as f64).sqrt() * 2.0;
        if post_residual == bin_capacity {
            score += 5.0; // empty vs empty: slight extra penalty so real bins win ties
        }
    }

    // Mild pressure to consolidate: more open bins -> favor filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are toxic.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual < dead_threshold && post_residual > 0 {
        // Unusable sliver: penalize hard, scaled by how small the gap is.
        let tightness = (dead_threshold - post_residual) as f64 / dead_threshold as f64;
        score += 60.0 + 40.0 * tightness;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Sets up an exact fit for the lookahead item.
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual that can host the next item is valuable.
        score -= 15.0 * (post_residual as f64 / dead_threshold as f64).min(3.0);
    }

    // Large residual waste: leaving big gaps when item was small is fine (flexible),
    // but prefer tighter fills mildly: reward smaller post_residual generally.
    score += 0.05 * (post_residual as f64 - mean_residual).abs().signum()
        * (post_residual as f64 - mean_residual).abs();

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: opening a bin is wasteful unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Less pressure to open new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Open-bin pressure: many open bins -> consolidate into existing ones.
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 150.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space penalty relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer tight fits relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Slight bias toward already-opened bins over new bin candidate
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    // Penalize leaving large unusable fragments as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item of stream: just minimize post residual.
        score += 10.0;
    }

    // Prefer bins with below-average residual (keep big spaces for big items).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate handling: make empty bins attractive only when the
    // item is large relative to capacity or fits are scarce / late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let largeness = item_size as f64 / bin_capacity as f64;
        let pressure = 0.5 * scarcity + 0.5 * largeness + 0.2 * progress;
        score += 15.0 - 25.0 * pressure;
    }

    // Mild diversity pressure: many open bins -> consolidate into existing ones.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = post / cap;

    // Base: prefer small post-residual with smooth polynomial shaping
    let mut score = post + 6.0 * post_norm * post_norm * cap;

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, tighter packing matters more
    let progress_coupling = 8.0 * post_norm * (progress * progress * (2.0 - progress));
    score += progress_coupling;

    // Penalize large residuals that nothing else can use; reward near-perfect fits
    let dead_space = (post / (item_size.max(1) as f64)).ln_1p();
    score += 3.0 * dead_space * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - post_norm);
    }

    // Lookahead: reward if next item fits in the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - ((post - nxt) / cap)) * (1.0 + progress);
        } else {
            score += 2.0 * ((nxt - post) / cap);
        }
    }

    // Mild pressure to reuse crowded bin sets rather than proliferate bins
    score += 0.15 * (open_bins_count as f64).ln_1p() * post_norm;

    // Align with mean residual: bins far from mean get slight normalization
    score += 0.5 * (post - mean_residual).abs() / cap;

    // New-bin candidate: make it attractive only when residual is large and
    // existing bins are tight on average
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap - 12.0 * tightness * (1.0 + progress) - 5.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: bins whose residual lands on a "friendly" multiple of 10
    // are more reusable for future items (sizes 1..100 often cluster mod 10).
    let harmonic = post_residual % 10;
    score -= harmonic as f64 * 3.0;

    // Integer-division class of post_residual: coarse buckets of reusability.
    let class = post_residual / 10;
    score -= class as f64 * 2.0;

    // Lookahead coupling: reward when next item fits the post-residual exactly
    // or nearly; penalize when post-residual is just barely too small (dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 400.0; // chain of perfect fits
            } else {
                score -= 40.0 * (1.0 - slack as f64 / 50.0).max(0.0);
            }
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 60.0; // placing here would block the next item
        }
    }

    // Penalize tiny unusable residuals (dead space) unless item is large.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make empty bin moderately attractive only when
    // existing residuals are poor fits (item leaves awkward remainder).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when item is large and would leave big dead space elsewhere,
        // or late in the stream when spreading load reduces fragmentation.
        score -= 120.0 * (item_size as f64 / 100.0);
        score -= 100.0 * progress;
        score -= mean_residual * 0.5;
        if waste < 20.0 {
            score += 150.0; // item fits tightly somewhere already -> use it
        }
    }

    // Mild preference for filling fuller bins among equals.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest item (size 1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals too small for typical mid-range items (10..30).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones; with few bins, consolidation is cheaper.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score -= 15.0 * bin_pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Penalize
    // opening a new bin unless the current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        // Baseline competitiveness for a fresh bin.
        score = 100.0 - 15.0 * bin_pressure;
        // If the item fills a large chunk of a fresh bin, opening is attractive.
        if (item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
        // If next item is large, a fresh bin may serve it better.
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Lookahead coupling: if next item fits into the post_residual,
        // reward this placement strongly.
        if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
            score -= 35.0;
        }
        // If next item would NOT fit but would fit a fresh bin, mild penalty.
        if next_item_size > post_residual && next_item_size >= 50 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating favorably (using up
    // larger residuals) when overall residuals are high.
    if mean_residual > 50.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when leftover exactly matches next item,
    // penalize leftover that is unusable for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * diff;

        // Exact match for the next item is a strong signal.
        if post_residual == next_item_size {
            score -= 45.0;
        }

        // Leftover too small for the next item is dead space.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.35 * post_residual as f64;
        }
    }

    // Compare against mean residual of open bins: prefer bins that tighten
    // the residual distribution (avoid stragglers).
    let post = post_residual as f64;
    if post > mean_residual {
        score += 0.25 * (post - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating very small unusable fragments (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when current
    // bins would leave large dead space or are scarce.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            20.0
        };
        // Base cost of opening a new bin, reduced late in the stream or
        // when few bins are open.
        score = 55.0 - dead_space_penalty
            - 10.0 * (step_index as f64 / total_items.max(1) as f64)
            - 3.0 * (open_bins_count as f64).ln().max(0.0);
        // If only one bin fits, opening a new bin is wasteful.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: penalize large post_residual non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: strong incentive to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Dead space relative to next item: penalize waste.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
        }
    } else {
        // Last item: just minimize leftover.
        score -= 5.0;
    }

    // Global state: with many open bins, prefer consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * (2.0 + open_bins_count as f64).ln().max(1.0) * 5.0;

    // Mean residual coupling: when mean residual is small (bins mostly full),
    // opening a new bin is more acceptable; penalize new bins less then.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty, reduced when existing bins are tight.
        let mut new_bin_penalty = 30.0;
        new_bin_penalty -= (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        new_bin_penalty -= progress * 10.0;
        // If the item is large and few bins fit it, new bin is less bad.
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty.max(2.0);
    } else {
        // Existing bin: small bonus for matching mean residual (balance avoidance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic penalty on wasted space weighted by progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly later in the stream
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Interaction: dead space vs mean residual of open bins
    score += 10.0 * (pr - mean_residual) / cap * (1.0 + progress);

    // Last-chance bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 12.0 * fit_next * (1.0 - (pr - nx) / cap);
        score += 8.0 * (1.0 - fit_next) * (nx / cap);
    }

    // Mild pressure against proliferating bins early
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // New-bin candidate: penalize slightly unless current fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 - 55.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quarters of capacity
    let q = post_residual * 4 / bin_capacity; // 0..=3
    // Penalize leftovers that fall into "dead" classes (small unusable slivers)
    match q {
        0 => score += 25.0,               // nearly full bin: excellent, reward
        1 => score -= 8.0,                // small leftover: penalize moderately
        2 => score += 2.0,                // half-ish leftover: neutral-ish
        _ => score -= 4.0,                // large leftover: still useful
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with 10..80 items
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0;
    } else if m >= 7 {
        score += 5.0;
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the leftover class fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        // leftover remains usable: reward proportionally
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover becomes dead space relative to next item
        score += 12.0;
    }
    // Perfect pairing: leftover exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make it mildly unattractive unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        // early in stream, allow fresh bins more readily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Tightness reward: the fuller the bin becomes, the better
    score -= 10.0 * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
