    // Prefer bins that are already fairly full (small residual relative to capacity)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Penalize deviating from mean residual: keep residual distribution tight
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // typical residuals or no good fit exists; penalize opening new bins early.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        // If item is large and would leave small post residual, a fresh bin is fine
        if item_size >= 50 {
            score -= 20.0;
        }
        // Early stream: opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (bin_capacity as f64);
    score -= 40.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that is too small for any plausible item (below min size 1... keep general):
    if post_residual > 0 && post_residual < 10 {
