        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is already below the mean (consolidate fullness).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for bins with larger current residual when item is large.
    score -= (item_size as f64) * (bin_residual as f64) / (bin_capacity as f64) * 0.1;

