}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    score += 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= 15.0 * norm_item * norm_item * (0.5 + progress);

    // Reward bins whose post_residual matches the next item size (smooth kernel)
    if next_item_size > 0 {
        let diff = (pr - norm_next * cap) / cap;
        score -= 12.0 * (-8.0 * diff * diff).exp();
    }

    // Penalize scarce fitting options mildly; smooth in fitting_bins_count
    let fit_term = 1.0 / (fitting_bins_count as f64 + 1.0);
    score += 8.0 * fit_term * (0.5 + 0.5 * progress);

    // Coupling with mean residual: prefer bins near mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize opening new bins early, less later
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) * (1.0 - progress);
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Leftovers in "dead" classes (tiny slivers)
    // are heavily penalized; leftovers that could host common small items
    // are rewarded.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Dead-space penalty: leftovers too small for the minimum item are useless.
    if post_residual < 1 {
        score += 1000.0;
    } else if post_residual < sixteenth {
        // Sliver class: nearly unusable.
        score += 40.0;
    } else if post_residual < eighth {
        // Small class: only fits tiny items.
        score += 12.0;
    } else if post_residual < quarter {
        // Mid class: decent.
        score -= 4.0;
    } else {
        // Large class: flexible, but wasteful if item was small.
        score += (post_residual as f64) * 0.05;
    }

    // Modulo harmonic bonus: leftovers that are congruent to multiples of a
    // natural item quantum tile better with future items.
    let quantum = sixteenth.max(1);
    if post_residual % quantum == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the leftover fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                // Perfect harmonic pairing: fill bin exactly.
                score -= 25.0;
            } else if slack < sixteenth {
                score -= 10.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins offer poor fits (large post_residual or dead classes).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // More open bins => stronger push to reuse them.
        score += (open_bins_count as f64) * 0.5;
        // If the current fit is terrible (huge leftover), opening fresh is fine.
        if post_residual > quarter && post_residual < bin_capacity {
            score -= 18.0;
        }
    }

    // Mild pressure toward tight fits overall.
    score += (item_size as f64) * 0.02;
    // Slight preference for bins below mean residual (balance load).
    score += ((bin_residual as f64) - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
