    } else {
        // last item: just minimize post residual
        score += 0.1 * post_residual as f64;
    }

    // Compare residual to mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item leaves huge unusable gap
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0; // default: prefer existing bins
        if next_item_size > 0 && item_size as f64 >= mean_residual {
            score -= 20.0; // item doesn't fit typical open bin anyway
        }
    }

    // Slight pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: residuals that can never host small items (min size 1, typical >=10)
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // mild reward for leaving room for the next item
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item won't fit here: penalize wasting space the next item needed
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.5 * waste.min(30.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate logic: opening a new bin is only attractive when current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bins early / when bins are still roomy; allow late when fragmented
        let new_bin_penalty = 55.0 - 30.0 * fragmentation - 10.0 * progress;
        score += new_bin_penalty.max(5.0);
        // if item is huge relative to capacity, a fresh bin is natural
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Global state: many open bins with high mean residual -> encourage consolidation into low-residual bins
    let rel_residual = bin_residual as f64 / bin_capacity as f64;
    let mean_rel = mean_residual / bin_capacity as f64;
    score += 10.0 * (rel_residual - mean_rel); // prefer below-average residual bins

    // Mild time-horizon modulation: late in stream, be greedier (minimize immediate waste)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Penalize opening bins when many already exist (encourage packing into existing)
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - rel_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Smooth polynomial coupling: penalize large post-residual quadratically as stream progresses
    let prn = pr / cap; // normalized post-residual [0,1]
    let quad = prn * prn;
    score += quad * (1.0 + 2.0 * progress) * cap * 0.5;

    // Reward tight fits (small post-residual) more strongly late in the stream
    score -= (1.0 - prn) * (1.0 - prn) * 8.0 * (0.5 + progress);

    // Penalize bins that deviate from mean residual (prefer balanced residual profile)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 6.0;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: reward if next item fits in the post-residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * ((n - pr) / cap);
        }
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 4.0 + 0.3 * open_bins_count as f64;
        // but new bin is fine early in stream
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues modulo 10.
    // Leftovers in "harmonic" classes (multiples of 10) are more reusable
    // since items are commonly drawn in coarse quanta; reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residue = (post_residual % 10) as f64;
    if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    } else {
        // penalize off-harmonic residue proportionally
        score += residue * 0.8;
        // harmonic classes: post_residual divisible by 10 or 20 are attractive
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 20 == 0 {
            score -= 4.0;
        }
    }

    // Integer-division thresholds on post_residual: dead-space bands.
    // Very small leftovers (<10) are effectively dead space -> penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Mid-band leftovers (10..=30) are the most reusable for small items.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0;
    }

    // Fraction-of-capacity coupling: prefer bins whose fill level is in
    // coarse fractions (1/2, 3/4) after placement.
    let fill_frac = 1.0 - post / cap;
    let half = (fill_frac * 4.0).round() / 4.0; // nearest quarter
    let frac_dev = (fill_frac - half).abs();
    score += frac_dev * 8.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it nearly fits (within 5), mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current item is
    // large and no good harmonic fit exists, or stream is early.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.55;
        // late in the stream, opening new bins is cheaper (waste less matter)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // if many bins already open, discourage more proliferation
        score += open_bins_count as f64 * 0.5;
        // large items justify fresh bins
        if item_size >= 60 {
            score -= 12.0;
        }
        // if next item is large too, a fresh bin preserves pairing potential
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild pressure toward consolidating into bins below mean residual
    // (pack into emptier-fitting bins to keep tight bins for small items).
    if (post as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1) can pair with it,
    // i.e. very small residuals that will likely never be filled.
    let dead_threshold = 12.0; // gaps <= 12 are nearly unusable for items (min size 1, but pairing waste)
    if (post_residual as f64) <= dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64 + 1.0);
    }

    // Nonlinear penalty on post_residual relative to bin capacity (wasted fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Open-bin pressure: penalize using bins when many are open, to consolidate load.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.8 * pressure;

    // Reward filling a bin almost exactly (tight fit).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 10.0;
    }
    // If next item would NOT fit here but would fit the current residual anyway,
    // slightly penalize leaving a gap just above next_item_size (awkward gap).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 5.0;
    }

    // Mean-residual coupling: prefer bins whose post placement moves residual
    // toward the mean (balanced packing) — mild regularizer.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate handling: an empty bin has huge post_residual; the
    // waste_frac^2 term already raises its score a lot. Add extra penalty so a
    // new bin is only chosen when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space
    score += 0.05 * (post_residual as f64) * (post_residual as f64) / 10.0;

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * (next_item_size as f64);
        } else if post_residual > 0 {
            // dead space that the next item cannot use
            score += 5.0;
        }
        // avoid wasting a bin that could fit both item and next item exactly
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: neutral-ish baseline, only attractive when
    // existing bins are poor fits or fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalty grows with fragmentation of open bins
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 + fragmentation * 0.3 - 20.0 * progress;
        // if many bins already open, discourage adding more unless forced
        score += 2.0 * open_bins_count as f64;
        // large items are easier to start fresh
        score -= 0.1 * item_size as f64;
    }

    // Prefer bins with residual close to mean residual (balanced usage)
    score += 0.02 * ((bin_residual as f64) - mean_residual).abs();

    // Slight preference for bins with small residual relative to item
    score += 0.05 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual non-linearly.
    let pr = post_residual as f64;
    score += 0.05 * (pr * pr) / bin_capacity as f64;

    // Reward filling bins deeply (small residual relative to capacity).
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * (1.0 - fill_ratio) * (1.0 - fill_ratio);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving residual that no typical item can use.
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.02 * waste;
        }
    }

    // New-bin candidate: attractive early, less attractive as stream progresses
    // or when many bins are open with slack to use.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = (bin_capacity as f64) - 10.0 * (1.0 - progress)
            + 0.5 * open_bins_count as f64
            + 0.1 * mean_residual;
    }

    // Smooth progress coupling: late in the stream, prefer consolidating into existing bins.
    score += 3.0 * progress * (pr / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean toward smaller values.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into decile buckets.
    let decile = post_residual / 10;
    match decile {
        0 => score -= 30.0,          // near-perfect fill: dead space < 10, excellent
        1 => score -= 18.0,          // very good fill
        2 => score -= 10.0,
        3 => score -= 5.0,
        4 => score += 0.0,           // neutral zone
        5 => score += 6.0,           // half-empty: awkward leftover
        6 => score += 12.0,
        7 => score += 18.0,
        8 => score += 26.0,
        _ => score += 34.0,          // barely touched bin: wasteful placement
    }

    // Modulo-4 harmonic bonus: leftovers that are multiples of 4 pair well with
    // typical item sizes; also exact multiples of 10 are re-usable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 4 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: reward when the leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-step chain
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // next item leaves near-perfect residue
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large relative to capacity or all residuals are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0
            - (item_size as f64 * 0.35)
            - fitting_bins_count as f64 * 6.0
            - mean_residual * 0.10
            - progress * 5.0;
        // large items start fresh bins happily
        if item_size >= 70 {
            score -= 25.0;
        }
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer reusing existing bins
    // over opening new ones (new bin has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 1.0 + open_bins_count as f64 * (0.05 + 0.1 * progress);
    if bin_residual == bin_capacity {
        score += 12.0 * pressure;
    } else {
        score -= 6.0 * pressure;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // Penalize if next item would leave this bin's residual wasted.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // keeps loose bins for larger future items.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize if next item cannot fit in the post residual (dead space for lookahead)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 10.0;
    }

    // Reward bins tighter than the mean residual (better-than-average packing)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize leaving large awkward residuals (hard-to-fill dead space)
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small residual is nearly perfect
    } else if post_residual > 50 {
        score += 0.2 * (post_residual as f64 - 50.0);
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 + 0.5 * mean_residual };
        score += pressure;
        // Early in stream, slightly discourage opening many bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Penalize dead space: residuals too small for typical future items.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (1.0 - t);
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // reward; otherwise penalize proportionally to the mismatch.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as u32) >= next_item_size {
            score -= 12.0 + 0.25 * n;
        } else {
            let waste = n - post_residual as f64;
            score += 0.35 * waste.min(50.0);
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (many fitting bins => keep consolidating; opening new bins is wasteful).
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        let openness = 1.0 - t;
        // Open a new bin mainly early in the stream or when alternatives are poor.
        score += 8.0 + 3.0 * pressure;
        score -= 15.0 * openness;
        if post_residual as f64 >= cap * 0.5 {
            score -= 10.0; // a fresh bin stays flexible
        }
    }

    // Global state: many open bins with slack => prefer filling existing ones.
    if open_bins_count > 2 {
        let slack = (mean_residual - post_residual as f64).abs();
        score += 0.05 * open_bins_count as f64;
        score -= 0.03 * slack;
    }

    // Mild preference for bins below mean residual (balance load).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear coupling: post_residual weighted by stream progress polynomial
    let progress_poly = 0.5 + 1.5 * progress * progress;
    score += progress_poly * norm_pr * norm_pr * cap * 0.3;

    // Dead-space penalty: small post_residual that can't fit typical next item
    let next_fits = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
    score -= next_fits * 8.0 * (1.0 - progress);

    // Lookahead synergy: post_residual close to next_item_size is valuable
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += (gap / cap) * 6.0 * progress;
    }

    // Last-chance bonus: avoid opening new bins early
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score += (mean_residual - pr) * 0.15 * (0.5 + progress);

    // Prefer filling larger residual bins when many bins open
    score -= (pr / (open_bins_count.max(1) as f64)) * 0.4;

    // New-bin candidate: penalize mildly so it's chosen only on good fit
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by large power-of-two / common item sizes are "usable" slots.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are multiples of common item granularities.
        let mut harmony_bonus = 0.0;
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 5 == 0 { harmony_bonus += 2.0; }
        if pr % 20 == 0 { harmony_bonus += 4.0; }
        if pr % 25 == 0 { harmony_bonus += 3.0; }
        // Perfect fit: exact harmonic closure.
        if pr == 0 { harmony_bonus += 100.0; }
        score -= harmony_bonus;

        // Penalize small dead-space classes (1..=9): unusable for items >= 10.
        if pr < 10 {
            score += 25.0 * (10.0 - pr as f64);
        }

        // Integer-division threshold: classify residual into capacity sextiles.
        let sextant = (pr * 6) / bin_capacity; // 0..5 integer division class
        // Mid-class residuals (class 2,3) are flexible; extremes less so.
        match sextant {
            2 | 3 => score -= 8.0,
            0 => score -= 4.0,
            _ => score += 3.0,
        }
    } else {
        // Perfect closure — best possible outcome.
        score -= 120.0;
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        // Reward chains where the pair leaves a harmonic residual.
        if leftover % 10 == 0 { score -= 10.0; }
        if leftover < 10 { score -= 5.0; }
        score -= (leftover as f64) * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty, worse if this was the only fitting bin.
        score += 6.0;
        if fitting_bins_count == 1 {
            score -= 18.0; // last-chance bin: still prefer filling it
        }
    }

    // Last-chance bonus: sole fitting bin should be strongly preferred over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Opening new bins is penalized more as stream progresses / bins fill.
        score += 20.0 + 40.0 * progress + 30.0 * mean_fullness;
        if open_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Mild global pressure: many open bins -> favor tightening existing ones.
    score -= (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        let dead_penalty = 60.0 * dead * dead * (1.0 - dead);
        score += dead_penalty;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Penalize gaps that no plausible future item can use (sizes 1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 25.0; // cannot host next item -> likely dead space
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += pressure;

    // New-bin candidate: only attractive when open bins are quite full/fragmented.
    if bin_residual == bin_capacity {
        let avg_fill_gap = (mean_residual - bin_residual as f64).max(0.0);
        score += 10.0 + 0.4 * open_bins_count as f64 - 0.5 * avg_fill_gap;
        if post_residual == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let post = post_residual as f64;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Neutral-ish baseline for a fresh bin: slightly penalized relative
        // residual so that decent existing fits still win.
        let mut new_score = post * 0.85;
        // Aggressive 2-step lookahead: a fresh bin leaves room exactly for the
        // next item -> very attractive (guaranteed perfect pairing).
        if next_item_size > 0 {
            if post_residual == next_item_size {
                new_score -= 45.0;
            } else if post_residual > next_item_size {
                let slack = post - next_item_size as f64;
                new_score -= (next_item_size as f64) * 0.4 - slack * 0.15;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        new_score += progress * 10.0;
        return new_score;
    }

    // --- Existing bin: aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect match: item + next item exactly fill this bin.
            score -= 50.0;
        } else if post_residual > next_item_size {
            // Next item still fits: reward proportional closeness to perfect fill.
            let gap = post - nxt;
            score -= nxt * 0.5 * (1.0 - gap / bin_capacity as f64);
            // Extra reward if the combined fill is near capacity.
            let combined = item_size as f64 + nxt;
            if combined >= 0.9 * bin_capacity as f64 {
                score -= 20.0;
            }
        } else {
            // Dead space: next item cannot use the remainder -> penalize
            // proportionally to the unusable gap.
            let dead = nxt - post;
            score += dead * 0.35;
            // Very small post-residual (<10) is genuinely dead space too.
            if post_residual < 10 {
                score += (10.0 - post) * 0.5;
            }
        }
    } else {
        // Last item: purely greedy tight fit.
        score -= 5.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose post-residual sits below the open-bin mean
    // (tightening already-loose bins), penalize outliers above the mean.
    score -= (mean_residual - post) * 0.25;

    // --- Last-chance bonus: only this bin can fit the item ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // --- Mild preference for keeping many bins busy early on ---
    if open_bins_count > 1 {
        score -= (open_bins_count.min(8) as f64) * 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual is good).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that can't fit the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * (post_residual as f64);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.25 * (next_item_size as f64);
    }
    // Penalize bins that leave just barely not-enough space for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so tight fits in open bins usually win.
        score += 14.0;
        // Late in the stream, opening fresh bins is cheaper (less waste risk).
        score -= 10.0 * progress;
        // If many open bins already fit, discourage opening another.
        if fitting_bins_count > 1 {
            score += 6.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the item leaves a lot of waste in any bin, a fresh bin is fine.
        if post_residual >= 40 {
            score -= 12.0;
        }
        // Large items fit cleanly in fresh bins.
        if item_size >= 60 {
            score -= 5.0;
        }
        // If mean residual across open bins is small, open bins are congested.
        if mean_residual < item_size as f64 {
            score -= 4.0;
        }
    }

    // Mild penalty for scattering across many open bins when residual is large.
    if open_bins_count > 3 && post_residual > 50 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * (0.5 + 0.5 * progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (20.0 + 30.0 * progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - ((pr - ns) / cap)) * (0.5 + progress);
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: bins whose leftover belongs to a
    // "usable" class (multiples of common small item sizes) are preferred.
    let usable = |r: u32| -> bool {
        r == 0 || (r % 10 == 0) || (r % 25 == 0) || (r % 50 == 0)
    };
    if usable(post_residual) {
        score -= 8.0;
    } else if post_residual < 10 {
        // dead space class: tiny leftover unusable for items >= 1? still usable
        // for small items, mild penalty scaled by deadness
        score += 3.0 * (10 - post_residual) as f64;
    }

    // Integer division thresholds on post_residual (quarters of capacity)
    let q = post_residual / (bin_capacity / 4);
    score += q as f64 * 2.0; // prefer filling bins deeper (smaller post_residual)

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residue: reward harmonic fit
            let nxt_post = post_residual - next_item_size;
            if usable(nxt_post) {
                score -= 15.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residue: penalize proportional to waste
            score += (next_item_size.min(post_residual + 100)) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins
    // have poor fits (large mean residual spread / item barely fits)
    if bin_residual == bin_capacity {
        // neutral base: cost of a fresh bin
        score = 55.0;
        if post_residual == bin_capacity {
            // empty vs empty
            score = 50.0;
        }
        // open a new bin when current item is large and open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 > 0.6 * cap_f && mean_residual < 0.25 * cap_f {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer consolidation
        score += progress * 10.0;
    }

    // Mild preference to keep many bins lightly loaded balanced: penalize
    // placing into bins far below mean residual (fragmentation control)
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful later
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 {
        score += 200.0; // near-perfect fit is great; handled by reward below
    }

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 150.0; // tiny gap likely dead space, but perfect-ish fit
    } else if post_residual < 25 {
        // awkward mid gap: penalize extra on top of raw residual
        score += 60.0;
    }

    // Coupling with lookahead: if the next item fits the post residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
        // extra reward if post residual is a comfortable host for next item
        let slack = (post_residual - next_item_size) as f64;
        if slack < 15.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here; if gap is small it's dead space
        if (post_residual as f64) < next_item_size as f64 * 0.5 {
            score += 50.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; opening new bins is penalized implicitly via residual
    // baseline plus an explicit term.
    let open_pressure = open_bins_count as f64 * 3.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., fuller bins) to concentrate packing.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 1.5;

    // New-bin candidate handling: empty bin starts from a high baseline so
    // it is only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 250.0 + open_bins_count as f64 * 5.0;
        // late in the stream, new bins are cheaper (less future to waste)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 150.0 * progress;
    }

    // Small item arriving: slightly prefer spreading into residual-rich bins.
    if item_size <= 20 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits too: small bonus proportional to how well it fits after
            let second_residual = post_residual - next_item_size;
            score -= 50.0 * (1.0 - second_residual as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize large post_residual (dead space)
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize post_residual that is too small to fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New bin candidate: mild penalty so we prefer reusing open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * open_bins_count as f64;
    }

    // Late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual dominates).
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize post_residual that is too small for next item
    // (dead space), but reward post_residual that can host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            let waste = (post_residual as f64) / (next_item_size.max(1) as f64);
            score += waste * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            let min_post = (bin_residual - item_size) as f64;
            min_post
        };
        // Base penalty so open bins are preferred unless fit is terrible.
        score += 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin guarantees room for the next item too.
            score -= 10.0;
        }
        if fitting_bins_count > 0 && (item_size as f64) / (bin_residual as f64) < 0.5 {
            // Item would waste more than half of an existing bin -> new bin ok.
            score -= 20.0;
        }
        let _ = pressure;
    }

    // Time horizon: early in stream, be more willing to open bins for
    // flexibility; late in stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 12.0;
    } else {
        score += progress * 5.0;
    }

    // Many open bins: favor filling existing ones (consolidation pressure).
    score += (open_bins_count as f64) * 0.5;
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Deviation from mean residual: prefer bins whose residual is near mean
    // (balanced packing) but reward below-mean residuals (denser bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild penalty for large items in nearly-full bins (fragmentation risk).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Quadratic coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more
    let coupling = norm_pr * norm_pr * (progress * progress) * cap * 0.35;
    score += coupling;

    // Smooth cubic interaction: mid-stream, moderate residual is acceptable
    score -= 12.0 * norm_pr * progress * (1.0 - progress);

    // Penalize dead space relative to mean residual state
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 5.0 * (1.0 - norm_pr);
        } else {
            score += 3.0 * ((next_item_size as f64) - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: mild penalty so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - progress) + 0.4 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space (capacity fraction classes of 10)
    let class = post_residual / 10;
    let in_class = post_residual % 10;
    // Penalize leftovers inside a class band (dead space within a harmonic class)
    score += in_class as f64 * 0.7;

    // Reward leftovers that exactly match a useful harmonic class
    match class {
        0 => score -= 15.0,                    // perfect fit
        1 => score -= 9.0,                     // 10-19 leftover: fits smallest items
        2 => score -= 6.0,
        3 => score -= 4.0,
        4 => score -= 2.5,
        5 => score -= 1.5,                     // half-full leftover
        _ => {}                                // large leftovers: neutral
    }

    // Coupling with lookahead: leftover that can host the next item is valuable
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 4.0 + (slack as f64).min(10.0) * 0.5;
        } else {
            // leftover cannot host next item: penalize proportionally to waste
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // crowding bonus: prefer tighter bins when many choices exist
        score -= (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: only attractive when item fits poorly everywhere
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // big items justify fresh bins; small items should reuse open bins
        if tightness > 0.7 {
            score -= 12.0 * (tightness - 0.7) / 0.3;
        } else {
            score += 18.0 * (0.7 - tightness);
        }
        // early in the stream, opening bins builds a working set
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        // many open bins with slack: discourage new bins
        score += (open_bins_count as f64) * 0.4;
    } else {
        // prefer bins with residual below the mean (tighter packing)
        score += (mean_residual - bin_residual as f64) * 0.25;
    }

    // Integer-division threshold on post_residual: punish awkward bands
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }
    if post_residual >= 30 && post_residual < 40 {
        score -= 2.0; // classic mid class, still useful
    }

    // Mild preference for bins that end exactly on capacity fractions
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item are pure waste. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize small-but-marginal gaps that few future items can use.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count <= 2 {
        score -= 15.0; // last-chance bin: strongly prefer using it
    } else {
        score += (open_bins_count as f64) * 0.8;
    }

    // Prefer bins with below-average residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // current fit is poor or many bins are open.
    if bin_residual == bin_capacity {
        score += 5.0;
        if post_residual > 0 && post_residual < 10 {
            // empty bin avoids creating a dead gap
        }
        score -= (open_bins_count as f64) * 0.3;
    }

    // Late-stream tightening: waste matters more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect 2-chain bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that next item cannot use at all
        if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Compare against mean residual: placing into a bin with residual near mean is neutral,
    // into a large-residual bin is favored (reduces fragmentation elsewhere).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize creating small unusable dead space (< typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Slight preference for opening new bins early in the stream (keeps options open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted space.
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize old bins less); late in the stream, pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * (1.0 - fill_frac);
    score -= progress * 10.0 * tightness;

    // Global residual balancing: bins far below mean residual get a nudge.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: mildly penalize so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits, must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = prn * (1.0 + 0.8 * prn * prn);

    // Smooth coupling: as stream progresses, dead space becomes more costly.
    score += 12.0 * progress * prn * prn;

    // Perfect fit reward (smooth Gaussian-like bump around zero post-residual).
    score -= 30.0 * (-prn * prn / 0.005).exp();

    // Penalize residual that no typical next item can use (dead space).
    let usable = if next_item_size > 0 { (next_item_size as f64).min(pr) / cap } else { 0.0 };
    score -= 15.0 * usable;

    // Lookahead: reward if next item fits exactly into post residual.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item cannot use this bin's remainder: slight penalty.
        score += 3.0 * prn;
    }

    // Last-chance bonus: if only this bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild preference for tighter bins relative to mean residual.
    score += 2.0 * ((pr - mean_residual) / cap);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score = 8.0 + 6.0 * progress + 2.0 * openness - 4.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions (C=100)
    let pr = post_residual;
    let frac = pr as f64 / bin_capacity as f64;

    // Penalize residual classes that are hard to fill: small but nonzero slivers
    if pr > 0 && pr < 10 {
        score += 60.0;
    }
    if pr >= 10 && pr < 20 {
        score += 25.0;
    }

    // Reward residuals in "harmonic" classes divisible by common item sizes
    if pr % 20 == 0 && pr > 0 {
        score -= 15.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 12.0;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 40.0 - (slack as f64).min(40.0);
            // Harmonic: next item leaves a class-0 residual
            if slack % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot follow here; slight penalty
            score += 10.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // large item stream: fresh bin useful
        }
    }

    // Prefer fuller bins as stream progresses (tightening)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - frac);

    // Prefer bins below mean residual slightly (balance avoidance of many half bins)
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it's too small for the smallest plausible item (1..100 range, assume min ~1
    // but practically gaps < ~10 waste space). Penalize small positive post_residual heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // Favor leaving gaps that can plausibly fit future items:
        // reward larger post_residual mildly (more reusable space).
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0; // next item nearly fills this bin perfectly
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mildly penalize creating a tight residual
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (avoid scattering); with few open bins, opening new bins is less costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: brand-new empty bin should only win when current placement
    // is terrible. Penalize it moderately so decent fits win.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if many open bins are nearly full, new bin is fine
        if mean_residual < 15.0 {
            score -= 35.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near mean (avoid outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches post_residual, hugely favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here: reward proportionally to tightness of the two-step fit
            let two_step_waste = post_residual - next_item_size;
            score -= (50.0 - two_step_waste.min(50) as f64) * 2.0;
        } else {
            // Next item won't fit in the residual: penalize dead space relative to next item size
            let dead = post_residual as f64;
            let unusable = dead < next_item_size as f64;
            if unusable {
                score += dead * 0.5; // dead space that the next item cannot use
            }
        }
    }

    // Coupling with mean residual: prefer bins tighter than average
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin candidate unless residual of open bins is poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin late in stream if mean residual is small (bins nearly full)
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 100.0;
        }
        // Late in the stream, opening fresh bins is less costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mild penalty for leaving large residuals in mostly-empty bins
    if post_residual as f64 > mean_residual * 2.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // Perfect pairing: this bin + next item exactly consumed elsewhere
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - gap / bin_capacity as f64).max(0.0) * 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins below mean residual (consolidate waste into few bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 15.0;

    // Time horizon: early on, be picky about tight fits; late, avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * (1.0 - fit_ratio);

    // New-bin candidate handling: mildly discourage opening new bins unless
    // the item is large relative to residual or current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 20.0 - 25.0 * fragmentation - fit_ratio * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large item arriving: fresh bin may be fine
        }
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: residual waste weighted by stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (0.3 + progress);

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 6.0 * (1.0 - (ns / pr).min(1.0)) * (0.5 + progress);
        } else {
            score += 5.0 * (ns - pr) / cap * (1.0 - progress);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize slightly, more when bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins near the mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residuals divisible by common
    // item-size classes (10/20/25/50) are more reusable than prime leftovers.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr == 0 {
        bonus += 40.0; // perfect fit
    } else {
        if pr % 10 == 0 { bonus += 12.0; }
        if pr % 20 == 0 { bonus += 8.0; }
        if pr % 25 == 0 { bonus += 8.0; }
        if pr % 50 == 0 { bonus += 6.0; }
        // dead-space penalty for tiny unusable slivers
        if pr < 10 { bonus -= 25.0; }
        else if pr < 20 { bonus -= 10.0; }
    }

    // Next item compatibility: lookahead fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            bonus += 30.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 { bonus += 10.0; }
            if slack < 10 { bonus -= 8.0; } // leaves another sliver
        } else {
            bonus -= 5.0; // lookahead won't fit here anyway
        }
    }

    // Integer-division threshold: residual in a "useful band" (>= 50) is valuable
    let band = pr / 25; // 0..4
    bonus += match band { 0 => -15.0, 1 => -5.0, 2 => 3.0, _ => 8.0 };

    // Last-chance bin: strongly prefer filling it rather than opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        bonus += 35.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        // penalize opening new bins early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        bonus -= 20.0 + 30.0 * (1.0 - progress);
        if item_size >= bin_capacity / 2 { bonus += 15.0; } // big item, fresh bin ok
    }

    // Slight pull toward bins with residuals near mean (keeps balance)
    bonus -= 0.1 * (bin_residual as f64 - mean_residual).abs();

    score -= bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: small unusable gaps are heavily penalized.
        // A residual is "dead" if it is smaller than the smallest conceivable item (1..100 interface).
        // Treat gaps <= 10 as dead space (cannot fit anything realistically useful).
        if post_residual <= 10 {
            score += 500.0; // worse than a mediocre fit
        } else if post_residual < 20 {
            score += 150.0; // nearly dead space
        }
        // Non-linear coupling: prefer small-but-usable residuals over large ones,
        // with a convex penalty on wasting space.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr / bin_capacity as f64;
    }

    // Reward bins that can also host the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 25.0; // blocks the next item
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 300.0 + 50.0 * open_bins_count as f64 + 100.0 * progress;
        // A new bin is acceptable only if no open bin fits well: if others fit,
        // keep the penalty high; mean_residual context nudges consolidation.
        score += 0.3 * mean_residual;
    } else {
        // Mild reward for consolidating into existing bins when many are open.
        score -= 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect match: next item exactly fills this bin
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Small bonus if next item still fits with room to spare
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Penalize tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward tight fits (small post_residual overall)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (good packing)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream: favor closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.2 * progress);

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional tightness of the fit: reward near-perfect packing.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items
    // (unusable slivers below ~10 are wasted, but small leftovers can pair
    // with tiny items; use a soft quadratic barrier).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 8.0 * (1.0 - pr / bin_capacity as f64) * (pr / 25.0).min(1.0);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement; penalize if next item barely misses.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= post_residual as f64 {
            let next_fit = ni / post_residual.max(1) as f64;
            score -= 25.0 * next_fit;
        } else {
            score += 6.0 * (ni - post_residual as f64) / 50.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current item is large relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let item_pressure = item_size as f64 / bin_capacity as f64;
        score = 55.0 + 40.0 * crowd + 30.0 * progress - 25.0 * item_pressure;
        // If no open bin fits at all, opening a new bin is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild global-state regularization: prefer bins whose residual is near the
    // mean (keeps residual distribution balanced).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Early-stream exploration: slightly favor tight fits more early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 0.9 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear waste penalty: dead space that can't fit typical items is quadratic in smallness
    let pr_norm = pr / cap;
    let waste = (1.0 - pr_norm).powi(3);
    score += 60.0 * waste * pr_norm;

    // Progress coupling: early on, prefer tight fits to keep flexibility; late, reward tight fits harder
    let tight_fit = 1.0 - pr_norm;
    score -= (20.0 + 60.0 * progress) * tight_fit.powi(2);

    // Lookahead: if next item fits in post_residual, reward this bin strongly
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 25.0 * (next_item_size as f64 / cap);
        } else {
            score += 15.0 * (1.0 - (next_item_size as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when many open bins already fit
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual alignment: bins deviating from mean residual get mild penalty
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in the "small residue"
    // classes (1..10) is nearly unusable -> strong penalty.
    let dead = post_residual < 10;
    if dead {
        score += 60.0;
    } else {
        // Reward residuals that fall into "harmonic" classes: multiples of
        // common item-size bands (10,20,25,50) are reusable.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 12.0;
        }
        if r % 20 == 0 {
            score -= 6.0;
        }
        if r % 25 == 0 || r % 50 == 0 {
            score -= 4.0;
        }
        // Small usable leftovers (10..20) are half-dead: mild penalty.
        if r < 20 {
            score += 8.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills the leftover.
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize more if post residual is
            // in a dead class anyway (wasted bin).
            score += 3.0;
            if dead {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits or all fits
    // are poor (huge post residual waste). Base cost of a fresh bin.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.35 * open_bins_count as f64;
        // Late in the stream, opening fresh bins is cheaper (fewer future items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If mean residual of open bins is small (fragmented), a new bin helps.
        score -= (mean_residual / cap).min(1.0) * 8.0;
    }

    // Prefer tighter fits overall: normalized fill fraction of this placement.
    score -= (item_size as f64 / cap) * 10.0;

    // Mild penalty for leaving residual far from mean (keeps bin sizes balanced).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize unusable small gaps.
    // A residual that is too small to hold even the minimum item is pure waste.
    if post_residual < 10 {
        score += 200.0;
    } else if post_residual < 25 {
        // Small, likely-unusable gaps: strong penalty scaled by how tight the gap is.
        score += (25.0 - post_residual as f64) * 8.0;
    } else if post_residual < 40 {
        // Moderate dead-space zone: mild penalty.
        score += (40.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits (post_residual very small but still usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 60.0;
    }

    // Open-bins pressure: prefer keeping the number of active bins low,
    // so slightly favor filling already-open bins over opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // or the current stream is early (plenty of future items to fill it with).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = (item_size as f64 / 100.0) * 30.0;
        score += 40.0 - large_item_bonus - (1.0 - progress) * 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement strongly (chains well).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 50.0;
        } else if slack <= 15.0 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (tighter bins),
    // encouraging consolidation of space.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Penalize very large leftover gaps proportionally (dead space grows).
    score += (post_residual as f64).powi(2) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end with zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the post-residual exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + gap);
        if gap == 0.0 {
            score -= 500.0; // two-item perfect chain
        }
    }

    // Penalize post_residual that is dangerously close to next_item_size
    // (dead space: next item almost fits but not quite)
    if next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 150.0 * (1.0 - miss / 10.0);
        }
    }

    // Penalize small unusable residuals (< 10, nothing can fit later)
    if post_residual < 10 && post_residual > 0 {
        score += 300.0;
    }

    // Relative-to-mean coupling: prefer bins tighter or looser than average
    // depending on whether we want to consolidate or spread.
    let mr = mean_residual;
    if (post_residual as f64) < mr {
        score -= (mr - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mr) * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // fragmented (high mean residual spread) or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if fragmentation > 20.0 || (large_item && next_item_size == 0) {
            score -= 100.0 + progress * 50.0;
        } else {
            score += 400.0; // prefer reusing open bins
        }
    }

    // Mild penalty for opening bins early in the stream
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fits badly
    // and there is meaningful lookahead demand.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (bin_residual as f64 - item_size as f64).abs() > 25.0;
        let lookahead_pressure = next_item_size as f64 > post_residual as f64 && next_item_size > 0;
        let mut penalty = 55.0;
        if tight { penalty -= 20.0; }
        if lookahead_pressure { penalty -= 10.0; }
        penalty *= 1.0 - 0.3 * progress;
        score += penalty;
    }

    // Lookahead synergy: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Prefer bins with residual below the mean (consolidate fullness).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild preference for already-open bins when many are open (limit sprawl).
    score += 0.05 * open_bins_count as f64;

    // Non-linear fullness reward: the fuller the bin becomes, the better.
    let fullness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * fullness * fullness * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: penalize wasted residual, with progress-dependent curvature
    let mut score = x * (1.0 + 3.0 * progress * (1.0 - progress) * 2.0 + progress * progress * 2.0);

    // Non-linear coupling: small post-residuals are valuable dead-space sinks
    score -= 6.0 * (1.0 - x).powi(3) * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        if fits_next {
            score -= 4.0 * (1.0 - ((next_item_size as f64 - pr).abs()) / cap);
        } else {
            score += 2.0 * (1.0 - x) * (progress + 0.3);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (0.5 + progress);
    }

    // Crowding: mildly penalize when many bins are open but residual is large
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * x;

    // Mean-residual deviation: prefer bins near the mean (balanced packing)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening unless residual would be tiny (tight fit elsewhere impossible)
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * progress;
        if item_size as f64 / cap > 0.7 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "residue band" does the leftover fall in?
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12

    // Class A: post_residual in [0, 8) — near-perfect fit, strongly reward.
    if post_residual < eighth {
        score -= 40.0;
    }
    // Class B: post_residual divisible by 8 exactly (harmonic residue) — usable chunks.
    else if post_residual % eighth == 0 {
        score -= 15.0;
    }
    // Class C: post_residual in the "dead zone" (10..=20) — classic unusable gap.
    else if post_residual >= 10 && post_residual <= 20 {
        score += 30.0;
    }

    // Integer-division class of post_residual by quarter bins.
    let div_class = post_residual / quarter; // 0..=4
    score += match div_class {
        0 => -10.0,
        1 => 5.0,
        2 => 12.0,
        3 => 20.0,
        _ => 0.0,
    };

    // Modulo coupling: does next_item_size divide into post_residual harmonically?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits_next = post_residual % next_item_size == 0
            || post_residual - next_item_size < eighth;
        if fits_next {
            score -= 25.0;
        } else {
            score += 10.0;
        }
        // Next item exactly fills the bin: huge reward.
        if next_item_size == post_residual {
            score -= 35.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize unless current bin would leave a dead zone
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        score = 60.0;
        if fitting_bins_count == 0 {
            score = 5.0;
        } else if post_residual >= 10 && post_residual <= 20 {
            score = 30.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more than large leftover space.
    if post_residual > 0 {
        let unusable = post_residual < 10;
        let awkward = post_residual >= 10 && post_residual < 20;
        if unusable {
            score += 40.0;
        } else if awkward {
            score += 12.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual below mean (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Post residual too small for next item: penalize if it's dead space.
        score += 8.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match lookahead reward: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    }
    // If next item cannot fit here, mild penalty proportional to lookahead gap.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize small unusable dead space (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (consolidate emptier bins first).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a good lookahead match and residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 35.0 - fragmentation * 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: reduce new-bin appeal as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalization (non-linear).
    let waste = post_residual as f64;
    score += (waste / cap) * (waste / cap) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual can't hold next item but is small, mild penalty (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            score -= 8.0;
        }
        // Check if next item would fit in post residual exactly (chained perfect fit).
        if post_residual as u32 == next_item_size {
            score -= 20.0;
        }
        // Dead space: post residual smaller than min plausible item but nonzero.
        if post_residual > 0 && (post_residual as f64) < nx && (post_residual as f64) < 10.0 {
            score += 12.0;
        }
    }

    // New-bin candidate: penalize so it's only chosen when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += cap * 1.5 + open_bins_count as f64 * 2.0;
        // Early in stream, opening bins is cheaper (more room to consolidate later).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 30.0;
    }

    // Global state: if mean residual is high, prefer filling fuller bins (balance residuals).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in stream: consolidate aggressively, avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: small post-residual is more valuable late in the stream
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize wasted space relative to the next item's needs (lookahead fit)
    if nxt > 0.0 {
        let gap = (nxt - pr).max(0.0);
        score += 0.35 * gap;
        // Reward post-residual that exactly or nearly accommodates next item
        let match_term = (pr - nxt).abs();
        score -= 10.0 * (-0.05 * match_term).exp() * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mild penalty for deviating from mean residual (keeps bin profile balanced)
    score += 0.08 * ((pr - mean_residual) / cap).abs() * cap;

    // Slight preference for tighter bins when many bins are open
    score += 0.02 * (open_bins_count as f64) * norm_pr;

    // Penalize opening a new bin smoothly, stronger early when consolidation matters
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) - 0.05 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable slots"
    // (>= 10) are rewarded; small dead-space residues are penalized.
    let pr = post_residual;
    let dead = pr < 10;
    let usable = pr >= 10 && pr <= 80;

    if dead {
        // Perfect fill or near-perfect fill is best; pure dead space is bad.
        if pr == 0 {
            score -= 60.0;
        } else {
            score += 25.0 + (10 - pr) as f64;
        }
    } else if usable {
        // Reward usable leftovers, scaled by how well a future item class fits.
        score -= 8.0;
    }

    // Integer-division thresholds on post_residual: which harmonic band does
    // the leftover live in?
    let band = pr / 20; // 0..5
    match band {
        0 => score += 6.0,          // 0..19: mostly dead space
        1 => score -= 2.0,          // 20..39: small but usable
        2 => score -= 5.0,          // 40..59: good slot
        3 => score -= 7.0,          // 60..79: great slot
        4 => score -= 4.0,          // 80..99: large leftover
        _ => {}                     // 100: fresh bin
    }

    // Modulo arithmetic: leftovers that are multiples of common item classes
    // (10, 20, 25) are more likely to be exactly filled later.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: does next_item_size divide into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Exact modular match: next item fills bin to a clean boundary.
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
            score -= 6.0;
        } else {
            // Next item won't fit here; leftover becomes stranded.
            score += 5.0;
            let gap = next_item_size - pr;
            if gap <= 15 {
                score += 4.0; // agonizingly close miss
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or open-bin fits would strand space.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.7 {
            score -= 12.0; // big item: fresh bin is fine
        } else {
            score += 10.0 + 15.0 * (1.0 - fill_frac); // discourage wasting a fresh bin on small items
        }
        // If many open bins exist and none fit well, fresh bin gains appeal.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Congestion: many open bins with high mean residual -> prefer compacting
    // into existing bins rather than spreading.
    if bin_residual != bin_capacity {
        if (mean_residual - bin_residual as f64).abs() < 5.0 {
            score -= 3.0; // align with the crowd to consolidate
        }
        if open_bins_count > 8 && bin_residual < mean_residual {
            score -= 4.0; // fill the tighter bins first
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            score += 60.0 * (11.0 - gap); // tiny dead space is worst outcome
        } else if gap <= 20.0 {
            score += 25.0 * (21.0 - gap) / 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 2.5 * open_bins_count as f64;

    // If the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next == 0 {
            score -= 70.0;
        } else if leftover_after_next <= 10 {
            score += 20.0; // would create tiny dead space next step
        } else {
            score -= 10.0;
        }
    }

    // Compare against mean residual: bins with residual far below mean are tighter; prefer them.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin pressure is high; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 55.0; // nothing fits: open new bin
        } else if open_bins_count > 6 {
            score -= 15.0 * (open_bins_count as f64 - 6.0).min(4.0);
        } else {
            score += 40.0; // discourage opening new bins when open ones can fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: shape score around whether the NEXT item
    // can use the residual left behind by the current placement.
    if next_item_size > 0 {
        let pr = post_residual;
        if pr == next_item_size {
            // Perfect chaining: next item exactly fills this bin's leftover.
            score -= 60.0;
        } else if pr >= next_item_size {
            // Next item still fits: mildly reward tighter leftover.
            score -= 8.0 + (next_item_size as f64 / pr as f64) * 10.0;
        } else if pr > 0 {
            // Dead space: leftover too small for the next item.
            // Penalize proportionally to how close it came to fitting.
            let near_miss = next_item_size as f64 / bin_capacity as f64;
            score += 15.0 + near_miss * 20.0;
        }
    } else {
        // Last item in stream: just prefer tightest packing.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty-bin candidate: penalize mildly so it only wins when
    // all existing fits are poor (large dead space / no lookahead match).
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Contextual coupling: reward bins whose residual is below the mean
    // (tighter bins), penalize outlier-loose bins slightly.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Early-stream nudge: keep bins balanced at the start to preserve options.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward placements that leave little but usable residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; mild penalty unless residual is tiny.
            score += 3.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer reusing bins over opening new ones.
    score += 0.5 * open_bins_count as f64;

    // Global residual pressure: if mean residual is large, prefer bins above mean (consolidate).
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early on, be conservative about dead space; late, exploit tight fits.
    score += (1.0 - progress) * 0.05 * post_residual as f64;
    score -= progress * 5.0 * tightness;

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted as the stream progresses.
        score = 40.0 - 15.0 * progress;
        // If only the new bin can fit the item, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Large items justify fresh bins more (less dead-space risk).
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, with non-linear penalty on small residuals
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, small residuals become costly.
    let progress_coupling = 1.0 + 2.0 * progress * progress + progress;
    score += progress_coupling * (norm_post * norm_post) * cap * 0.5;

    // Reward filling bins almost exactly (post near 0), smoothly
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * tightness * item_size as f64 * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize if next item would not fit, scaled by how far off
        let gap = (next_item_size as f64 - post) / cap;
        score += gap * gap * cap * 0.4;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).ln() * 0.5;
    score += (norm_post - mean_residual / cap).abs() * cap * 0.2;

    // New-bin candidate: prefer opening a new bin early, less so late
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress) - 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are
    // "friendly" to common item sizes (divisible by small harmonic divisors).
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit is always ideal.
        score -= 1000.0;
    } else {
        // Reward residuals that are multiples of common size classes.
        let mut harmony: f64 = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 {
                harmony += 30.0;
            }
        }
        if pr % 5 == 0 {
            harmony += 8.0;
        }
        score -= harmony;

        // Penalize tiny dead space (unusable slivers).
        if pr < 10 {
            score += 60.0;
        }

        // Reward residuals that can exactly host the lookahead item.
        if next_item_size > 0 && pr == next_item_size {
            score -= 120.0;
        }
        // Penalize if post residual can't fit the next item but is still sizeable.
        if next_item_size > 0 && pr > 0 && pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.5;
        }
        // Bonus if post residual can fit next item with zero or small slack.
        if next_item_size > 0 && pr >= next_item_size {
            let slack = pr - next_item_size;
            score -= 40.0;
            if slack % 10 == 0 {
                score -= 15.0;
            }
            if slack < 10 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // the item is large relative to capacity or few bins fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins aren't opened casually.
        score += 25.0;
        // Large items deserve fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 45.0;
        }
        // If many bins fit the item, discourage spreading.
        if fitting_bins_count > 2 {
            score += 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild preference to keep the number of open bins low.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are unusable (too small for
    // any plausible item) are heavily penalized, non-linearly.
    let dead_threshold = 10.0f64; // smallest possible item size
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Penalize "awkward" residuals in (10, 30): often wasted space.
    if post_residual > 10 && post_residual < 30 {
        score += 0.8 * (30 - post_residual) as f64;
    }

    // Reward near-perfect fits (post_residual close to 0 but usable).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 18.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 5.0; // next item can't use this bin's remainder anyway
        }
    }

    // Open-bins pressure: mildly discourage adding to many-open states,
    // but strongly prefer filling an existing bin over opening a new one
    // when the fit is decent.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, opening a new bin
    // wastes this residual; penalize the new-bin option instead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when the item is huge
    // relative to residual or fit is poor. Penalize its base score.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Exception: large items deserve a fresh bin.
        if item_size > 60 {
            score -= 55.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host both current and next item
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (tighter bins get filled first, keeping loose bins flexible).
    score += 0.25 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a third-level residual; mildly reward.
            let chain_residual = post_residual - next_item_size;
            score -= 20.0 * (1.0 - (chain_residual as f64) / (bin_capacity as f64));
        } else {
            // Next item will NOT fit here: penalize leaving residual that
            // becomes dead space relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual of open bins: prefer bins
    // that end up tighter than average (reducing wasted space overall).
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating unusable dead space: residual smaller than the minimum
    // plausible item size (1) is impossible, but very small residuals waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when no
    // open bin offers a good fit; default slight penalty so we reuse bins.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if next item is large and current item is small, a fresh bin
        // preserves space for big items later.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidation matters more; favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Prefer bins that are already well-filled before placement.
    let pre_fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * pre_fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more dead space; mild reward scaled by fit quality.
            let next_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 18.0 * next_fit;
        } else {
            // Next item cannot use the residual; penalize proportionally to wasted space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64;
        score -= 25.0 - 0.2 * fit_quality;
    }

    // Penalize creating very small unusable residual fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer bins whose residual deviates below the mean (consolidate emptier bins' usage).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Dynamic time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0;
    score -= progress * 5.0 * tightness;

    // When many bins are open, discourage spreading items across bins; favor filling.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Brand-new empty bin candidate: penalize opening a new bin unless the item
    // is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on wasted space, growing with stream progress
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Non-linear coupling: waste is more costly as the stream progresses
    score += 20.0 * norm_post * norm_post * (progress * progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 15.0 * (1.0 - norm_post).exp() * (1.0 + norm_item);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else {
        // Mild penalty when many alternatives exist, scaled by fit competition
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0) * norm_post;
    }

    // Lookahead: penalize leaving residual that cannot fit the next item,
    // reward residual that exactly accommodates it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= post {
            let gap = post - ni;
            score -= 8.0 * (1.0 - gap / cap).exp();
        } else {
            score += 6.0 * ((ni - post) / cap).min(1.0);
        }
    }

    // Coupling with mean residual: avoid drifting far from the fleet average
    score += 0.05 * (post - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when other bins can still fit the item
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // A new bin is attractive only if the item is large relative to capacity
        score -= 25.0 * norm_item * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues divisible by small "denominators"
    // (10, 20, 25, 50) are reusable by typical items; prime/odd residues are dead space.
    let mut class_bonus = 0.0;
    if post_residual % 50 == 0 {
        class_bonus = 60.0;
    } else if post_residual % 25 == 0 {
        class_bonus = 45.0;
    } else if post_residual % 20 == 0 {
        class_bonus = 40.0;
    } else if post_residual % 10 == 0 {
        class_bonus = 30.0;
    } else if post_residual % 5 == 0 {
        class_bonus = 12.0;
    } else {
        // awkward residue: penalize proportional to how prime-like it is
        class_bonus = -((post_residual % 5) as f64) * 8.0;
    }
    score -= class_bonus;

    // Lookahead coupling: does post_residual admit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward, more so if the fit is tight
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 400.0;
            } else {
                score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // next item cannot use this residual: penalize dead space creation
            score += 25.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 8.0;
        let mean_frac = mean_residual / bin_capacity as f64;
        // open a new bin if mean residual is large (open bins are fragmented)
        score += 300.0 - crowded - 200.0 * mean_frac;
        // late in the stream, prefer consolidation into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
    }

    // Mild preference for fuller bins (low residual) overall
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64).recip().min(2.0);

    // Penalize bins far from the mean residual (outlier fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (post_residual in 1..=9) are pure waste: heavily penalize.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    }
    // Medium gaps (10..=19) only useful if next item fits exactly; otherwise partial waste.
    else if post_residual >= 10 && post_residual <= 19 {
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 25.0;
        }
    }

    // --- Perfect / near-perfect fit reward ---
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // --- Next-item lookahead coupling ---
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // Reserve capacity for the lookahead item: reward keeping it placeable.
            score -= 12.0;
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // Opening a new bin is costly; strongly favor the only fitting open bin.
        score -= 45.0;
    }

    // --- Open bins pressure: discourage proliferation of bins ---
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the mean (balanced packing)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.3;

    // New-bin candidate: only attractive when item barely fits anywhere else.
    if bin_residual == bin_capacity {
        // Mild default penalty so existing bins are preferred unless heavily rewarded.
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // post-residual, this is a perfect chain -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 100.0; // perfect two-item pairing
        } else if next_item_size <= post_residual {
            // next item fits, but leftover after that is dead space
            let second_leftover = post_residual - next_item_size;
            score -= 25.0;
            score += second_leftover as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: a bin with residual far below the mean
    // is a "junk" bin; filling it is good. A bin far above the mean
    // should be preserved for large future items.
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.15;
    } else {
        score += diff * 0.05;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is huge relative
    // to capacity or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 20.0 - tightness * 25.0; // big items favor new bins
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // next item pairs perfectly with a fresh bin
        }
    }

    // Late in the stream, consolidate aggressively into fewest bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (fitting_bins_count as f64).min(3.0) * 2.0;

    // Penalize leaving residuals too small to be useful (< 10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0; // tiny unusable slivers
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to wasted pairing potential
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible (favor balanced fills);
    // late in the stream, prefer closing bins out aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_res_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += (1.0 - progress) * 8.0 * mean_res_gap;   // early: prefer below-average residual bins? no—prefer bins with MORE residual to stay flexible is wrong; favor bins tighter than mean
    score -= progress * 10.0 * mean_res_gap;          // late: favor bins with less residual (close them)

    // Discourage opening new bins when good fitting options exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
        // but if nothing fits (this is effectively the only candidate), the base residual dominates anyway
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // early stream: new bins are cheap and useful for future large items
        if progress < 0.3 {
            score -= 6.0;
        }
    }

    // Mild pressure to spread load across bins when many are open.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = post / cap; // 0..1 fraction of space left after placement

    // Base: prefer tight fits (low post_residual), with smooth non-linear shaping.
    let mut score = post;

    // Quadratic/cubic coupling of residual fraction with stream progress:
    // early on, tolerate larger residuals slightly (future items may fill them);
    // later, penalize dead space super-linearly.
    let g = fit_norm * (1.0 - fit_norm) * 4.0; // peaks at 1 mid-fill
    score += (1.0 - progress) * (fit_norm * fit_norm) * 12.0
           - progress * (g * g) * 6.0;

    // Smooth interaction: large item into tight bin is valuable.
    let item_norm = item_size as f64 / cap;
    score -= item_norm * (1.0 - fit_norm) * 8.0;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // many fitting bins: mild penalty for leaving fragmentation
        score += fit_norm * 2.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= (1.0 - slack / cap) * 10.0;
        } else {
            // next item cannot use leftover; penalize proportional to unusable space
            score += (post / cap) * 5.0;
        }
    }

    // New-bin candidate: penalize opening a fresh bin unless open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score = cap + 30.0 * frag + 10.0 * (1.0 - progress);
    }

    // Mild regularization toward mean residual state.
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of common
    // item granularities (10, 20, 25) is more reusable -> reward it.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.5; }
        if pr % 50 == 0 { score -= 4.0; }
    } else {
        // Perfect fit: strongly reward.
        score -= 25.0;
    }

    // Small awkward dead space (1..=9) is nearly unusable: penalize via harmonic penalty.
    if pr > 0 && pr < 10 {
        score += 8.0 - pr as f64; // smaller residual = worse
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is a perfect two-step chain -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 { score -= 4.0; }
            score -= (gap.min(30) as f64) * 0.1;
        } else {
            // next item cannot follow here; penalize proportionally to overflow
            let over = next_item_size - post_residual;
            score += (over.min(40) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline slightly above a decent fit,
    // but attractive when all open bins have tiny residuals.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (post_residual as f64);
        if fitting_bins_count == 0 { score -= 30.0; }
        if open_bins_count == 0 { score -= 40.0; }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Tight-fit bonus: item fills most of the bin -> reward.
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.8 { score -= 6.0; }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a straggler bin; using it consolidates state -> small reward.
    let res_f = bin_residual as f64;
    if res_f + 1.0 < mean_residual {
        score -= (mean_residual - res_f).min(20.0) * 0.2;
    }

    // Harmonic class threshold on post_residual via integer division:
    // residual in [10,30] band is a sweet spot for medium items.
    if pr >= 10 && pr <= 30 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals that cannot fit even the smallest item (dead space).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residual that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open bins pressure: discourage spreading across many bins when alternatives exist.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin bonus: strongly favor the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0 + (post_residual as f64 - 20.0).abs() * 0.5;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Early stream: slightly favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead reward: next item fits snugly (small leftover after next placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + after_next);
    }

    // Penalize residuals that are too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.3 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mildly discourage opening new bins as stream progresses if open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer filling larger-residual bins first (best-fit flavor).
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or mean residual is low relative to remaining demand.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        if mean_residual < 0.35 * cap && fitting_bins_count > 0 {
            score += 20.0; // keep using existing bins when they are poor anyway? no: penalize new bin mildly
            score -= 5.0 * progress;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        score += 6.0 * crowding.min(3.0);
    }

    // Mild preference to fill bins with larger residuals when many bins are open.
    score += 0.05 * (open_bins_count as f64);
    score -= 0.02 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth quadratic-cubic shaping of residual across the stream:
    // early stream: tolerate larger residuals (open bins); late stream: penalize waste
    let w = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 30.0 * w * norm_pr * norm_pr * cap / 100.0;

    // Cubic interaction: reward tight fits (small post_residual) increasingly over time
    score -= 20.0 * (1.0 - w) * (norm_pr - 0.5) * (norm_pr - 0.5) * (norm_pr - 0.5);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 25.0 * w;
    }

    // Lookahead: reward if next item fits in the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64) / cap) * (1.0 - w);
    } else if next_item_size > 0 {
        score += 6.0 * w;
    }

    // Mean-residual coupling: prefer bins below mean residual (compact bins) mildly
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / cap;
        score += 25.0 * (1.0 - avg_tightness) * (1.0 - avg_tightness) + 10.0 * (1.0 - w);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // sizes are more reusable, so reward them (subtract from score).
    let pr = post_residual;
    let mut reusable_bonus = 0.0f64;
    if pr == 0 {
        reusable_bonus += 30.0; // perfect fit: best possible outcome
    } else {
        if pr % 10 == 0 { reusable_bonus += 8.0; }
        if pr % 20 == 0 { reusable_bonus += 6.0; }
        if pr % 25 == 0 { reusable_bonus += 5.0; }
        if pr % 50 == 0 { reusable_bonus += 7.0; }
        // Dead-space classes: tiny unusable remainders are penalized.
        if pr < 10 { reusable_bonus -= 25.0; }
        else if pr <= 15 { reusable_bonus -= 10.0; }
    }
    score -= reusable_bonus;

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits: strong reward, scaled by how snugly it fits.
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 + 0.15 * slack;
            if (pr - next_item_size) % 10 == 0 { score -= 5.0; } // leaves harmonic residue
        } else {
            // Next item cannot fit here: penalize by the overflow gap.
            let gap = (next_item_size - pr) as f64;
            score += 0.35 * gap;
            // Harmonic near-miss: gap is small and divisible by 5 -> still bad but less so
            if gap <= 10.0 { score += 6.0; }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if pr < 10 { score += 20.0; } // but not if it creates dead space
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins, but reduced when open bins are nearly full or many.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 14.0;
        new_bin_penalty -= 8.0 * progress; // later in stream, consolidation matters more
        new_bin_penalty += 0.4 * open_bins_count as f64;
        if mean_residual < item_size as f64 { new_bin_penalty -= 10.0; } // no bin can usefully absorb
        score += new_bin_penalty.max(0.0);
    }

    // Fragmentation pressure: penalize leaving residual far from harmonic
    // classes relative to the mean residual of open bins.
    let frag = (pr as f64 - mean_residual).abs();
    score += 0.05 * frag;

    // Integer-division threshold: residual in [40, 60] is highly flexible.
    let half_class = (pr / 25) as f64;
    if half_class >= 1.0 && half_class <= 2.0 { score -= 4.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual gap is "dead" if no realistic future item (min size 1..10)
    // can plausibly fill it; small gaps waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item if the
    // next item is small enough to matter but larger than the gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Only penalize moderately if the gap is genuinely tiny.
        if post_residual < 20 {
            score += 25.0;
        }
    }

    // Reward closing off a bin when the next item fits elsewhere better:
    // if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize opening new ones / spreading).
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // current bin would leave a big messy residual vs a fresh bin.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: its post_residual equals capacity - item_size,
        // already in score. Add slight bias so tight fits in existing bins win.
        score += 15.0;
        // But if no existing bin fits well (many open bins, none fitting),
        // opening fresh is fine: relieve pressure.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference for bins with below-average residual (tighter bins),
    // keeping looser bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in the stream, be more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size, penalize near-misses that strand space.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff == 0.0 {
            score -= 80.0; // chain two items perfectly
        } else if next <= post {
            // Next item fits here afterwards: mild reward proportional to slack left after both.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize stranded dead space.
            score += 10.0 + 0.3 * diff;
        }
    }

    // Compare against mean residual: bins below mean residual are already
    // "tight"; filling them further is efficient. Above-mean bins keep slack.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or current bins are nearly all unusable.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize dead space: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits into post_residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = post_residual - next_item_size;
        score -= (bin_capacity - next_waste.min(bin_capacity)) as f64 * 0.15;
        if next_waste < 10 {
            score -= 8.0;
        }
    }
    // Penalize if next item cannot use the leftover space (potential dead space).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins flexible); later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= (1.0 - progress) * 20.0;
        score += progress * 30.0;
        // Don't open a new bin if an open bin fits nearly perfectly.
        if post_residual < 15 && bin_residual != bin_capacity {
            score += 10.0;
        }
    } else {
        // Prefer filling existing bins more as the stream progresses.
        score -= progress * 10.0;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 && bin_residual < bin_capacity {
        score -= 5.0;
    }
    // Few open bins -> opening a new bin is relatively cheap.
    if open_bins_count <= 2 {
        score += 3.0 * (1.0 - progress);
    }

    // Mild preference for bins whose residual is close to item size (best fit).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += slack * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, dead space matters more.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress) + 0.5 * pr_norm * progress * progress;
    score += 40.0 * poly;

    // Reward bins whose residual exactly matches the lookahead item (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= 15.0 * (-10.0 * diff * diff).exp();
    }

    // Penalize last-chance bins mildly unless the fit is tight (encourage using them when tight).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (item_size as f64 / bin_residual as f64);
        score += 8.0 * tightness;
    }

    // New-bin candidate: penalize opening new bins, more strongly early in the stream
    // and when many bins are open with slack.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference for bins below mean residual (consolidating space).
    score += 3.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity octaves and reward bins whose leftover can still host
    // meaningful future items.
    let post = post_residual as f64;
    let octave = (post / (cap / 8.0)).floor(); // 0..8 harmonic class
    score -= octave * 2.5; // larger leftover class => more reusable => favored

    // Perfect / near-perfect fits (harmonic closure classes)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: leftover too small for the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match reward
            if post_residual % next_item_size.max(1) == 0 {
                score -= 18.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size as f64 - post) * 0.6;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor (small) residuals. Penalize opening a new bin unless the
    // stream is early or open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_r = mean_residual;
        // opening cost grows with number of open bins and stream progress
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // but if mean residual is small (bins nearly exhausted), opening is fine
        score -= (cap - mean_r) * 0.5;
        // early stream: cheaper to open
        score -= (1.0 - progress) * 15.0;
    }

    // Mild preference for tighter bins overall (waste minimization)
    score += (bin_residual as f64 - post) * 0.1;

    // Integer division threshold on post_residual: quarter classes
    let quarter = post_residual / 25; // 0..4
    score -= quarter as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Mild reward for tight fits (post_residual small but usable).
    if post_residual >= 10 && post_residual < 30 {
        score -= 8.0;
    }

    // If this bin's post-residual can host the next item, reward the lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just below the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless dead space penalty dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 15.0 + 6.0 * (open_bins_count as f64).sqrt();
        // But if no existing bin fits, opening is fine: fitting_bins_count excludes this new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins with below-average residual (consolidate waste).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late-stream tightening: as the stream progresses, be stricter about wasted space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use
        score += 0.3 * (next_item_size as f64 - post_residual as f64).abs();
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Relative residual coupling: prefer bins tighter than the mean
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize wasting a nearly empty bin when many bins are open
    if bin_residual as f64 > 0.9 * bin_capacity as f64 && open_bins_count > 1 {
        score += 20.0;
    }

    // Early in the stream, be more willing to open fresh bins for large items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress) - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount for small post-residual.
    score -= 0.6 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // Chain fit: exact two-item packing is excellent.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: make fresh bins attractive when existing
    // residuals are large but fragmented, or late in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early: prefer filling open bins; late: opening fresh bins is fine.
        score += 55.0 * (1.0 - progress);
        // Penalize opening new bins when many are already open and loose.
        score += 0.8 * open_bins_count as f64;
        if mean_residual > item_size as f64 + 20.0 {
            score += 15.0;
        }
        // If next item is huge, a fresh bin with full room is valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Reward using bins that deviate favorably from mean residual
        // (consolidating into emptier bins keeps tight bins for small items).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Global pressure: many open bins -> discourage waste to avoid sprawl.
    score += 0.05 * open_bins_count as f64 * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (penalize large post_residual more via cubic term).
    // Late stream: allow larger residuals, reward using existing bins.
    let pr_norm = post / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * pr_norm * pr_norm * progress;
    score += 30.0 * poly;

    // Reward bins that also fit the next item (smooth lookahead coupling).
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64 <= post) as f64;
        let tight_next = 1.0 - ((post - next_item_size as f64).abs() / cap).min(1.0);
        score -= 12.0 * next_fits * tight_next * (0.5 + 0.5 * progress);
    }

    // Penalize dead space (small post_residual that can't fit typical items).
    let dead = (1.0 - pr_norm) * pr_norm; // peaks mid-range
    score -= 8.0 * dead * (1.0 - progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild congestion penalty: many open bins -> prefer filling them.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm) * 2.0;

    // Smooth deviation from mean residual: prefer bins near mean early, tighter late.
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - 0.5 * progress);

    // Never reward opening a new bin unless residual is truly unusable.
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * (1.0 - pr_norm) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into residue classes mod 10 (dead-space bands)
    let post_class = post_residual % 10;
    let next_class = if next_item_size > 0 { next_item_size % 10 } else { 0 };

    // Reward when post_residual residue class matches next item's residue class (harmonic pairing)
    if next_item_size > 0 && post_residual >= next_item_size {
        let harmony = (post_class as i32 - next_class as i32).abs() as f64;
        score -= 6.0 * (10.0 - harmony) / 10.0;
        // Strong reward if next item fits exactly-ish
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual - next_item_size <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this residual
        score += 10.0 + post_residual as f64 * 0.2;
    }

    // Integer division thresholds on post_residual: penalize awkward tiny remainders
    let q = post_residual / 10;
    if q == 0 {
        score += 12.0; // residual < 10 is nearly dead space
    } else if q <= 2 {
        score += 4.0;
    } else if q >= 5 {
        score -= 3.0; // large residual left is flexible
    }

    // Penalize odd residue classes that rarely pair well (1,3,7,9 style dead zones)
    if post_class == 1 || post_class == 3 || post_class == 7 || post_class == 9 {
        score += 2.5;
    } else if post_class == 0 {
        score -= 2.0; // round residuals are versatile
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // Capacity fraction coupling: prefer tight fits
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // Slight preference to keep many open bins balanced when late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual as f64 > mean_residual * 1.5 && open_bins_count > 1 {
        score += 3.0 * progress; // avoid leaving overly fat bins unused late
    }

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: fresh bin has future value
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest item (1..100 range, min item 1)
    // Treat gaps below a "useful threshold" as dead weight with super-linear penalty.
    let useful_threshold = 20.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < useful_threshold {
        score += (useful_threshold - pr) * (useful_threshold - pr) * 0.5;
    }

    // Reward tight fits: post_residual near zero is ideal
    score -= (bin_capacity as f64 - pr) * 0.1;

    // Open bins pressure: penalize selecting bins when many bins are open,
    // but reward using existing bins when few are open (avoid proliferation).
    score += open_bins_count as f64 * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (more filled bins)
    score -= (mean_residual - pr) * 0.3;

    // Slight bias toward opening new bins early in the stream (plenty of future items to fill them)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize large post_residual generally (wasted capacity), super-linear
    score += pr * pr * 0.005;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Exact fit is gold
    if post_residual == 0 {
        score -= 120.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, heavily favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further waste: mild penalty scaled by slack
            let slack = post_residual - next_item_size;
            score += 0.35 * slack as f64;
        } else {
            // next item won't fit here: penalize leaving large dead space
            let overhang = (next_item_size - post_residual) as f64;
            score += 0.25 * overhang;
        }
    }

    // Compare residual against mean residual of open bins: prefer bins tighter than average
    score += 0.30 * ((post_residual as f64) - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize unless post_residual would be large enough to be useful
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual >= 50 {
            score -= 25.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate aggressively into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: small post-residual relative to item size is good
    let tightness = post_residual as f64 / (item_size as f64).max(1.0);
    score -= 50.0 * (1.0 - tightness.min(1.0));

    // Penalize dead space that cannot fit even the smallest item (assume min ~1)
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax penalty
    // when no open bin fits well (this call is the empty-bin candidate itself).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 250.0 * (1.0 - 0.5 * progress);
        // If lookahead item is large and current item is large, a fresh bin is attractive
        if next_item_size > 0 && next_item_size as f64 + post_residual as f64 <= bin_capacity as f64 {
            new_bin_penalty -= 60.0;
        }
        // Many open bins with large mean residual: prefer existing bins
        new_bin_penalty += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64).max(0.0);
        score += new_bin_penalty;
    }

    // Lookahead synergy: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 30.0 + 20.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post-residual too small for next item: penalize proportionally to waste
        score += 15.0;
    }

    // Prefer bins with residual above mean (keeps small bins for small items)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in stream: be more aggressive about filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild preference to keep many moderately-filled bins rather than one very full
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth coupling with stream progress: later in stream, penalize large residuals more
    score += 20.0 * norm_post * norm_post * progress;

    // Reward tight fits (small post residual) more strongly as progress grows
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize bins far from mean residual (encourage homogeneity), smoothly
    let dev = (post - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post);
    }

    // Lookahead: reward if next item fits post residual, penalize near-miss
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (nxt / cap) * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Mild penalty for too many open bins relative to progress
    score += 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" space classes.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: residuals that are small but nonzero are nearly useless.
    if pr > 0 && pr < 10 {
        score += 25.0 * (10.0 - pr as f64) / 10.0;
    }
    // Perfect fit reward (zero waste).
    if pr == 0 {
        score -= 30.0;
    }
    // Harmonic bonus: residuals divisible by 10 are "clean" classes (item sizes 10..80
    // frequently align with multiples of 10), so prefer leaving such space.
    if class == 0 && pr > 0 {
        score -= 6.0;
    } else if class == 5 {
        score -= 3.0;
    } else {
        score += 2.0; // odd/awkward residue classes
    }

    // Integer-division threshold: post_residual bucket by pr / 20.
    let bucket = pr / 20; // 0..5
    score += bucket as f64 * 4.0; // larger leftover space is fine (bin still reusable)

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            // harmonic class of the gap after next placement
            if gap % 10 == 0 {
                score -= 8.0;
            } else if gap < 10 {
                score += 10.0; // creates dead space for the item after next
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap_f);
        // Penalize new bin mildly; the penalty shrinks if mean residual is low (all bins tight)
        let mut nb = 18.0 + crowd * 3.0;
        if mean_residual < 25.0 {
            nb -= 22.0; // open bins are nearly full -> new bin is fine
        }
        if item_size >= 60 && mean_residual < item_size as f64 * 0.4 {
            nb -= 15.0; // big item, no good home
        }
        if progress > 0.9 && open_bins_count > 3 {
            nb += 8.0; // late stream: avoid bin proliferation
        }
        score += nb;
    }

    // Mild preference to pack into bins below mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is gold
    }

    // Reward tight fits: post_residual small relative to item_size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage opening new bins when many are open.
    score += 3.0 * open_bins_count as f64;

    // If this bin is the last chance to avoid a new bin, favor it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits this bin's post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates usefully.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 10.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 30.0; // strong bias against opening when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item exactly or nearly fills the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 - gap.min(60.0);
        // Perfect 2-step closure: item + next item fill the bin exactly.
        if gap == 0.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the resulting residual: penalize proportional dead space.
        let overflow = (next_item_size - post_residual) as f64;
        score += overflow * 0.8;
    }

    // Penalize residual far above the mean residual (creating an outlier hole).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Reward tightening the bin relative to its current residual.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it unattractive unless current placement is terrible.
    if bin_residual == bin_capacity {
        // Attractive only if this is the last item or no open bin fits well.
        if next_item_size == 0 {
            score += 50.0;
        } else {
            score += 20.0;
        }
    }

    // Slight late-stream conservatism: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect chaining: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * fitting_bins_count as f64;
        // But opening a fresh bin early in the stream is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Prefer bins with residual below the mean (consolidate waste).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for bins that are already fairly full.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = 100.0 * x * x + 30.0 * x;

    // Smooth coupling of post residual with stream progress:
    // later in stream -> penalize large residuals more strongly
    let progress_coupling = (1.0 + 4.0 * progress) * x * x * x * cap * 0.5;
    score += progress_coupling;

    // Penalize residual that is far from mean residual (dead-space dispersion),
    // scaled smoothly by progress
    let disp = (pr - mean_residual).abs() / cap;
    score += 20.0 * disp * disp * (0.5 + progress);

    // Reward tight fits: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill * fill;

    // Lookahead: if next item fits exactly into post residual, reward strongly
    if next_item_size > 0 {
        let diff = (pr as i64 - next_item_size as i64).abs() as f64;
        let nf = next_item_size as f64 / cap;
        score -= 12.0 * nf * (1.0 - diff / cap);
        // penalize leaving residual that is just slightly too small for next item
        if (pr as i64) < (next_item_size as i64) && diff < 20.0 {
            score += 10.0 * (1.0 - diff / 20.0) * (1.0 - diff / 20.0);
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: mild penalty early (prefer packing), relax late when
    // open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 8.0 - 6.0 * progress + 2.0 * fragmentation.min(5.0);
    }

    // Small bonus for many fitting bins (flexibility preserved)
    score -= 1.5 * (fitting_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual buckets via integer division on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class of post_residual by quarter-capacity thresholds
    let quarter = (bin_capacity / 4) as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fit: ideal
    } else if post_residual <= bin_capacity / 10 {
        score -= 25.0; // near-perfect, tiny dead space
    } else if post < quarter {
        score += 10.0; // dead space under quarter capacity is bad
    } else if post < 2.0 * quarter {
        score -= 5.0; // usable half-ish remainder
    } else {
        score -= 12.0; // large remainder still very usable
    }

    // Modulo classes: residual mod 10 — small remainders of common item classes
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // aligns with decile item classes
    } else if m <= 2 {
        score += 3.0;
    }

    // Coupling with next item: reward if next_item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // modulo harmonic match: next item class divides residual
        if post_residual % next_item_size.max(1) == 0 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0
            + mean_residual * 0.3
            + (open_bins_count as f64).sqrt() * 2.0
            + (1.0 - step_index as f64 / total_items.max(1) as f64) * 5.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // next item won't fit here anyway; open early
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 / cap) * 5.0;

    // Tightness reward: closer fit to residual is better (relative waste)
    score += (item_size as f64 / bin_residual.max(1) as f64) * -4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 12.0 {
                score += slack * 3.0; // next item would leave dead space
            } else {
                score -= 10.0;
            }
        }
    }

    // Mild preference for filling bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight late-stream conservatism: keep residuals flexible as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post-residual that exactly matches
    // the next item, or that leaves a "good" gap relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // Perfect match for the next item is a huge bonus.
        if diff < 0.5 {
            score -= 40.0;
        } else if post >= nxt {
            // Partial reward proportional to how close the leftover is to next item.
            score -= (nxt / (post + 1.0)) * 15.0;
        } else {
            // Post-residual smaller than next item: dead space penalty scaled by
            // how much of the next item cannot fit.
            score += ((nxt - post) / nxt) * 10.0;
        }
    }

    // Compare against mean residual: bins far below mean residual are already
    // tight; prefer them (low residual = tight packing), penalize loose bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is wasteful unless current bin
    // leaves unusable dead space. Penalize new bins mildly, more so early on.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 - 10.0 * progress;
        // If next item fits perfectly in a fresh bin too, slightly soften.
        if next_item_size > 0 && (next_item_size as f64 - item_size as f64).abs() < 1.0 {
            score -= 5.0;
        }
    }

    // Penalize leaving tiny unusable gaps (dead space <= 5).
    if post_residual > 0 && post_residual <= 5 {
        score += 12.0;
    }
    // Reward leaving zero residual (perfect fill).
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with a slight convexity bonus
    // for very tight fits (post_residual near 0 is disproportionately good).
    let pr = post_residual as f64;
    score += 0.35 * (pr / 10.0).powi(2);

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item cannot fit, penalize dead space proportional to its size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 6.0 + 0.25 * slack_after_next as f64;
        } else {
            score += 0.18 * nxt * (1.0 + pr / 50.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that keep future flexibility
        // (larger residual after placement is mildly better here).
        score += 0.06 * pr;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and the global state suggests congestion (few fitting bins, high mean residual waste).
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64).max(1.0).ln() / 3.0;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_waste = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Opening is attractive for big items when existing bins are fragmented.
        let open_bonus = 8.0 * item_frac * (0.5 + mean_waste) - 10.0 * congestion;
        score += 12.0 - open_bonus;
    }

    // Time horizon: early in the stream, be more conservative with tight fits
    // (keep flexibility); late in the stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Prefer bins whose residual is already below average (consolidating waste).
    score += 0.08 * (pr - mean_residual);

    // Fragmentation guard: penalize residuals that are hard to fill later
    // (classic awkward sizes around 1..20 relative to capacity).
    if pr > 0.0 && pr < 20.0 {
        score += 5.0 * (1.0 - pr / 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) * cap * 0.5;
    // Penalize large post_residual more as stream progresses
    let mut score = base + poly * (0.5 + progress);
    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0 * (1.0 - progress);
    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }
    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 {
        // penalize dead space that cannot host the next item
        score += (pr - next_item_size as f64).max(0.0) * 0.05;
    }
    // Slight preference to keep many small open bins consolidated
    score += open_bins_count as f64 * 0.1;
    // New-bin candidate: penalize opening a new bin mildly, more so late in stream
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let cap_frac = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual exactly 0 -> perfect packing, huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }
    // Class B: residual in small dead zone (1..=9) -> dead space penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    }
    // Class C: residual divisible by common sizes 10,20,25,50 -> reusable class.
    let r = post_residual;
    if r % 10 == 0 { score -= 25.0; }
    if r % 25 == 0 && r > 0 { score -= 15.0; }
    if r % 50 == 0 && r > 0 { score -= 20.0; }

    // Fraction-of-capacity thresholds on post_residual.
    let frac = pr / cap_frac;
    if frac < 0.1 { score += 30.0; }          // sliver residual
    else if frac < 0.3 { score -= 10.0; }      // tight but usable
    else if frac > 0.8 { score += 15.0; }      // nearly empty bin used wastefully

    // Next-item lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item fits a residue class of the new residual
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 { score -= 35.0; } else { score -= 15.0; }
        } else {
            // Next item won't fit here: residual becomes dead unless small
            if post_residual < next_item_size {
                score += 0.35 * (post_residual as f64);
            }
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer filling bins that are already partially loaded (fewer open bins).
    score += 0.5 * (open_bins_count as f64);
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate (empty bin): penalize unless current stream is early
    // or all fits would be terrible.
    if bin_residual == bin_capacity {
        score += 40.0;
        if step_index == 0 { score -= 100.0; }
        if fitting_bins_count == 0 { score -= 300.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small for any future item are wasted.
    let dead_threshold = 9u32; // smallest item is 1..100 unknown; treat tiny gaps as dead
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0;
    }

    // Penalize gaps that cannot fit the lookahead item (k=2 lookahead waste),
    // but only mildly if some other bin could take it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: small positive post_residual is good.
    if post_residual > 0 {
        score -= 25.0 * (1.0 - post_residual as f64 / (bin_capacity as f64 * 0.5));
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // (mean residual low) or the item is huge and fits nothing well.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 0.35 * bin_capacity as f64;
        let pressure = open_bins_count as f64 / (2.0 + step_index as f64 / (total_items.max(1) as f64));
        if crowded {
            score += 30.0 + 20.0 * pressure;
        } else {
            score += 120.0 + 40.0 * pressure;
        }
        // Slightly encourage new bin for very large items that leave big gaps elsewhere.
        if item_size > bin_capacity * 3 / 4 {
            score -= 25.0;
        }
    }

    // Mild progress term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 10.0;
        // Small residual unusable by typical items is dead space.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer filling below-average-residual bins.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Never prefer a brand-new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Lookahead coupling: reward if the next item can also fit in the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            // Dead space that the next item cannot use: penalize proportionally,
            // but only for small leftovers (large leftovers may serve later items).
            let dead = post_residual as f64;
            if dead < 30.0 {
                score += dead * 0.6;
            } else {
                score += dead * 0.15;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 22.0;
        if fill_ratio > 0.5 {
            score -= 10.0;
        }
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (new bins are cheap over a long horizon); late in the stream, consolidate.
    let t = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = (1.0 - t) * 10.0;
    // A brand-new empty bin candidate has bin_residual == bin_capacity; make its
    // score sensitive to stream position.
    if bin_residual == bin_capacity {
        score += new_bin_bias;
        // Don't open a new bin when the current item fits snugly somewhere.
        if fill_ratio > 0.7 && open_bins_count > 0 {
            score += 25.0;
        }
    }

    // Global state: high mean residual across open bins means capacity is
    // plentiful; slightly discourage stuffing more into already-loose bins.
    score += 0.08 * mean_residual;
    // Many open bins: encourage consolidation to avoid bin sprawl.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for using bins whose residual is close to the item size,
    // independent of post_residual (captures fragmentation quality).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += poly * 40.0;
    // Penalize dead space more strongly late in the stream
    score += (norm_post * norm_post * norm_post) * (progress * 60.0);
    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 25.0;
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Lookahead coupling: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // Prefer bins with residuals below the mean (concentrate free space)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 10.0 * (0.5 + progress);
    // Mild penalty for opening a new bin when other bins fit
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 8.0 + 15.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes (hard to reuse) get penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Modulo-10 harmonic classes: residues < 10 are dead space
    let dead = post_residual % 10;
    score += dead as f64 * 0.8;

    // Integer-division thresholds on post_residual
    let q = post_residual / 10;
    score += (q as f64).powi(2) * 0.3;

    // Fraction of capacity used
    let fill = 1.0 - pr / cap;
    score -= fill * 20.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item's residue class vs post_residual
            let slack = post_residual - next_item_size;
            score += slack as f64 * 0.5;
            if slack % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot reuse this residue: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        score = pr - 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // prefer new bin when mean residual is large but fragmented
        score -= mean_residual * 0.05;
        // late in stream, avoid opening bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are dead,
    // but practically residuals below a "usefulness band" waste capacity.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(6) {
        score += 1000.0; // unusable sliver
    }
    // Penalize small-but-likely-unusable gaps nonlinearly
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 12.0 {
            score += (12.0 - gap) * 8.0;
        }
    }

    // Reward tight fits (small post_residual) more aggressively
    score -= (bin_residual as f64 - post_residual as f64).max(0.0) * 0.5;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless item is large relative to residual
    if bin_residual == bin_capacity {
        score += 25.0;
        // large items fill a fresh bin efficiently; slightly soften penalty
        if item_size >= bin_capacity * 7 / 10 {
            score -= 20.0;
        }
        // if current bin would leave a bad gap anyway, new bin less bad
        if post_residual > 0 && post_residual < 12 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0; // next item can't use this bin; slight penalty for blocking
    }

    // Mean residual coupling: prefer bins deviating below mean (consolidating)
    score += (mean_residual - post_residual as f64) * 0.1;

    // Early stream: be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fit (post_residual == next_item_size)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit: next item exactly fills this bin
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += gap * 0.35;
            // If next item still fits comfortably, mild reward
            if post_residual >= next_item_size {
                score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
            }
        }
        // Penalize leaving residuals that no future item can use well
        if post_residual < next_item_size {
            score += 12.0; // dead space relative to lookahead
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 20.0;
    }

    // Reward tight packing relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins as stream progresses (consolidation pressure)
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference to keep number of open bins low
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space: small post-residuals that are hard to reuse (below ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // creating unusable sliver
    } else {
        // reward post_residual that can host typical future items
        score -= 0.15 * post_residual as f64;
    }

    // Lookahead: if next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful when other bins fit and mean residual is healthy.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual / bin_capacity as f64;
        score += 30.0 + 25.0 * waste + 15.0 * (1.0 - progress);
        // But allow new bin if item is large relative to capacity and mean residual small.
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (i.e., tighter bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 0.5 * dev; // bin is tighter than average: good target
        } else {
            score += 0.3 * (-dev); // bin looser than average: deprioritize
        }
    }

    // Mild time-horizon term: early in the stream, be frugal with bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Slight preference to spread across fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item_f = item_size as f64;
    let next_f = next_item_size as f64;

    // Base: prefer small post-residual, with non-linear squashing
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, tight fits (small pr) are rewarded more aggressively
    let tightness = 1.0 - norm_pr;
    score -= 2.0 * tightness * tightness * progress;

    // Penalize leaving residual that is smaller than the next item but nonzero (dead space)
    if next_f > 0.0 && pr > 0.0 && pr < next_f {
        score += 1.5 * (next_f - pr) / cap * (1.0 + progress);
    } else if next_f > 0.0 && pr >= next_f {
        // reward leaving room for the lookahead item
        score -= 0.8 * (next_f / cap) * (1.0 - progress);
    }

    // Non-linear penalty on residual far from both 0 and usable sizes (fragmentation)
    let frag = norm_pr * (1.0 - norm_pr); // peaks at pr = cap/2
    score += 1.2 * frag * frag * (1.0 - progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New empty bin candidate: penalize mildly, more so when other bins fit the item
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 2.5 + 0.1 * open_f.sqrt() + 2.0 * progress;
    }

    // Mild preference for bins with residual close to item (best-fit flavor, smooth)
    let diff = (bin_residual as f64 - item_f) / cap;
    score += 0.5 * diff * diff;

    // Slight tie-break toward bins with lower mean residual context (consolidation)
    score += 0.05 * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: penalize residuals in "awkward"
    // classes that few item sizes can fill, reward near-full or clean classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual that is neither 0 nor large enough for the
    // smallest plausible item (<= ~10% of capacity) is wasted space.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 4.0;
    }

    // Modulo-class bonus: residuals that are multiples of common size classes
    // (e.g. 10, 20, 25, 50) are easier to fill later.
    let class_bonus = if post_residual % 10 == 0 { 6.0 }
        else if post_residual % 5 == 0 { 3.0 }
        else if post_residual % 2 == 0 { 1.0 }
        else { 0.0 };
    score -= class_bonus;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.15;
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty proportional to overshoot.
        score += ((next_item_size - post_residual) as f64) * 0.25;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Prefer tighter bins: scale by how full the bin already is.
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= fullness * 10.0;

    // New-bin candidate: make it unattractive unless the item is huge relative
    // to the residual and no good fit exists. Penalize opening a new bin when
    // many bins can already fit the item.
    if bin_residual == bin_capacity {
        score += 12.0 + (fitting_bins_count as f64) * 3.0;
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
    }

    // Slight preference for bins below mean residual (balance-aware).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight relative fits.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins when residuals are large.
    let avg_res = mean_residual.max(0.0);
    let pressure = open_bins_count as f64 * avg_res / bin_capacity as f64;
    score -= 8.0 * pressure;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // leaves a healthy residual or the item is large.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 10.0; // large items pack well into fresh bins
        } else {
            score += 20.0 + 0.5 * (item_size as f64);
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    } else {
        // Lookahead: if next item fits exactly into post_residual, reward heavily.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else if next_item_size > post_residual {
            // Next item won't fit here; penalize leaving a gap it can't use.
            score += 6.0;
        }
    }

    // Slight late-stream conservatism: reuse existing bins more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fits post_residual,
    // reward if it fits at all, penalize near-miss dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 1.5;
        } else {
            // next item can't use the leftover: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 50.0;

    // Penalize leaving tiny unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Prefer bins with below-average residual (denser bins) mildly
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make it unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 400.0 + open_bins_count as f64 * -0.0;
        // allow new bin when current item is large and would leave bad residue elsewhere
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 350.0;
        }
    }

    // Late-stream consolidation: as stream progresses, discourage opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Partial reward proportional to how much of post-residual the next item consumes.
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 10.0 * fill;
        } else {
            // Next item won't fit here anyway; slight penalty for leaving awkward gap.
            score += 2.0;
        }
    }

    // Coupling with global state: when mean residual across bins is high,
    // encourage consolidating items into existing bins rather than opening new ones.
    let mean_res = mean_residual;
    if bin_residual <= bin_capacity {
        // For open bins, reward when bin residual is below mean residual (denser bin).
        if (bin_residual as f64) < mean_res {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless necessary.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // If many bins already fit the item, opening a new bin is bad.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64);
        }
        // Early in the stream, opening new bins is cheaper (more items to come).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If next item is large relative to capacity, a fresh bin may be valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Dynamic time horizon: late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 5.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Mild penalty proportional to number of open bins to discourage bin proliferation.
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = (pr / cap).clamp(0.0, 1.0);
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like base
    score += poly * (20.0 + 30.0 * progress) - 20.0 * (1.0 - poly) * (1.0 - progress);

    // Penalize small dead space more as stream progresses (dead space becomes permanent cost).
    let dead = (pr / cap).clamp(0.0, 1.0);
    score += dead * dead * (1.0 - dead) * 15.0 * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 25.0 * (1.0 - progress);

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 10.0 + 15.0 * (next_item_size as f64 / cap);
        } else {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mean residual coupling: prefer bins near the mean to keep balance, more so late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (dev / cap) * 12.0 * (0.3 + 0.7 * progress);

    // Slight preference for fewer open bins early on.
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by small
    // integers (2,4,5,10) are "usable classes" likely to host future items.
    let harmonic_bonus = if post_residual > 0 {
        let mut h = 0.0;
        if post_residual % 10 == 0 { h += 8.0; }
        else if post_residual % 5 == 0 { h += 5.0; }
        else if post_residual % 4 == 0 { h += 4.0; }
        else if post_residual % 2 == 0 { h += 2.0; }
        h
    } else {
        12.0 // perfect fit
    };
    score -= harmonic_bonus;

    // Penalize dead space that is too small to hold even the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Integer-division threshold: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 && post_residual > 0 {
        score += 15.0; // sliver waste
    } else if frac > 0.5 {
        score -= 6.0; // half-full bin remains attractive
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly
    // or in a harmonic class.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0; // exact division: perfect future fill
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when open bins
    // are congested (low mean residual relative to item).
    if bin_residual == bin_capacity {
        let congestion = item_size as f64 / mean_residual.max(1.0);
        score = 30.0 + 20.0 * congestion - harmonic_bonus.min(6.0);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0; // big next item: fresh bin is fine
        }
    }

    // Mild stream-progression tiebreak to diversify bin usage late.
    score += (step_index as f64 / total_items.max(1) as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item (min size 1,
    // but practically >= 10 in classic streams) can use are pure waste.
    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space: penalize quadratically by smallness.
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // Awkward small gap: mildly penalize.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to bin size).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This placement strands the next item elsewhere; small penalty.
        score += 4.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, new bins are even less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Encourage using existing bins, especially when few fit.
        if fitting_bins_count <= 1 {
            score -= 20.0; // last-chance bin: use it to avoid opening a new bin
        }
        score -= 1.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (consolidating waste into few bins rather than spreading it).
    if !is_new_bin {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0 - 1.5 * slack;
        } else {
            score -= 10.0 / slack.sqrt();
        }
    }

    // Dead space: post_residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste;
        // Very small post_residual is nearly unusable dead space.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer filling bins whose residual deviates above the mean (tighten outlier bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Early in the stream, tolerate opening new bins to build a good residual pool.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let new_bin_bonus = 8.0 * (1.0 - progress) - 10.0 * progress;
        score += new_bin_bonus;
        // Opening a new bin is attractive if no open bin fits well.
        if next_item_size > 0 && post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: quadratic bonus for small leftover space.
    score -= 12.0 * (1.0 - post / cap).powi(3);

    // Penalize dead space that is too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post);
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0 * (1.0 - (post - nxt) / cap);
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the average residual.
    score += 0.4 * (mean_residual - post);

    // Mild preference for reusing bins as the stream progresses (consolidation).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * t * (bin_residual as f64 / cap);

    // New-bin candidate: open a new bin only when the item is large relative
    // to open-bin residuals or when bin count is low.
    if bin_residual == bin_capacity {
        let waste_threshold = mean_residual - item_size as f64;
        if waste_threshold > 25.0 || open_bins_count == 0 {
            score -= 20.0; // fresh bin is attractive
        } else {
            score += 15.0; // discourage proliferation
        }
    }

    // Early stream: allow slightly looser packing to build good bins.
    if t < 0.2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / c;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress) - 18.0 * fit_norm * (1.0 - fit_norm) * (1.0 + 0.5 * progress);

    // Penalize large unusable residuals smoothly
    if pr > 0.0 {
        score += 8.0 * (pr / c).powi(2) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (nxt / c) * (1.0 - pr / c);
        } else {
            score += 6.0 * (1.0 - pr / c) * (nxt / c);
        }
    }

    // Mild preference for consolidating into existing bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress) + mean_residual * 0.05;
    } else {
        score -= 4.0 * (bin_residual as f64 / c) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space quadratically beyond a threshold
    let dead = post_residual as f64;
    if dead > 10.0 {
        score += (dead - 10.0) * 0.5;
    }

    // Harmonic class of post_residual: residues that are "unusable" (too small
    // for the smallest plausible item) are dead space; reward exact small classes.
    let min_item = 10u32;
    if post_residual < min_item {
        score += 25.0; // fully dead slot
    } else if post_residual % 10 == 0 {
        score -= 8.0; // harmonic alignment: slot divisible into decile chunks
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: how many min-size items still fit
    let fits_small = post_residual / min_item;
    score -= fits_small as f64 * 2.0;

    // Lookahead coupling: if next item fits in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize proportionally to wasted lookahead
            score += ((next_item_size - post_residual) as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition among bins: prefer the tightest via base post_residual already
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    if bin_residual == bin_capacity {
        let decent = (mean_residual - item_size as f64).abs() < 15.0 && open_bins_count > 0;
        if decent {
            score += 40.0; // discourage opening new bin when good fits exist
        } else {
            score -= 10.0; // allow new bin when open bins are all poor fits
        }
    }

    // Stream progression: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - dead / bin_capacity as f64);

    // Mean residual context: if mean residual is high, spread items; if low, pack tight
    if (mean_residual as u32) > item_size {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Usable leftover: mildly reward closeness to a reusable chunk.
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover cannot host next item: slight penalty.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // New-bin candidate: make it moderately attractive only when current bins fit poorly
    // (i.e., item is large relative to residuals) or many bins already fragmented.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        score -= 10.0 + 30.0 * tightness - open_bins_count as f64 * 2.0;
        // Penalize new bin if a last-chance open bin exists.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
    }

    // Prefer bins with below-average residual (denser bins first).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: next item exactly fills the post-residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            // Chain fill: this bin gets perfectly closed over two steps.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but measure how "tight" the chain is.
            let chain_gap = (post - next) as f64;
            score -= 12.0 * (1.0 - chain_gap / bin_capacity as f64);
            // Penalize if next item leaves a tiny unusable sliver.
            if chain_gap > 0.0 && chain_gap < 10.0 {
                score += 15.0;
            }
        } else {
            // Next item will NOT fit here: post_residual becomes a dead zone
            // unless another item later fits. Penalize proportionally to how
            // close-but-failed the match is (worst: just barely misses).
            let miss = (next - post) as f64;
            score += 10.0 + 20.0 * (1.0 - miss / 80.0);
        }
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor),
    // penalize wasting space in bins that are already roomy.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, keep bins flexible (avoid fragmenting too soon);
    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.3 * post_residual as f64 / bin_capacity as f64;
    score -= progress * 5.0;

    // New-bin candidate: penalize opening a new bin unless residual would be
    // small relative to typical item sizes (i.e., item nearly fills it).
    if bin_residual == bin_capacity {
        score += 30.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space: residuals too small for the smallest item are wasted.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * (item_size as f64);
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the stream
    // or when many bins are open (prefer consolidating).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But allow a new bin if no open bin fits well (large item, few fitting bins).
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean: bins below mean
    // residual (tighter) get priority to be filled.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild time-horizon coupling: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with non-linear (quadratic/cubic) shaping
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * cap;
    score -= 60.0 * norm_pr * norm_pr * norm_pr * cap * (1.0 - progress);

    // Coupling post_residual with stream progress: tight fits matter more early,
    // loose residual tolerance grows late (keeping bins open for future items)
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (1.0 + 2.0 * (1.0 - progress));

    // Interaction: post_residual vs mean residual — prefer bins deviating from mean
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * cap;
    score -= 8.0 * dev * (progress * 2.0 - 1.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits into post_residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (pr - nx) / cap;
            score -= 10.0 * (1.0 - progress);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate handling: make empty bin attractive only when it beats
    // poor fits (large post_residual) or few fitting bins exist
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score = pr - 20.0 + 60.0 * scarcity * (1.0 + progress)
              + 30.0 * norm_pr * norm_pr * cap * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "waste classes".
    // Residuals that are 0 mod 10 are perfectly reusable by common item sizes.
    let class = post_residual % 10;
    let class_penalty: f64 = match class {
        0 => -6.0,
        1 | 9 => 4.0,
        2 | 8 => 2.5,
        3 | 7 => 1.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: small residuals (<20) are near-dead space.
    if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 40 {
        score += 2.0;
    }

    // Reward tight fits strongly (post_residual small relative to item).
    if post_residual <= item_size / 4 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportionally to leftover after next.
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
        } else {
            // next item won't fit here: slight reward for keeping big residual.
            score -= (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // New-bin candidate handling: baseline high so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
    }

    // Progress-aware mild pressure to consolidate as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64) * (0.2 + 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits
    score -= (bin_residual as f64 - post_residual as f64) * 0.3;

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 6.0;

    // Progress-based scaling of dead-space penalty
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fill is excellent.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 60.0 + (slack_after_next as f64).min(50.0);
        if slack_after_next == 0 {
            score -= 150.0; // perfect two-item fill
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to mismatch.
        let gap = (next_item_size as f64) - (post_residual as f64);
        score += gap * 0.5;
    }

    // Compare against mean residual: bins with residual below mean are scarcer
    // (harder to reuse), so filling them is good; large-residual bins can wait.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.15;

    // Last-chance bonus: only one bin fits the item, use it rather than open new.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only prefer opening a new bin when the item is large
    // and would leave an awkward post residual in existing bins.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) > 30.0 && (post_residual as f64) < 60.0;
        if awkward {
            score -= 40.0;
        } else {
            score += 25.0; // default: prefer existing bins
        }
        // Early stream: opening bins is cheaper; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Penalize leaving dead space that is too small for typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: quadratic in post_residual, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / cap * (0.5 + progress);

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 6.0;
        } else {
            score += 4.0 + 0.05 * (next_item_size as f64);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize very tight residuals only slightly if item nearly fills bin (good fit reward).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Global state: many open bins with large mean residual -> prefer reusing fat bins.
    if open_bins_count > 2 && mean_residual > 25.0 {
        score -= 0.10 * mean_residual;
    }

    // New-bin candidate: strongly penalize unless current item is huge relative to capacity
    // and no good reuse exists (handled by fitting_bins_count==1 case above).
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    // Early stream (t small): favor tight fits strongly (low post residual)
    // Late stream (t large): dead space matters more, tighten further
    let poly = x * x * (1.0 - t) + x * x * x * t;
    score += poly * cap * (0.5 + 0.5 * t);

    // Reward near-perfect fits smoothly (small x) with a cubic dip
    score -= (1.0 - x) * (1.0 - x) * (1.0 - x) * 10.0;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Penalize opening a new bin when open bins exist and mean residual is large
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 20.0 * (1.0 - t) + mean_residual * 0.2 + open_f * 0.5;
        // If next item would fit in the new bin's residual, mild bonus for fresh bin late in stream
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 8.0 * t;
        }
    }

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularities are more reusable. Reward post_residual that is a multiple
    // of small class sizes (10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Dead space penalty: tiny unusable leftovers (1..=9) are nearly worthless
        if pr < 10 {
            score += 15.0;
        }
        // Integer-division thresholds: post_residual in a "medium" band is good
        let band = pr / 10; // 0..=9 harmonic class
        match band {
            0 => score += 10.0,          // 0..9: mostly dead space
            1 | 2 => score -= 4.0,       // 10..29: fits small items
            3 | 4 => score -= 6.0,       // 30..49: versatile
            5 | 6 => score -= 5.0,       // 50..69: fits half-size items
            _ => {}                      // large leftover: neutral
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: mild penalty proportional
            // to how "wasted" the harmonic class is
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the current bin's post-fit would be poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 10.0 * progress;
        // prefer new bin if current best fit would leave a bad residue class
        let item_mod = item_size % 10;
        if item_mod != 0 {
            score -= 5.0; // awkward item size, fresh bin may pair better later
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size && bin_residual != bin_capacity {
            score -= 8.0;
        }
        // empty bin leaves full flexibility for the next item
        if next_item_size > 0 {
            score -= 4.0;
        }
    }

    // Mean residual coupling: when open bins are already loose, discourage
    // spreading items thin; prefer tightening a tight bin.
    let residual_frac = bin_residual as f64 / cap;
    if residual_frac < mean_residual / cap {
        score -= 5.0; // tighter than average: good consolidation target
    } else {
        score += 3.0;
    }

    // Penalize creating very many open bins with large residuals
    if open_bins_count > 6 && post_residual > 40 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 6.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are small.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // New-bin candidate: mildly penalize opening new bins unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if this bin would leave a bad gap elsewhere, opening is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits this bin's post residual, reward the placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Perfect / near-perfit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if (nr - post_residual as f64).abs() < 0.5 {
            score -= 90.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            // next item fits, penalize leftover after chaining proportionally
            let chain_left = post_residual as f64 - nr;
            score -= 30.0 * (1.0 - chain_left / bin_capacity as f64);
        } else {
            // next item won't fit here: dead-space risk grows with small post_residual
            let gap = post_residual as f64 - nr;
            score += 10.0 + 0.3 * post_residual as f64 * (1.0 - fit_ratio);
        }
    } else if next_item_size == 0 {
        // last item: just minimize post_residual (already base).
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce-space bins;
    // using them for loose fits wastes them, using them for tight fits is great.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 8.0 * (mean_residual - res_f) / bin_capacity as f64 * fit_ratio;
    } else {
        score += 4.0 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists (post_residual of empty bin is large).
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; lookahead can rescue it if next item is huge.
        score += 15.0;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 25.0; // next item may be big, a fresh bin is valuable
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Many open bins: prefer filling existing ones over spreading.
    score += 0.5 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit bonus: strongly reward small waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 25 {
        score -= 3.0; // still usable for small items
    }

    // Lookahead: reward if the next item can fit into the post residual (chaining).
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving moderate residuals,
            // but a near-zero residual is fine (bin is "done").
            if post_residual > 0 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor filling the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage closing out bins (reduce fragmentation).
    if open_bins_count > 4 {
        let pressure = ((open_bins_count as f64 - 4.0) / (open_bins_count as f64 + 4.0)).min(1.0);
        score -= 5.0 * pressure * tightness;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // the item fits poorly in existing bins or mean residual is low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Base penalty so new bins are only chosen when open bins score badly.
        score += 10.0;
        // Large items leave little waste in a fresh bin: relax the penalty.
        score -= 10.0 * fit_quality * fit_quality;
        // If open bins are nearly full on average, a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Early in the stream, be slightly more willing to spread items
    // (keeps options open); late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= 4.0 * (1.0 - progress);
    } else {
        score -= 2.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post_residual, with non-linear polynomial coupling to progress.
    let mut score = pr;

    // Smooth polynomial in progress shaping residual penalty strength.
    let shape = 0.5 + 2.0 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 10.0 * pr_norm * pr_norm * shape * cap * 0.1;

    // Reward tight fits (small post_residual) with non-linear bonus.
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Penalize bins far from mean residual (fragmentation), smooth coupling.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * (0.3 + 0.7 * progress);

    // Mild penalty for many open bins to encourage consolidation early.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // New-bin candidate: keep it moderately unattractive unless residuals are poor.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
        if fitting_bins_count > 0 && mean_residual / cap > 0.25 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (modulo arithmetic) ----
    // Residuals divisible by large classes (e.g. %10 == 0) are "harmonic"
    // and more likely to be filled exactly by future items -> reward them.
    let harmonic_class = post_residual % 10;
    score -= match harmonic_class {
        0 => 8.0,              // perfectly harmonic residual
        5 => 3.0,              // half-class, still reusable
        2 | 4 | 6 | 8 => 1.0,  // even class
        _ => 0.0,              // odd class: dead-space risk
    };

    // Integer-division thresholds: residuals in [1..=9] are nearly dead space.
    if post_residual > 0 && post_residual / 10 == 0 {
        score += 12.0; // tiny unusable sliver -> strong penalty
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly into this bin's post residual: big reward.
            let exact = (post_residual == next_item_size) as f64;
            score -= 10.0 + 15.0 * exact;
        } else if next_item_size <= post_residual + 10 {
            // Near-miss: next item almost fits; mild penalty for stranding it.
            score += 2.0;
        }
        // Harmonic pairing: item + next item sums to a multiple of 10 within capacity
        if (item_size + next_item_size) % 10 == 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0;
        }
    }

    // ---- Last-chance bonus: only this bin can fit the item ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are bad
        // (high mean residual spread / fragmented fitting options).
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let late_stream = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bin by default; discount penalty when many open bins
        // with large mean residual exist (poor fits likely).
        let mut new_bin_penalty = 18.0
            - 0.05 * mean_residual
            - 2.0 * open_bins_count as f64
            - 6.0 * late_stream;
        if fragmentation < 5.0 {
            new_bin_penalty += 8.0; // open bins already near-empty; don't fragment more
        }
        // Large items (harmonic class 0 mod 10) start clean bins well.
        if item_size % 10 == 0 && item_size >= 50 {
            new_bin_penalty -= 6.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // ---- Mean-residual coupling: prefer bins below mean residual (tighter) ----
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.3 * residual_gap.max(0.0) - 0.1 * residual_gap.min(0.0);

    // ---- Mild progression term: late in stream, consolidate aggressively ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (post_residual % 25 == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving space that can fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize when lookahead item cannot fit the resulting gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins lightly,
    // but allow opening new bins when this is a last-chance bin with bad fit.
    score += open_bins_count as f64 * 0.5;

    if fitting_bins_count == 1 && post_residual <= 15 {
        score -= 15.0;
    }

    // Prefer tighter bins overall relative to the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose leftover exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * next_fit * next_fit; // next item fits well here too
        } else {
            // next item cannot fit -> penalize proportionally to wasted potential
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare against mean residual: prefer bins that reduce residual dispersion.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Penalize dead space that no plausible item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized so we only
    // open new bins when existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If the item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late in stream, prefer reusing open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Early stream: encourage opening bins to build a diverse residual portfolio.
    if step_index < total_items / 10 && open_bins_count < 3 && bin_residual < bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= (bin_capacity as f64 / (1.0 + tightness)) * 0.35;
    }

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in stream, be pickier (penalize loose fits);
    // late in stream, prioritize closing bins out
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.2;

    // Global state coupling: many open bins with high mean residual
    // -> favor bins below mean residual (consolidation)
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.1;
        // pressure to fill existing bins when many are open
        score -= (open_bins_count as f64).ln() * (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Brand-new bin candidate: only attractive when current item is large
    // and no open bin fits well
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.6 {
            score -= 20.0 * fill;
        } else {
            score += 15.0 * (1.0 - fill);
        }
    }

    // Mild preference for filling larger residuals when few bins open
    if open_bins_count <= 2 {
        score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial deepening over time
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear coupling: penalize residuals that are too small to be useful,
    // scaled by stream progress (dead space hurts more later)
    let dead = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * dead * (0.5 + progress);

    // Reward tight fits (post_residual near zero) with a smooth trough
    score -= 25.0 * (-norm_pr * norm_pr * 8.0).exp();

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0);
        let slack = ((pr - nx) / cap).abs();
        score += fits_next * 0.3 - 15.0 * (-slack * slack * 10.0).exp();
    }

    // Last-chance bonus: strongly favor using a scarce fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual
    let mean_norm = mean_residual / cap;
    score += 5.0 * (norm_pr - mean_norm).abs() * (open_bins_count as f64).ln().max(1.0) * (0.3 + 0.7 * progress);

    // New-bin candidate: neutral baseline with slight progress-dependent penalty
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable, penalize "odd" leftovers.
    let pr = post_residual;
    if pr > 0 {
        let mut class_bonus = 0.0;
        if pr % 50 == 0 { class_bonus += 12.0; }
        else if pr % 25 == 0 { class_bonus += 8.0; }
        else if pr % 20 == 0 { class_bonus += 6.0; }
        else if pr % 10 == 0 { class_bonus += 4.0; }
        if pr % 10 != 0 && pr < 10 { class_bonus -= 6.0; } // dead sliver
        score -= class_bonus;
    }

    // Perfect fit: extremely favorable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // wasted space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
        // Harmonic match: next item divides the post residual exactly
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating small unusable slivers (< 10, the min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity or many bins already exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_fit = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when item is big (would leave tiny residual anyway)
        // or late in the stream; otherwise keep packing into open bins.
        score += 30.0 - tight_fit * 60.0 + progress * 20.0;
        if fitting_bins_count > 0 && post_residual >= 30 {
            score += 25.0; // an open bin still has room; don't open a new one
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual >= 50 {
            score += 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance residuals).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Integer-division threshold on post_residual: quantize into bands.
    let band = post_residual / 10;
    score += band as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 9 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual <= 19 {
            score += 12.0;
        }
    }

    // Reward tight fits (small waste fraction).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins below mean residual (fuller bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item would fit exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use this gap: penalize if gap is small.
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // New-bin candidate: neutral baseline, slightly penalized so it's only
    // chosen when all open bins are genuinely bad fits (dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
