pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good, amplify it.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 20.0;

    // Penalize dead space: residuals too small for the smallest item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is high.
    score += open_bins_count as f64 * 0.5;
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    // New-bin candidate handling: only open a new bin when current bin fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // At stream start, allow more bins; late stream, discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If item is large relative to capacity and fits perfectly, a new bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0;
        }
        // If existing bins are fragmented (high mean residual spread), new bin less costly.
        if mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // Time horizon: early stream favors consolidation, late stream favors any fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1)

    // Smooth polynomial base: prefer small post_residual (tight fit)
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep-like: penalizes large leftover space

    // Non-linear coupling with stream progress: early on, tolerate loose fits;
    // later, demand tight fits more strongly.
    score += (1.0 - progress) * (x - 0.5) * (x - 0.5) * 8.0;
    score -= progress * (1.0 - x) * (1.0 - x) * 6.0;

    // Dead-space penalty: post residual too small to ever fit a plausible item
    let dead = ((12.0 - post).max(0.0)) / 12.0;
    score += dead * dead * 15.0;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly (smooth kernel)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let k = (-gap * gap / 18.0).exp();
        score -= k * 10.0 * (0.4 + 0.6 * progress);
        // penalize if post residual can't fit next item but is large
        if next_item_size as f64 > post {
            score += 3.0 * (1.0 - x);
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    } else {
        // mild penalty when many alternatives exist, encouraging consolidation
        score += (fitting_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Encourage balancing residuals toward the mean (smooth attraction)
    score += ((post - mean_residual) / cap).abs() * 2.0;

    // Mild penalty for proliferating bins early (favor filling existing bins)
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 1.2;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions create dead-space classes.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Penalize residuals in "unusable" classes: small leftovers (<10) are dead space
    // unless exactly 0 (perfect fit). Use modulo classes on post_residual.
    if post_residual == 0 {
        score -= 500.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 80.0; // tiny dead space, unusable for typical items
    } else {
        // Modulo-10 class: residuals that are multiples of 10 are more reusable
        let cls = post_residual % 10;
        score += cls as f64 * 1.5;
    }

    // Integer-division thresholds: reward residuals that can still host common sizes
    let halves = post_residual / 2; // integer division threshold
    if halves >= 40 {
        score -= 15.0; // roomy bin, still flexible
    } else if halves >= 20 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, scaled by how tightly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.2;
        } else {
            // next item won't fit here: this bin becomes dead after placement
            score += 30.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (new bin also returns ~post_residual == capacity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current fit is poor (large post_residual, no lookahead fit).
    if bin_residual == bin_capacity {
        // neutral base for new bin; slight penalty so existing bins with good
        // fits win, but bonus if open bins are nearly full on average.
        score = frac * 100.0;
        let pressure = mean_residual / cap; // average fullness slack
        if pressure < 0.15 {
            score -= 20.0; // open bins nearly full -> opening new bin is fine
        }
        if next_item_size > 0 && next_item_size > 90 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: early on, be more willing to open bins (exploration);
    // later, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (post_residual as f64 / cap);

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but dead space matters more
    // when it's too small to be usable by typical future items.
    if post_residual > 0 {
        // Unusable dead space zone: gaps below ~20 are hard to fill.
        if post_residual < 20 {
            score += 40.0 * (20.0 - post_residual as f64) / 20.0;
        }
        // Very tight fits (0..=5) are excellent; reward them.
        if post_residual <= 5 {
            score -= 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual can't host the next item: mild penalty scaled by how close it was.
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 8.0 * (1.0 - miss / 10.0);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += 2.0 * pressure;

    // Mean residual coupling: if mean residual is large, packing into existing bins
    // is cheap; if mean residual is small, opening a fresh bin is relatively attractive.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only good when current bins are crowded or the item
        // would leave a bad gap elsewhere.
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded || fitting_bins_count == 0 {
            score -= 35.0;
        } else {
            // Penalize new bins when decent fits exist (fresh bin wastes capacity potential).
            score += 20.0 + 0.3 * mean_residual;
        }
        // Slight early-stream tolerance for opening bins.
        if progress < 0.2 {
            score -= 10.0 * (1.0 - progress / 0.2);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item fits exactly-ish after this placement
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 200.0;
            }
        } else {
            // dead space relative to lookahead item
            score += 0.8 * (post_residual as f64 / next).min(3.0);
        }
    }

    // Penalize wasted space relative to mean residual
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Slight preference for tighter bins among many options
    score += 0.3 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = post_residual as f64 <= mean_residual.max(1.0);
        if good_fit_exists && open_bins_count > 0 {
            score += 300.0; // discourage new bin when decent fit exists
        }
        // late in stream, opening bins is cheaper
        score -= 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
