    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100 unknown, assume ~10 threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty for wasting capacity pairing
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_gap;

    // Time horizon: early in the stream, be more willing to open new bins (keep flexibility);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (40.0 - 60.0 * progress);

    // When many bins are open, discourage opening even more.
    score += new_bin * 2.0 * open_bins_count as f64;

    // Slight preference to place into bins below mean residual (balance / large residual preservation).
    if residual_gap < 0.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let coupling = x * x * (1.0 - progress) - x * progress * progress;
    score += 40.0 * coupling;
    // dead-space penalty: small post_residual is wasteful unless perfectly tight
    let tight = (x - 0.0).abs();
    score -= 12.0 * (1.0 - tight) * (1.0 - progress);
    // lookahead: reward leaving room for next item
    let nx = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let fit_next = (x - nx).abs();
        score += 8.0 * fit_next * (x - nx).signum() * (1.0 - progress);
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }
    // penalize spreading residuals far from mean
    score += (pr as f64 - mean_residual).abs() * 0.3 * progress;
    // new-bin candidate handling
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 residue classes.
    // Residues 1..=9 create "dead space" classes; residue 0 is harmonically clean.
    let post = post_residual;
    let residue = (post % 10) as f64;
    if post > 0 {
        score += residue * 0.8;
    }

    // Unusable dead space: post_residual below the minimum item size (1) is fine,
    // but post_residual in [1, 9] can never be filled by items >= 10 in classic
    // streams; treat as waste. For 1..100 streams, penalize tiny leftovers hard.
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Perfect fit is a harmonic zero: reward strongly.
    if post == 0 {
        score -= 40.0;
    }

    // Check whether the next item fits exactly into the post residual (chained fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0; // next item closes this bin perfectly
        } else if next_item_size < post {
            // reward leaving room for the lookahead, scaled by how well it couples
            let coupled = (post - next_item_size) % 10;
            score -= 10.0 - coupled as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += (next_item_size - post) as f64 * 0.15;
        }
    }

    // Integer-division thresholds on post_residual relative to capacity quarters.
    let quarter = (bin_capacity / 4) as f64;
    let post_f = post as f64;
    if post_f <= quarter {
        score += 12.0; // near-full bin leftover is likely dead space
    } else if post_f <= 2.0 * quarter {
        score += 4.0;
    } else {
        score -= 6.0; // roomy leftover is flexible
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: give it a neutral-to-slightly-high baseline so we only
    // open a new bin when existing fits are genuinely bad. Scale with stream
    // progress: late in the stream, prefer consolidating into open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 25.0 * progress + mean_residual * 0.1;
    }

    // Mild preference for bins whose residual is below mean (filling emptier
    // relative space keeps a spread of usable bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
