pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 20.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here afterward: big bonus, scaled by how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize leftover dead space
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (dead space < 10)
    if post_residual < 10 {
        score += 8.0;
    }

    // Slight preference for opening new bins early vs late in the stream
    // when the new-bin candidate would be perfectly empty
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new bin: neutral base, slight penalty so it only wins when fits are bad
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    // Discourage spreading across many open bins when residuals are large
    if open_bins_count > 2 && bin_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: non-linear bonus as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any future item (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 + 10.0 * chain_quality;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading, prefer consolidating into fuller bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (post_residual as f64 - mean_residual) * 0.5;

    // Time horizon: late in the stream, favor closing bins tightly (less future to plan for).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity_penalty = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += scarcity_penalty + 8.0 * pressure;
        // Early stream: opening bins is cheap; late stream: avoid fragmentation.
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), smoothly coupled with progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty for awkward dead space (mid-range residuals)
    let dead = norm_pr * (1.0 - norm_pr);
    score += 12.0 * dead * (0.5 + progress);

    // Reward using bins when few fitting bins exist (last-chance effect)
    if fitting_bins_count <= 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - nxt / cap) * (1.0 + progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference toward consolidating into existing bins vs new bin
    if bin_residual < bin_capacity {
        score -= 1.5 * (mean_residual / cap.max(1.0));
    } else {
        score += 4.0 * (1.0 - progress);
    }

    // Slight crowding penalty as many bins are open
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class by integer division into bands of 10 (item size quantum).
    let band = post_residual / 10;
    // Dead-space penalty grows superlinearly for small nonzero leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 60.0; // perfect packing
    }

    // Lookahead: can next item fit exactly in the post residual? (harmonic pairing)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 55.0; // next item fills bin exactly: strong reward
        } else if slack < 10 {
            score -= 25.0; // near-exact pairing
        } else {
            score -= (slack as f64).min(30.0) * 0.3;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover becomes dead weight
        score += post_residual as f64 * 0.15;
    }

    // Modulo harmonic class: residuals divisible by common item sizes (10,20,25,50)
    // are more likely to be exactly consumed later.
    let pr = post_residual;
    if pr % 10 == 0 { score -= 8.0; }
    if pr % 25 == 0 { score -= 5.0; }
    if pr % 50 == 0 { score -= 5.0; }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // opening a bin wastes capacity equal to (capacity - item_size) at minimum
        score += 10.0 + (bin_capacity - item_size) as f64 * 0.5;
        // late in stream, prefer closing out existing bins rather than opening
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // many open bins with large mean residual: discourage new bin
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
    } else {
        // prefer tighter fits among open bins: reward small bin_residual relative to item
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
        // crowded bins: mildly prefer filling bins that already hold a lot
        score -= (bin_capacity - bin_residual) as f64 * (open_bins_count as f64).ln().max(0.0) * 0.05;
    }

    // Progress-aware pressure: early on, keep flexibility (penalize very tight fits less later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual <= 20 {
        score += (1.0 - progress) * 10.0; // small leftovers cost more early (flexibility)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Nonlinear penalty for growing dead space beyond the minimum item size.
    if post_residual > 0 && post_residual < item_size as f64 * 0.5 {
        score += 25.0 + (10 - post_residual.min(10)) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open bins pressure: discourage spreading across many bins when few needed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late when open bins are fragmented.
        score += 20.0 + 30.0 * (1.0 - progress) - open_bins_count as f64 * 2.0;
        // If existing fits are very poor, opening a new bin is acceptable.
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to avoid opening a new bin.
        score -= 35.0;
    }

    // Prefer bins with residuals close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    // Mean residual coupling: if mean residual is high, favor using existing space.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Lookahead: if next item could use the post residual, reward leaving it.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight post_residual relative to mean residual.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or near-exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            // Reward proportional to how snugly the next item nests in the remainder.
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus if next item fills bin completely after placement.
            if slack <= 0.0 + f64::EPSILON {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit in this bin's remainder: penalize large dead space.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize post residual.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Early in the stream, tolerate spreading items across bins (more options later).
    score -= (1.0 - progress) * 1.5;

    // Penalize leaving residuals that are unusably small (dead space) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // Many open bins: prefer consolidation into fuller bins.
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residuals below the minimum item size are wasted forever.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0;
    } else {
        // Penalize small unusable-ish residuals more than proportional.
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.10 {
            score += (0.10 - frac) * 300.0;
        }
    }

    // Lookahead: reward bins whose post-residual can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5 + 5.0;
        } else {
            // This bin becomes dead after placement if residual can't fit anything.
            score += 10.0;
        }
        // If next item fits exactly in post-residual, strongly favor.
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (penalize new-bin alternative via capacity check).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: it's only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // But if current bin would leave large dead space, opening new bin
        // becomes more attractive: reduce the penalty.
        let waste = (bin_residual - item_size) as f64;
        if waste > 0.5 * bin_capacity as f64 {
            score -= 30.0;
        }
        // Few open bins and early stream: opening is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        if open_bins_count < 3 {
            score -= 15.0;
        }
    }

    // Global state coupling: if mean residual is high, prefer bins that
    // reduce dispersion (place into small-residual bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Prefer fuller bins overall (best-fit bias beyond raw post_residual).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr);

    // Penalize large dead space non-linearly (quartic in normalized residual)
    score += 8.0 * norm_pr * norm_pr * norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small, stronger as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack_fit) * (1.0 - slack_fit);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Mild preference for keeping bin count low; encourage filling existing bins early
    score += (open_bins_count as f64).ln() * 0.5;

    // Deviation from mean residual: prefer bins near the mean to balance residuals
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lies in
    // "usable" residue classes are rewarded; dead-space classes penalized.
    let dead_threshold = bin_capacity / 10; // 10
    if post_residual == 0 {
        score -= 60.0; // perfect closure is excellent
    } else if post_residual < dead_threshold {
        score += 25.0; // tiny unusable sliver -> dead space penalty
    } else {
        // residue class modulo 5: leftovers congruent to small multiples
        // pair well with common item sizes (multiples of 5 / 10)
        let r = post_residual % 5;
        score -= match r {
            0 => 12.0,
            1 => 2.0,
            2 => 0.0,
            3 => 4.0,
            _ => 6.0,
        } as f64;
        // integer-division tier of the residual: how many "half-items" fit
        let tiers = post_residual / (bin_capacity / 4);
        score -= tiers as f64 * 8.0;
    }

    // Pairing bonus: if the next item fits exactly into the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility: gcd-like affinity via modulo classes
            let compat = if post_residual % next_item_size == 0 {
                18.0
            } else if next_item_size % 5 == 0 && post_residual % 5 == 0 {
                10.0
            } else {
                4.0
            };
            score -= compat;
        } else {
            // next item won't fit here; penalize large leftovers that strand it
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when open bins are crowded (high mean fill => low mean residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 45.0; // default: prefer existing bins
        score -= progress * 20.0; // late in stream, fresh bins less costly
        if mean_residual < (bin_capacity as f64) * 0.2 && open_bins_count > 0 {
            score -= 35.0; // open bins are nearly full -> new bin is fine
        }
    }

    // Mild preference for tighter bins overall (below-average residual)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when the leftover can still host the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover too small for next item: mild penalty scaled by gap size.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another;
    // the empty-bin candidate (bin_residual == bin_capacity) gets penalized.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if item is large and fits poorly anywhere else, new bin may win.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate fuller bins).
    if bin_residual < bin_capacity {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    // Progression term: late in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else {
        // Nonlinear penalty on wasted residual (quadratic dead-space cost)
        score += (post_residual as f64).powi(2) * 0.01;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 0.5; // next item fits perfectly-ish
        } else {
            // next item won't fit here: penalize more if the gap is small (near miss)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Coupling with mean residual: prefer bins tighter than the mean
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is very full
    if bin_residual == bin_capacity {
        score += 250.0;
    }

    // Early in the stream, allow more liberal bin opening; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small waste relative to capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use, scaled by how dead it is
        score += (post_residual as f64).min(next_item_size as f64) * 0.6;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity && item_size <= bin_capacity {
        let crowded = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        let poor_fit = if post_residual as f64 > 0.0 { 1.0 } else { 0.0 };
        score += 20.0 - crowded * 60.0 + poor_fit * 0.0;
        // early stream: new bins are fine; late stream: prefer filling existing
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - t) * 10.0 - t * 15.0;
    }

    // Prefer bins whose residual deviates from mean in a "well-used" direction
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Mild global pressure: more open bins -> consolidate
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    // Early stream: prefer tight fills (low post_residual). Late stream: waste tolerable.
    let progress_weight = 1.0 + 0.6 * progress * progress;
    score += 12.0 * norm_pr * norm_pr * progress_weight;

    // Penalize post_residual that could still fit the next item (smooth quadratic in gap).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 2.0 * (-gap / cap) * (-gap / cap);
        }
    }

    // Last-chance bonus: only one bin fits, smooth sigmoid-like coupling with progress.
    let last_chance = (fitting_bins_count == 1) as i32 as f64;
    score -= 10.0 * last_chance * (1.0 / (1.0 + (-(6.0 * (progress - 0.5)).exp())));

    // Mild penalty when this bin's residual deviates from mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight preference for reusing open bins over opening new ones as stream grows.
    score -= 3.0 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover space: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // Integer-division dead-space classes: tiny leftovers are wasted space.
        let dead_class = pr / 10; // 0 => 1..9 dead, 1 => 10..19, etc.
        score += match dead_class {
            0 => 25.0,          // nearly unusable sliver
            1 => 8.0,
            2 => 0.0,
            3 => -4.0,
            _ => -6.0,          // large leftovers still useful
        };
    }

    // Lookahead coupling: does the leftover pair well with the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly-ish into this bin's leftover
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 30.0; // chain of perfect fits
            } else if slack < 10 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize big leftovers only mildly,
            // but penalize small leftovers harder (they become dead).
            let gap = next_item_size - pr;
            score += (gap as f64).min(40.0) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // the current item is large relative to capacity and mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        let mean_frac = mean_residual / cap;
        // Penalize opening new bins when existing space could absorb items.
        score += 20.0 + mean_frac * 40.0 - item_frac * 25.0 - progress * 5.0;
        // Large items deserve fresh bins more often.
        if item_size >= 60 { score -= 15.0; }
        if item_size <= 20 { score += 15.0; }
    }

    // Prefer tighter bins overall: closeness of fill to capacity.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * 10.0;

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (< 10) are unusable dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward using a bin whose residual is only slightly larger than the item.
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score -= (1.0 - slack / bin_capacity as f64) * 10.0;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the resulting gap is dead space.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual - next_item_size < 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: penalize unless it is dead space anyway.
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow opening new bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);

    // New-bin candidate: attractive when mean residual across open bins is low
    // (open bins are fragmented) or item is large; unattractive early on.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        score += 15.0 * progress;
        if item_size >= 60 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 50.0; // never open a new bin just to make dead space
        }
    }

    // Prefer bins whose current residual is close to the item (tight packing).
    score += ((bin_residual as i64 - item_size as i64).abs() as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (minimal dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chain match
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 40.0).min(2.0);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 5.0;
    }

    // Penalize bins that deviate favorably from mean residual (waste concentration).
    let cap = bin_capacity as f64;
    let residual_norm = bin_residual as f64 / cap;
    let mean_norm = mean_residual / cap;
    score += 6.0 * (residual_norm - mean_norm).abs().sqrt();

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or stream is late (waste is locked in).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can chain the next item
        }
    }

    // Mild preference for fuller bins early on.
    score -= 4.0 * (1.0 - residual_norm) * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin used by this placement.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (item_size as f64 / bin_residual as f64);
    }

    // New-bin candidate handling: empty bin should only win when the item is large
    // or fits of existing bins are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0
            - 30.0 * fit_ratio
            - 15.0 * (1.0 - progress)
            + 2.0 * open_bins_count as f64;
        // If many bins can fit the item, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 20.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
    }

    // Prefer bins with below-mean residual (concentrate filling).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Mild time-horizon scaling: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, smoothly warped.
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes progressively more costly.
    let progress_coupling = pr_norm * (1.0 - pr_norm) * progress * (1.0 - progress);
    score += 40.0 * progress_coupling - 12.0 * pr_norm * progress;

    // Penalize large residuals relative to mean residual (fragmentation signal).
    score += 0.5 * (mean_residual - pr).abs() * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (1.0 + progress);
        // Penalize wasting almost all space when next item nearly fits.
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap * gap / cap;
    }

    // Mild penalty for bin proliferation when many bins are open.
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // Slight preference for tighter bins overall.
    score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // (divisible by small item sizes 10..20), penalize awkward ones.
    let pr = post_residual;
    if pr > 0 {
        let mut friendliness = 0.0f64;
        for d in 10..=20 {
            if pr % d == 0 {
                friendliness += 1.0;
            }
        }
        score -= 4.0 * friendliness;

        // Integer-division threshold bands on post_residual
        let band = pr / 10; // 0..10
        match band {
            0 => score += 15.0,          // tiny dead space, unusable
            1 => score += 5.0,           // marginal
            2 | 3 => score -= 6.0,       // sweet spot: fits mid items
            4 | 5 => score -= 3.0,
            _ => {}                      // large residual: near-neutral
        }
    } else {
        score -= 25.0; // perfect fill is best
    }

    // Lookahead coupling: does next item fit the post_residual exactly or well?
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 20.0; // chains a perfect follow-up
            } else if slack <= 10 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here; penalize large leftover that becomes dead
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early stream: be a bit pickier (more bins later available to consolidate);
    // late stream: just fill anything reasonable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: neutral baseline; only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 60.0 + 10.0 * (1.0 - progress) - (open_bins_count as f64).min(20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10] is nearly unusable
    // (min item size is 10 in the classic regime). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits generally: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin should only win when the item fits
    // badly everywhere else. Make the empty bin attractive only for large items
    // or when it creates a good future landing spot.
    if bin_residual == bin_capacity {
        // Base penalty for proliferating bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Large items justify a fresh bin.
        score -= 20.0 * fill_ratio;
        // Lookahead: if next item would leave the fresh bin with a nice residual,
        // boost the new bin slightly.
        if next_item_size > 0 {
            let next_gap = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).unsigned_abs() as f64;
            score -= 15.0 / (1.0 + next_gap);
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual is close to item_size (waste-minimizing match).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 30.0 * tightness;
        // Prefer bins with larger residuals among equally tight options (keep
        // small-residual bins for small items).
        score -= 5.0 * (bin_residual as f64 / bin_capacity as f64);
        // Open-bin pressure: many open bins -> favor consolidation into existing bins.
        score -= 1.5 * open_bins_count as f64;
        // If next item fits the post-residual exactly, big bonus (chained fit).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can still host the next item (good chaining)
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / post_residual as f64);
    } else {
        // Dead space: post_residual too small for next item
        score += 15.0;
    }

    // Reward tight fits relative to current item
    score -= 20.0 * (item_size as f64 / bin_residual as f64);

    // Compare residual to mean residual: prefer filling below-average-residual bins
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 30.0 + 5.0 * fitting_bins_count as f64;
        } else {
            score -= 10.0;
        }
        // Early stream: opening bins is cheaper
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.3 {
            score -= 15.0;
        }
    }

    // Late stream: consolidate aggressively
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, non-linear bonus.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later (below min item size 1... use 10 as practical floor).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // If next item would be blocked by a bad post_residual, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins,
    // and discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= (mean_residual / bin_capacity as f64) * 10.0 * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: only attractive when open bins are crowded / residuals low.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let crowding = (open_bins_count as f64 / (1.0 + fitting_bins_count as f64)).min(3.0);
        let time_pressure = 0.5 + 0.5 * progress;
        score += 20.0 - 35.0 * avg_fullness * time_pressure - 8.0 * crowding;
        // Late in stream, opening new bins is worse (waste).
        score += 15.0 * progress;
    }

    // Mild preference for bins whose residual is close to item size (perfect packing).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    let poly = x * x * (1.0 - progress) + x * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= 15.0 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Penalize dead space relative to mean residual
    score += 0.5 * (pr as f64 - mean_residual).abs();

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 10.0 * (1.0 - (pr as f64 - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr as f64) / cap;
        }
    }

    // New-bin candidate: penalize opening new bins early, allow late
    if bin_residual == bin_capacity {
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Class A: post_residual divisible by 10 -> highly reusable
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // Class B: divisible by 5 but not 10 -> moderately reusable
        else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Class C: small dead space (< 10) -> nearly unusable, penalize hard
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 30.0;
    }

    // Harmonic compatibility: if the lookahead item divides the post_residual
    // exactly, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size <= pr {
            if pr % next_item_size == 0 {
                score -= 12.0;
            } else if pr - next_item_size < 10 {
                // next item would create dead space here; mild penalty
                score += 3.0;
            }
        } else {
            // next item cannot use this residual anyway; neutral
            score += 0.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Prefer keeping it pristine unless existing bins have poor fits.
    if bin_residual == bin_capacity {
        // Neutralize the base residual so new bins compete fairly,
        // then apply a mild reluctance that grows with available fits.
        score = (bin_capacity - item_size) as f64 * 0.9 + 10.0
            + (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing large items together in fresh bins is fine
            score -= 5.0;
        }
    }

    // Stream progression: early on, be more selective (penalize loose fits);
    // late in the stream, prefer packing into existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    // Spread-aware term: placing into a bin far below the mean residual
    // balances the pool of open bins.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Favor bins whose residual was already fragmented (high mean residual gap).
    if (bin_residual as f64) > mean_residual + 15.0 {
        score -= 8.0; // prefer using unusually full-capacity-remaining bins
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score += 8.0; // avoid draining already-tight bins unless fit is perfect
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 35.0;
    }
    // Penalize leaving a gap just below next item size (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open bins pressure: many open bins -> discourage opening new ones implicitly
    // by rewarding reuse; also makes this bin more attractive vs new bin.
    score -= (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // current item is large relative to capacity or many bins already open.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * load_frac; // large items start fresh bins more readily
        score += 5.0;              // default mild penalty so reuse is preferred
    }

    // Late in stream: consolidate, avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64).recip().min(4.0) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual < 20 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 200.0;
        } else if post_residual < next_item_size {
            // leftover can't fit next item -> dead space unless small
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // next item would leave an exact fit after this placement
        let after_next = post_residual.saturating_sub(next_item_size);
        if after_next > 0 && after_next <= 10 {
            score -= 50.0;
        }
    }

    // Penalize creating unusable dead space relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small residual is fine, nearly full
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize leaving large residuals when many bins are open (fragmentation)
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.3;
    }

    // New-bin candidate: only attractive when current bins are fragmented
    // or this bin is empty and item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size > 60;
        if large_item && next_item_size > 40 {
            score -= 80.0; // pair two large items fresh
        } else if mean_residual < 15.0 && open_bins_count > 0 {
            score += 120.0; // existing bins are nearly full, opening is fine
        } else {
            score += 60.0 + progress * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize tiny post-residuals only lightly (tight fit is good),
    // but heavily penalize "almost fits" dead space in mid range.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 6.0; // awkward sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty, worse early when many items remain.
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 10.0 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= fullness * (2.0 + 0.15 * open_bins_count as f64);

    // Compare against mean residual: bins far below mean residual are worse choices
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when no open bin fits well
        // (many fitting bins exist) or stream is nearly done.
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).ln() + 1.0
        } else {
            0.0
        };
        // Base cost of a fresh bin, discounted late in the stream.
        score += 14.0 - 6.0 * progress + pressure;
        // Never open a new bin when the item would leave zero residual elsewhere
        // handled by other arms; also discourage new bin if item is small relative to capacity.
        score += 6.0 * (1.0 - item_size as f64 / cap);
    }

    // Small noise-free tiebreaker: prefer bins with slightly more residual used.
    score += 0.01 * (bin_residual as f64 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (prefer tight fits)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mildly tolerate larger residuals; late stream: strongly penalize them.
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 20.0 * poly;

    // Reward near-perfect fits more aggressively as stream advances.
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize creating dead space that next item cannot use (smooth interaction).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 10.0 * gap * gap * (1.0 + progress);
        // Reward if next item fits exactly in post residual
        let fits_next = (next_item_size as f64 <= pr) as f64;
        score -= 8.0 * fits_next * (norm_pr.min(0.5)) * (1.0 + progress);
    }

    // Last-chance bin: strong reward to use it instead of opening new bins.
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    let frag = norm_pr * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    score += 6.0 * frag * (0.3 + 0.7 * progress);

    // Pull toward mean residual: prefer bins whose residual is typical (smooth).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline; only chosen if open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * norm_pr;
        if next_item_size > 0 && next_item_size as f64 <= 0.5 * cap {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" the leftover falls into.
    // Residuals in [0,10) are near-perfect; [10,20) good; large residuals wasteful.
    let pr = post_residual;
    let class = pr / 10; // integer division: 0..=10
    let class_penalty: f64 = match class {
        0 => -6.0,
        1 => -2.0,
        2 => 0.0,
        3 => 2.0,
        4 => 4.0,
        5 => 6.0,
        6 => 8.0,
        7 => 10.0,
        8 => 12.0,
        9 => 14.0,
        _ => 16.0,
    };
    score += class_penalty;

    // Modulo coupling: residuals that are multiples of small harmonics (5, 10, 20)
    // are more reusable by typical item sizes; reward them.
    if pr % 5 == 0 { score -= 2.0; }
    if pr % 10 == 0 && pr > 0 { score -= 2.0; }
    if pr % 20 == 0 && pr > 0 { score -= 1.5; }

    // Dead space: leftover smaller than the minimum conceivable next chunk (<=10)
    // is nearly unusable — heavy penalty.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Exact fit is ideal.
    if pr == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after both
            let pr2 = pr - next_item_size;
            score -= 3.0 + (pr2 as f64).min(10.0) * 0.3;
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += ((next_item_size - pr) as f64).min(40.0) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item is
    // large or fits are scarce; otherwise penalize spreading across bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a new bin
        score += 18.0;
        // large items benefit from a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 12.0 + (item_size as f64 - cap * 0.5) * 0.2;
        }
        // few fitting bins or late in stream: new bin more acceptable
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
        // early stream: fresh bins fine; late stream: prefer consolidation
        score += progress * 6.0;
        // if mean residual across open bins is high, opening new bins wastes space
        score += (mean_residual / cap).clamp(0.0, 1.0) * 10.0;
    }

    // Prefer bins that are already somewhat filled (tighter packing).
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10) are unusable for future items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit reward
        score -= 40.0;
    } else {
        // Mild reward for small-but-usable residual, decaying with size
        score -= (10.0 - (post_residual as f64 - 10.0) / cap) * 3.0;
    }

    // Penalize leaving residual that just barely fails to fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx && (bin_residual as f64) >= nx {
            score += 25.0; // blocks the lookahead item
        } else if (post_residual as f64) >= nx {
            score -= 12.0; // can chain the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (post_residual as f64 / cap);

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 18.0 + pressure };
        score += desperation;
        // A fresh bin is more attractive late in the stream when residuals are fragmented
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward tighter leftover after the pair
            let pair_residual = post_residual - next_item_size;
            score -= 25.0 - 0.3 * pair_residual as f64;
        } else {
            // next item cannot use this bin's remainder: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(50.0);
        }
    } else {
        // last item: only post residual matters
        score -= 5.0;
    }

    // Prefer bins tighter than average residual (compact packing)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Penalize large unusable post residual (dead space nobody fits)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin bonus: if only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Early in stream: slight preference to consolidate into fewer bins
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    // New-bin candidate: neutral base, penalize slightly so we prefer good fits
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0; // sliver waste
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Crowding: when many bins are open, prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.35 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be picky about fits; late, just fill bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual context: if this bin's residual is far above mean, it's a good filler target.
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= 0.05 * residual_gap;

    // New-bin candidate: make empty bin moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > (bin_capacity as f64 * 0.55)
            || (next_item_size > 0 && next_item_size > post_residual && next_item_size > 50);
        if bad_fit {
            score -= 12.0;
        } else {
            score += 10.0; // discourage wasteful new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, waste is cheap; later, compactness matters more.
    let coupling = 1.0 + 1.5 * progress * progress + 0.5 * progress;
    score *= coupling;

    // Perfect-fit reward (smooth, via normalized residual)
    score -= 30.0 * (1.0 - norm_pr).powi(6);

    // Lookahead: reward bins whose post-residual accommodates the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 8.0 * (1.0 - (diff / cap)).powi(2);
        } else {
            score += 4.0 * (-diff / cap);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mild penalty for spreading across many bins when residuals are large
    score += 0.05 * open_bins_count as f64 * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: penalize opening a bin unless current bin fits poorly
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space buckets (mod arithmetic).
    let pr = post_residual;
    let class = pr / 10; // integer division thresholds: 0..10
    match class {
        0 => { score -= 60.0; }            // near-perfect fit
        1 => { score -= 35.0; }            // excellent
        2 => { score -= 18.0; }            // good
        3 => { score -= 8.0; }             // fair
        4 => { score += 4.0; }             // mediocre
        5 => { score += 12.0; }            // half-empty bin
        6 => { score += 20.0; }
        7 => { score += 28.0; }
        8 => { score += 36.0; }
        9 => { score += 44.0; }
        _ => { score += 52.0; }            // nearly untouched bin
    }

    // Fine-grained harmonic bonus: post_residual divisible by common item sizes
    if pr > 0 {
        if pr % 10 == 0 { score -= 10.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
    } else {
        score -= 70.0; // exact fill
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0 + (pr - next_item_size) as f64 * 0.15;
            // harmonic chain: next item leaves a small remainder too
            let npr = pr - next_item_size;
            if npr <= 10 { score -= 15.0; }
        } else {
            // next item won't fit here: penalize bins that strand the lookahead
            score += 8.0;
        }
    } else {
        // last item: just fill as tightly as possible
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item wastes less relative to others
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: reserve it unless current placement is terrible.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; opened only if all open bins score worse
        score = 55.0 + mean_residual * 0.05;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Progress pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for filling emptier bins when many bins are open
    score -= (bin_residual as f64 - post_residual as f64) * 0.05 * (open_bins_count as f64).min(20.0) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

