    // Open-bin pressure: many open bins -> prefer packing into existing ones.
    score -= open_bins_count as f64 * 2.5;

    // Compare against mean residual: bins with less residual than average are tighter fits.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when the item is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 60 && open_bins_count > 2 && mean_residual < item_size as f64 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Mild early-stream conservatism: keep bins flexible early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

