            }
        } else {
            // next item cannot follow: penalize dead space relative to next size
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Early in stream: prefer opening new bins less aggressively (keep bins consolidated)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: penalize slightly unless item is large or few bins fit
        let mut new_bin_penalty = 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        if item_size > 70 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear boost.
    if post_residual > 0 {
        score -= 30.0 / (post_residual as f64).powf(0.8);
    } else {
        score -= 60.0; // perfect fit is highly desirable
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
