            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins
    // (favor tight fits more); late in the stream, just minimize bin count now.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 / (1.0 + post_residual as f64 / 20.0);

    // Global state: many open bins with high mean residual -> prefer reusing bins
    // with residual close to mean (avoid spreading fragmentation).
    if open_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 8.0 * (1.0 - dev / (mean_residual + 1.0));
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // item fits poorly everywhere else. Make empty-bin score moderately high.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if next item is large, a fresh bin is attractive for pairing.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
        // Few open bins early on: new bin is cheap.
        if open_bins_count <= 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: post residual, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let x = pr / cap;
    let p = progress;
    // Wasted space matters more as stream progresses (bins become scarce)
    let waste_penalty = x * x * (1.0 + 3.0 * p) + x * x * x * (2.0 * p + 0.5);
    score += waste_penalty;

    // Tight fits are desirable: reward small post_residual non-linearly
    let tightness = 1.0 - x;
    score -= 0.6 * tightness * tightness * (0.5 + p);

    // Dead space: residuals too small for typical items are penalized quadratically
    let dead_threshold = 0.15;
    if x < dead_threshold {
        let d = dead_threshold - x;
        score += 2.5 * d * d;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2 + 0.8 * p;
    }

    // New-bin candidate: prefer it when current bins fit poorly (post_residual large)
    if bin_residual == bin_capacity {
        // Neutral base for new bin; penalize opening when tight fits exist
        score += 0.35 + 0.25 * (1.0 - p);
        if next_item_size > 0.0 as u32 && (next_item_size as f64) <= pr {
            score -= 0.3; // new bin can also host lookahead item
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if nxt <= pr {
            score -= 0.5 * (1.0 - diff / cap) * (1.0 - diff / cap);
        } else {
            score += 0.2 * (nxt - pr) / cap;
        }
    }

    // Mean residual deviation: prefer bins whose post residual stays near mean
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev;

    // Many open bins: mild pressure to consolidate (fill existing bins)
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes mod 25.
    // Small leftovers (0..=5) are near-perfect fits -> strong reward.
    let cls = post_residual % 25;
    match cls {
        0 => score -= 40.0,                     // exact-ish fit
        1..=5 => score -= 30.0 - (cls as f64) * 3.0,
        6..=15 => score += 5.0,                 // awkward dead zone
        _ => {}                                 // 16..24, still usable
    }

    // Perfect fit: zero waste is the ideal outcome.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with lookahead: if next item can exactly fill the new residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 35.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // residual too small for the next item: dead space penalty scaled by size
            score += (post_residual as f64) * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a fresh bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // current item is large relative to capacity or all open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 8.0;
        score += 70.0 - 0.35 * (item_size as f64) - 10.0 * crowding - 15.0 * progress;
        // If next item is huge, reserving a fresh bin is fine.
        if next_item_size >= 70 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // packing into below-average-residual bins consolidates waste.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild late-stream tightening: waste less as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
