pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: penalize wasted space nonlinearly (dead space grows quadratically in cost).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste * (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the next item also fits snugly (small leftover after chain).
        let chain_left = post_residual - next_item_size;
        score -= 8.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a gap too small for the next item (unusable dead space).
        if post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer tighter packing to consolidate (relative to mean residual).
    if open_bins_count > 2 {
        let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * tightness; // bins below-mean residual (fuller) get lower score
    }

    // Time horizon: early in the stream, allow opening new bins more freely;
    // late in the stream, strongly prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    // New-bin candidate: only attractive when it enables a near-perfect split for
    // the current+next pair, or when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let pair = item_size + next_item_size;
        if next_item_size > 0 && pair <= bin_capacity && (bin_capacity - pair) <= 10 {
            score -= 40.0; // fresh bin fits both items almost perfectly
        } else {
            score += 15.0; // default: discourage opening new bins
            if fitting_bins_count > 0 {
                score += 10.0 * (fitting_bins_count as f64).ln();
            }
        }
    }

    // Snug-fit bonus: reward minimal leftover overall.
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - norm_pr);
    score -= 25.0 * coupling * (0.5 + progress);
    score += 15.0 * norm_pr * norm_pr * norm_pr * progress;

    // Penalize tight fits that leave dead space when a larger item may follow
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr).min(60.0) * (0.3 + 0.5 * progress);
        } else {
            // reward bins that also fit the lookahead item
            score -= 10.0 * (1.0 - (nxt / pr.max(1.0))) * (1.0 - progress);
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Slight penalty when bin residual deviates from mean residual (balance pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize mildly early, more late (prefer filling existing bins)
    if bin_residual == bin_capacity {
        score += 12.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes model "dead space quality".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space classes (1..=9) are hard to fill; penalize by class.
    let class = post_residual % 10;
    if post_residual > 0 && class > 0 && class < 10 {
        score += (10 - class) as f64 * 2.0;
    }

    // Reward residuals that are multiples of 25 (quarter-capacity harmonic).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportional to how well the next item fills the remaining space.
        let fill = next_item_size as f64 / pr;
        score -= 30.0 * fill;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Dead space that next item cannot use.
        score += 10.0 + pr * 0.1;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + mean_residual * 0.5;
    }

    // Prefer tighter bins overall.
    score += (mean_residual - pr).max(0.0) * 0.3;

    // Late-stream bias: consolidate into fewer bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1 unit) but awkwardly small relative to typical item sizes are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // only fits the tiniest items
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // every existing bin; only attractive when this bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // Lookahead: if the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size > item_size {
            score -= (next_item_size - item_size) as f64 * 0.5;
        }
        // Late in the stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Open-bin pressure: with many open bins, prefer tight packing of existing ones.
    score += open_bins_count as f64 * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead synergy: if the next item fits exactly in post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 50.0;
        }
        // penalize leaving dead space the next item cannot use
        if post_residual > 0 && post_residual < next_item_size {
            score += 30.0;
        }
    }

    // Penalize small unusable dead space relative to the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count <= 1 {
            score -= 250.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space nonlinearly — small leftovers are the worst.
        let pr = post_residual as f64;
        score += 40.0 / pr.sqrt();
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + 0.3 * nxt;
        } else {
            // Next item cannot fit here: penalize bins that leave awkward gaps.
            score += 0.2 * (nxt - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a fresh bin is discouraged unless
    // the current bin's residual would be very small and unusable.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin: high, but softened late in the stream
        // or when open bins are mostly full (mean residual low).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        score = bin_capacity as f64 * (1.0 + 0.6 * (1.0 - pressure)) - 40.0 * progress;
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= 0.4 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    }

    // Prefer filling bins with below-average residual (balance toward fullness).
    if bin_residual != bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Slight preference for bins among many open bins (consolidate).
    score += 0.05 * open_bins_count as f64;

    // Time horizon: early on, be conservative about tight fits that strand space;
    // later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        - 40.0 * norm_pr * (1.0 - norm_pr)          // reward medium residuals (good fits)
        + 25.0 * norm_pr * norm_pr * progress;       // penalize large residuals later in stream

    // Smooth progress coupling: dead space matters more as stream advances
    score += 30.0 * norm_pr * norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0);

    // Lookahead: reward residual that fits next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr >= nx) as i32 as f64;
        let tight = ((nx - pr).abs()) / cap;
        score -= 18.0 * fit_next * (1.0 - tight).max(0.0);
        score += 10.0 * (1.0 - fit_next) * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mean residual divergence penalty (smooth)
    score += 8.0 * ((pr - mean_residual) / cap).abs();

    // Slight new-bin preference when many bins and tiny residual waste elsewhere
    if bin_residual == bin_capacity {
        score += 5.0 * norm_pr * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity-fraction classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual % 25) as f64;
    let eighth = (post_residual % 12) as f64;

    // Penalize residuals that fall into awkward classes (not multiples of 25/50)
    if post_residual % 50 == 0 {
        score -= 6.0; // perfectly divisible residual, easy to fill later
    } else if post_residual % 25 == 0 {
        score -= 3.0;
    } else if post_residual % 10 == 0 {
        score -= 1.0;
    } else {
        score += quarter * 0.15; // awkward dead space penalty
    }

    // Small residual granularity: eighth-class refinement
    score += eighth * 0.05;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward if next item leaves another clean class residual
        let next_post = post_residual - next_item_size;
        if next_post % 25 == 0 { score -= 5.0; }
        if next_post % 10 == 0 { score -= 2.0; }
        score -= (next_item_size as f64) * 0.1;
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving large unusable gap
        score += (pr / cap) * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Brand-new bin candidate: only attractive when existing residuals are poor
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins mildly; worse late in stream or when many bins open
        score += 15.0 + openness * 0.5 + progress * 5.0;
        // but if mean residual is small (all bins nearly full), new bin is fine
        score -= mean_residual * 0.15;
        // large items prefer fresh bins
        score -= (item_size as f64) * 0.12;
    }

    // Prefer tight fits generally
    score -= (1.0 - pr / cap) * 4.0;

    // Discard tiny useless residuals entirely (dead space under 10 is near-worthless)
    if post_residual < 10 && post_residual > 0 {
        score -= 3.0; // finishing a bin cleanly is good
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gap (smaller than next item, or too small
    // for the minimum plausible item) is heavily penalized.
    let min_item = 1u32;
    let gap_unusable = post_residual > 0 && post_residual < next_item_size.max(min_item);
    if gap_unusable {
        score += 40.0 + (next_item_size - post_residual) as f64;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits relative to item size.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * tightness;
    }

    // Lookahead: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Usable residual for the next item: mild reward proportional to slack.
        score -= 8.0;
    }

    // Last chance bin before opening a new bin: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    // or this bin would be a poor fit anyway.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Open bins pressure: many open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64;

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post residual: strong lookahead reward,
    // scaled by how snugly it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space creation.
        let dead = (post_residual as f64).min(next_item_size as f64);
        score += dead * 0.3;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && bin_capacity >= next_item_size {
            // A fresh bin guarantees a perfect fit for the next item.
            score -= 10.0;
        }
    }

    // Slight preference for snug fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves waste; mild reward proportional to how well it nests.
            let nest = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - nest / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize slightly, scaled by how badly it misses.
            score += 8.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * open_pressure * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mean residual coupling: prefer bins whose residual is below mean (fill emptier-of-space bins),
    // penalize dumping into already-tight bins when mean is high.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Time horizon: early in the stream, be more selective (penalize mediocre fits);
    // late in the stream, just pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    // New-bin candidate handling: an empty bin has zero tightness reward; add a mild
    // opening cost that shrinks as the stream progresses (cheaper to open later is wrong,
    // so instead: opening is penalized early, and increasingly penalized when many bins open).
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score += 12.0 + 4.0 * open_pressure - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic tightening early on
    let mut score = pr * (1.0 + 0.8 * (1.0 - progress) * norm_pr);

    // Smooth non-linear coupling: dead-space penalty grows with stream progress
    let dead = norm_pr * norm_pr;
    score += 25.0 * dead * (0.3 + progress);

    // Reward tight fits (post_residual near zero) via smooth saturating term
    score -= 20.0 * (-pr / 12.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - progress);
    }

    // Lookahead coupling: bonus if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        let gap = (pr - next_item_size as f64).abs();
        if fits_next {
            score -= 10.0 * (-gap / 20.0).exp();
        } else {
            score += 5.0 * (1.0 - (-gap / 30.0).exp());
        }
    }

    // Mild penalty for spreading across many open bins vs. mean residual alignment
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - (mean_residual - pr).abs() / cap).max(0.0);

    // New-bin candidate: keep it competitive only when open bins are fragmented
    if bin_residual == bin_capacity {
        score = pr - 12.0 * progress + 8.0 * (open_bins_count as f64 / (1.0 + fitting_bins_count as f64)).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residue classes modulo 10
    let pr = post_residual;
    let class = pr % 10;
    // Dead space penalty: residuals < 10 (smallest item) are unusable
    if pr > 0 && pr < 10 {
        score += 500.0;
    }
    // Residues that pair well with common sizes (multiples of 5/10) are valuable
    match class {
        0 => score -= 30.0,
        5 => score -= 15.0,
        2 | 8 => score += 8.0,
        4 | 6 => score += 4.0,
        _ => score += 10.0,
    }

    // Lookahead coupling: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            // quotient/remainder harmonic split of post_residual by next item
            let q = pr / next_item_size.max(1);
            let r = pr % next_item_size.max(1);
            score -= 20.0 * q as f64;
            score += 2.0 * r as f64;
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is tight
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 40.0; // fresh bin pairs well with next big item
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late-stream consolidation: favor filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item (or the lookahead item) are toxic.
    let min_item = 1u32;
    let dead_threshold = next_item_size.max(min_item);
    if post_residual < dead_threshold && post_residual > 0 {
        // Unusable gap: penalize proportionally to how much capacity is wasted.
        score += (dead_threshold - post_residual) as f64 * 2.0;
        // Extra harsh penalty for very tiny slivers (1..=5 units).
        if post_residual <= 5 {
            score += 25.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement strands the next item: penalize.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 20 {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins (penalize new-bin candidate implicitly via residual, add mild pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean, it's a laggard bin — prefer filling it.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.15;
    }

    // New-bin candidate guard: empty bin should only win when the item is huge relative to capacity or fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    score = post_residual as f64 / bin_capacity as f64 * 100.0;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses the leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * usage;
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 15.0;
        }
    }

    // Compare against mean residual: bins with residual far from mean
    // that still fit are good consolidation targets.
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= 0.5 * (res_f - mean_residual).min(50.0);
    } else {
        score += 0.5 * (mean_residual - res_f).min(50.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or current bins are too full/fragmented.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let avg_tightness = mean_residual / bin_capacity as f64;
        // open new bin if it would leave a large reusable residual vs fragmented bins
        score = 100.0 - 40.0 * tightness - 20.0 * (1.0 - avg_tightness);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can chain next item too
        }
        if fitting_bins_count <= 1 {
            score += 20.0; // don't abandon last-chance bins
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale wasted space quadratically.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 40.0;

    // Penalize dead space relative to smallest plausible follow-up item.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += (dead / 100.0).powf(2.5) * 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: penalize placements that leave residual too small for next item
    // (unless next item fits exactly, which is great).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            // next item still fits here: reward leaving room for it
            let slack = post_residual as f64 - n;
            score -= 10.0 * (1.0 - slack / 100.0);
        } else {
            // next item won't fit here: mild penalty proportional to how much
            // we "almost" fit it (blocking a good chain)
            let gap = n - post_residual as f64;
            score += 8.0 * (1.0 - gap / 100.0);
        }
    }

    // New-bin candidate handling: only open a new bin when existing bins are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its residual equals capacity, so
        // post_residual is large; add a fixed opening penalty.
        score += 45.0;
        // Early in stream or many items remaining: slightly cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If few bins fit the item, opening is more acceptable.
        score -= 5.0 * (fitting_bins_count.min(4) as f64).recip();
    } else {
        // Prefer bins whose residual is below the mean (consolidate emptier space? no —
        // fill tighter bins first to keep large residuals available).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);

    let mut score = pr;

    // Penalize large residuals early (keep bins flexible), reward tight fits later
    score += 30.0 * poly;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize slightly unless post fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }

    // Mean residual divergence penalty
    score += 0.5 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as fraction of capacity

    // Tight fits (small post_residual) are excellent; reward quadratically.
    score -= (1.0 - frac) * (1.0 - frac) * 30.0;

    // Dead-space penalty: residual that no typical item can use.
    // Items <= post_residual are usable; penalize unusable slivers.
    if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot land here: this residual is likely dead -> penalize
        let dead = (next_item_size as f64 - pr).min(pr);
        score += dead * 0.6;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fits: reward, more so if it's a tight nest
        let nest = 1.0 - (pr - next_item_size as f64) / cap;
        score -= nest * 12.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands of ~capacity/4).
    let quarter = bin_capacity / 4;
    let band = post_residual / quarter.max(1);
    score += band as f64 * 4.0; // higher bands (bigger leftover) mildly penalized

    // Perfect power-of-two style residual classes: residual % 10 == 0 keeps modularity
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual < 10 {
        score += 6.0; // sliver, near-unusable
    }

    // New-bin candidate: penalize so existing bins are preferred by default.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if opening a fresh bin leaves a very reusable residual, soften penalty
        score -= (1.0 - frac) * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Congestion: many open bins -> prefer filling existing ones harder.
    if open_bins_count > 2 {
        score += (open_bins_count as f64 - 2.0) * 0.8;
    }

    // Stream progression: late in stream, tighten packing (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - frac) * progress * 8.0;

    // Mean-residual coupling: if this bin's residual is far below mean, it's an outlier
    // worth closing out; if above mean, less attractive.
    let dev = pr - mean_residual;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps
    // (gaps below the minimum plausible item size of 1 are unavoidable,
    // but gaps of 1..=5 are nearly always dead space).
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    } else if post_residual > 5 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // If the leftover gap can exactly fit the lookahead item, reward strongly.
    if next_item_size > 0 && post_residual > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // If lookahead item cannot fit in the post residual, the gap is likely dead
    // space for the immediate future: penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 40.0 + 15.0 * open_bins_count as f64;
        // But if no open bin leaves a decent gap (mean residual small),
        // opening a new bin is more acceptable.
        if mean_residual < 15.0 {
            score -= 60.0;
        }
        // If the next item is large and current bins are tight, new bin helps.
        if next_item_size >= item_size && mean_residual < next_item_size as f64 {
            score -= 30.0;
        }
    }

    // Mild progression coupling: late in the stream, be slightly more
    // conservative about opening bins (packing tighter).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Prefer filling bins with larger residual (tighter bins first is
    // handled by post_residual already; add small tie-break on residual).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 500.0 / (post_residual as f64 + 1.0);
    }

    // 2-step lookahead: strongly reward if the next item exactly fills post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 / (gap + 1.0);
        if gap == 0.0 {
            score -= 300.0; // exact two-item match
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize leftover dead space proportionally.
        score += (next_item_size.min(post_residual.max(1))) as f64 * 0.5;
        score += 50.0;
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin opening unless current bins are quite full / poor fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count > 0 {
            score += 150.0;
        }
        // Late in stream, prefer filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 60.0;
        // Opening a new bin is fine if next item is large and would leave dead space.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 30.0;
        }
    }

    // Mild penalty for leaving awkward small residuals (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // residual chain usable: mild bonus proportional to left-over after next item
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here: penalize leaving medium-sized gaps
            score += 8.0;
        }
    }

    // Prefer filling bins with large residuals when mean residual is high (avoid fragmentation).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Early in stream: slightly favor keeping bins balanced (open more bins to preserve flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        // Late in stream: consolidate into fewest bins.
        score -= 0.25 * (bin_residual as f64 - mean_residual);
    }

    // Mild penalty when many bins are already open — encourage closing bins out.
    score += 0.3 * open_bins_count as f64;

    // Slight bias against opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress * (1.0 - progress) * 4.0);
    let mut score = pr * (1.0 - 0.5 * progress) + 40.0 * poly;
    // penalize dead space that no typical item can use
    if pr > 0.0 && pr < 10.0 {
        score += 30.0 * (10.0 - pr) as f64;
    }
    // reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;
    // last chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // lookahead: prefer bins whose post-residual still fits next item
    if next_item_size > 0 {
        if (pr as u32) >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0 * (1.0 - pr / cap);
        }
    }
    // mild penalty for many open bins to discourage fragmentation
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    // deviation from mean residual: prefer bins near mean to balance residuals
    score += 0.3 * (pr - mean_residual).abs();
    // new-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition [0,100] into classes
    // by integer division on 10-size buckets; dead space below 10 is worst.
    let class = post_residual / 10;
    // Penalize small-but-nonzero residuals harshly (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class coupling: residual class vs next item size class.
    if next_item_size > 0 {
        let next_class = next_item_size / 10;
        // If the next item would fit exactly in the new residual, reward.
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item harmonizes with residual.
            let harmon = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 15.0 * (1.0 - harmon);
        } else {
            // Next item won't fit here; penalize more for tiny residuals.
            score += 5.0 + (10 - class.min(10)) as f64;
        }
        // Modulo coupling: same residue class mod 20 harmonizes well.
        if post_residual % 20 == (next_item_size % 20) && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so it is
    // chosen only when open bins have poor fits; but early in stream or
    // with many items remaining, opening fresh bins is cheaper.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 45.0 - 20.0 * progress;
        // If existing fit is very tight (post_residual small), a new bin is bad.
        score = score.max(base) - if post_residual == 0 { 0.0 } else { 0.0 };
        score += base;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64 * 0.01;

    // Mean residual coupling: prefer bins far below mean residual (tighter bins).
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are pure waste. Penalize them super-linearly.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 25.0 * (dead_threshold as f64 - post_residual as f64);
    } else if post_residual <= 20 {
        // Small but potentially usable gap: mild penalty scaled by how far
        // below the "safe" 20-unit window it sits.
        score += 4.0 * (20.0 - post_residual as f64);
    }

    // Reward tight fits: the smaller the relative waste, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap < dead_threshold {
            score -= 35.0; // next item consumes the bin perfectly
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual is dead space for the known next item: penalize.
        score += 10.0 + 0.2 * (post_residual as f64);
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: bins far below the mean residual are already
    // tight; slightly reward placing into tighter-than-average bins.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: a fresh empty bin is a last resort.
    // It should only win when no open bin offers a decent fit, e.g. when
    // the item is large relative to available residuals or many bins are open.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream or with many open bins, be even more reluctant.
        score += 10.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item nests
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space relative to mean residual
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 10.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    }

    // Tight fit now is good (small post_residual), scaled against mean residual.
    score -= 15.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));

    // Penalize bins far below mean residual (they hoard space); slight reward above mean.
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, be more willing to open new bins (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
        // Don't open a new bin if a perfect match exists in an open bin.
        if next_item_size > 0 && post_residual == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        // dead space below min item size is unusable
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless this is a poor fit situation
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 250.0;
        // early in stream, opening bins is fine
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= 1.0 - 0.5 * progress;
        // if item is huge, a fresh bin is actually good
        if item_size >= 60 {
            new_bin_penalty -= 200.0;
        }
        // if many bins already open, discourage sprawl
        new_bin_penalty += open_bins_count as f64 * 5.0;
        score += new_bin_penalty;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
            // chain fit: next item then leaves small residue
            let chain = post_residual - next_item_size;
            if chain < 10 {
                score -= 40.0;
            }
        } else {
            // post-residual becomes dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Mild preference for filling fuller bins
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping.
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 40.0;

    // Smooth coupling with stream progress: late in the stream, tighten bins more aggressively.
    let late = progress * progress;
    score += late * (norm_pr * 30.0 + (pr - mean_residual).abs() * 0.25);

    // Penalize dead space relative to the next item's fit.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            // Small gap that fits next item well: reward (subtract).
            let fit_quality = 1.0 - (gap / cap);
            score -= fit_quality * fit_quality * 25.0;
        } else {
            // Next item cannot fit here: penalize proportionally to the shortfall.
            score += (-gap / cap) * (-gap / cap) * 20.0;
        }
    }

    // Last-chance bonus: only one bin fits the item, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Mild preference for bins with lower residual than the mean (compact bins).
    score += (pr - mean_residual) * 0.15;

    // Reward tight fits (small post_residual) with a smooth exponential term.
    score -= (-norm_pr * 8.0).exp() * 10.0;

    // Slight penalty for opening many bins late: favor consolidation.
    score += (open_bins_count as f64).ln() * late * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo small divisors
    let pr = post_residual;
    let class_penalty = match pr % 10 {
        0 => -6.0,                     // perfect multiple of 10: excellent dead space
        1 | 2 | 3 => 4.0,              // tiny slivers are near-unusable
        4 | 5 | 6 => 1.5,
        _ => 0.0,
    };
    score += class_penalty;

    // Fraction-of-capacity harmonic: reward residuals in the "half-ish" band
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.45 && frac < 0.55 {
        score -= 3.0;
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pair: post_residual mod next_item_size == 0 is ideal
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize small leftovers more
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.05;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 2.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize relative to how well open bins fit
    if bin_residual == bin_capacity {
        score += 12.0;
        // late in the stream, opening new bins is cheaper than fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0;
        // if mean residual is small, new bin is attractive
        score += mean_residual * 0.08;
    }

    // Mean residual alignment: prefer bins near the mean (balanced packing)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.03;

    // Integer division threshold: post_residual / item_size ratio
    if item_size > 0 {
        let div = post_residual / item_size;
        if div >= 2 {
            score -= 2.0; // room for another item of same size
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever host a
    // typical item (below the minimum item size of 1, but practically
    // small gaps) are wasted capacity. Penalize heavily when post_residual
    // is small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 25.0;
    }

    // Reward tight fits relative to the item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement; otherwise penalize leaving a residual that matches the
    // next item poorly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate implicitly by
    // rewarding open bins).
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Prefer bins with below-average residual (more filled).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    } else {
        // New-bin candidate: penalize more when many bins are open or the
        // stream is early (opening bins early is fine, later is wasteful).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify non-linearly.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - fit_frac).powi(4);

    // Penalize dead space: residuals too small for typical future items are wasted.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item.max(0.0) {
        score += 50.0;
    }
    // Dead-space penalty: residual below a plausible small-item threshold.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chaining: leaves exactly the next item's size
        } else if post_residual >= next_item_size {
            // good: next item can also go here; reward proportionally
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by how far off
            score += 6.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is progressing and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base reluctance to open new bins, decreasing as open bins pile up with bad fits.
        let mut new_bin_score = 55.0;
        // If many open bins exist and mean residual is small (fragmented), opening is worse.
        new_bin_score += open_bins_count as f64 * 1.5;
        // If mean residual is large (lots of slack), opening a fresh bin is more acceptable.
        new_bin_score -= mean_residual * 0.4;
        // Early in stream, slightly prefer reusing; late, allow opening.
        new_bin_score += (1.0 - progress) * 10.0;
        // If this item cannot fit any open bin (fitting_bins_count==0 means only new bin),
        // the new bin is the only option — make it very attractive.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // Lookahead: a fresh bin leaves room for the next item too.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_score -= 12.0;
        }
        score = new_bin_score;
    }

    // Mild global pressure: when many bins are open, favor consolidation into existing bins.
    score += open_bins_count as f64 * 0.3 * fit_frac;

    // Small time-dependent tie-breaker noise-free deterministic jitter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += ((step_index % 7) as f64) * 0.01 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: quadratic waste penalty scaled by progress
    let waste = fit_ratio * fit_ratio;
    score += waste * cap * (0.5 + progress);

    // Reward tight fits (low post_residual) with smooth exponential bonus
    score -= cap * (-(pr / cap) * 3.0).exp() * (1.0 - 0.5 * progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += (gap / cap) * (gap / cap) * 10.0;
        // Reward leaving room exactly for the next item
        let match_bonus = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= match_bonus.max(0.0) * 5.0;
    }

    // Last-chance bin bonus: prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - fit_ratio);
    }

    // Mild pressure to consolidate into many-open-bin states
    score -= (open_bins_count as f64).ln().max(0.0) * fit_ratio * 2.0;

    // Slight preference for bins with above-mean residual early on
    score += (mean_residual - pr) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify dead space by size class.
    // Residuals <= 10 are nearly dead; 11..=20 poor; 21..=30 marginal; >30 usable.
    let residual_class = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 20 { 2 }
        else if post_residual <= 30 { 3 }
        else { 4 };

    // Penalize dead-space classes super-linearly.
    score += match residual_class {
        0 => 0.0,
        1 => 40.0 + (10 - post_residual) as f64 * 3.0,
        2 => 12.0 + (20 - post_residual) as f64 * 1.5,
        3 => 4.0,
        _ => 0.0,
    };

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are "harmonic" and reusable -> reward them.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 6.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or well,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 - (slack.min(10) as f64);
        // Perfect chain: post_residual == next_item_size exactly.
        if slack == 0 { score -= 15.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving awkward space.
        score += (post_residual.min(next_item_size) as f64) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when current bins are crowded or the fit
        // elsewhere would be terrible; otherwise discourage (base cost).
        score = bin_capacity as f64 - 5.0;
        // Encourage new bin when many open bins already exist (spread load).
        score -= (open_bins_count.min(20) as f64) * 0.5;
        // Discourage new bin early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 8.0;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= bin_capacity / 2 { score -= 10.0; }
    }

    // Tight fits (small post_residual but > 0) are excellent: reward.
    if post_residual > 0 && post_residual <= 5 {
        score -= 20.0;
    }

    // Mild preference for bins below mean residual (balance load).
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fill: reward strongly.
        score -= 200.0;
    } else if post_residual < 10 {
        // Unusable dead space: heavy penalty scaled by gap smallness.
        score += (10.0 - post_residual as f64) * 12.0;
    }

    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Penalize creating a gap that can't fit the lookahead item if it could have.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // bin stays useful for next item
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys the ability to take the next item
            score += (next_item_size - post_residual) as f64 * 4.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Prefer bins with residual near the mean (balanced packing); avoid outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // New-bin candidate: only attractive when no open bin fits well
    // (its raw post_residual = capacity is large, so add a mild bias it must overcome).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: new bin is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect 2-step fit: strong bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Penalize dead space below the minimum plausible item size (waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight bias against opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Early in stream: allow more flexibility (mild penalty on tight fits to keep options).
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later steps favor tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of the bin by this item.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward high fill more strongly as the stream progresses.
    score -= 40.0 * fill * (0.5 + progress);

    // Penalize dead space non-linearly: small post-residuals are hard to reuse.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dead = pr / bin_capacity as f64;
        score += 30.0 * dead * dead;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
            // Extra reward when the next item fills the bin completely after this placement.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if next_item_size as f64 > pr * 1.6 {
            // Next item cannot use the leftover: penalize large unusable leftovers.
            score += 8.0;
        }
    } else {
        // Last item of the stream: only care about filling this bin well.
        score -= 15.0 * fill;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into
    // bins that deviate favorably (smaller residual than the mean means fuller bin).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score -= 5.0 * (dev / bin_capacity as f64);
        // Pressure to close bins when many are open.
        score += 3.0 * (open_bins_count as f64).ln().max(0.0) * (pr / bin_capacity as f64);
    }

    // New-bin candidate handling: make an empty bin attractive only when the item is large
    // or existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by how full this item makes it.
        score = bin_capacity as f64 * (1.0 - fill) + 10.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
        if item_size >= 60 {
            score -= 15.0; // large items start fresh bins happily
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // non-linear coupling of post_residual with stream progress
    score += 40.0 * (norm_pr * norm_pr) * (1.0 - t) * (1.0 - t);
    score -= 25.0 * norm_pr * t;
    // reward tight fits
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();
    // lookahead coupling: favor bins whose post residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 15.0 * (next_item_size as f64 / cap) * norm_pr;
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 35.0;
    }
    // mild preference for reusing existing bins over opening new ones
    if bin_residual < bin_capacity {
        score -= 5.0;
    }
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by how reusable it is.
    // Class 0: post_residual == 0 (perfect). Class 1: residual in smallest item range (1..=10) -> nearly dead.
    // Class 2: 11..=50 -> medium. Class 3: >50 -> very reusable.
    let pr = post_residual;
    let dead_penalty = if pr == 0 {
        0.0
    } else if pr <= 10 {
        90.0 + (10 - pr) as f64 * 4.0 // smaller leftover = worse waste
    } else if pr <= 50 {
        30.0 + ((pr - 11) % 10) as f64 * 1.5 // modulo ripple to break ties within class
    } else {
        0.0
    };
    score += dead_penalty;

    // Lookahead coupling: if next item fits exactly or well into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score -= 120.0 - (gap as f64).min(120.0); // reward closeness of next fit
        } else {
            // next item cannot use this residual: residual value drops if it's tiny
            if pr < 20 {
                score += 40.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // opening new bin is attractive only for large items (tight fit in fresh bin)
        score += 60.0 - tightness * 120.0;
        // avoid hoarding bins early in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 30.0 + open_bins_count as f64 * 2.0;
    }

    // Prefer filling bins that deviate below mean residual (balancing load).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Fraction-of-capacity harmonic coupling on post_residual.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (frac * std::f64::consts::PI).sin() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual accommodates the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // leftover gap likely wasted
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive when existing bins are crowded
    // (mean residual too small for the item) or nothing fits well.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 35.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild preference for filling fuller bins as the stream progresses.
    score -= 0.05 * (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let exact_fit = (post_residual - next_item_size) as f64;
        score -= 30.0 - 2.0 * exact_fit.min(30.0);
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to wasted lookahead
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Perfect-fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small post_residual that next item can't use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Discourage opening new bins early when a decent fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still supports lookahead
        }
    }

    // Slight preference for bins that leave residuals divisible by common sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero residuals that
    // few future items can use). Very small residuals are fine (near-full bin).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score -= 15.0; // near-perfect closure
        } else {
            // dead-space penalty peaks for residuals that are hard to reuse
            let awkward = (pr - 35.0).abs();
            score += 0.3 * awkward;
        }
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.2 * slack; // prefer chains that stay tight afterward
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here afterward; slight penalty proportional to waste
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened when many items remain
        // and current bins are fragmented (high mean residual).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 70.0;
        new_bin_score -= 20.0 * (1.0 - progress); // early stream: new bins cheaper
        new_bin_score -= 0.5 * (mean_residual - (cap * 0.5)); // fragmentation relief
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0; // no alternative
        }
        // A new bin is good if the item is large relative to capacity.
        new_bin_score -= 0.2 * item_size as f64;
        score = new_bin_score;
    } else {
        // Mild preference for filling already-open bins when many are open.
        score += 0.05 * open_bins_count as f64;
        // Prefer bins with residual close to the item (best-fit coupling).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.1 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - progress) * 0.5;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Lookahead synergy: post residual that can host the next item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 18.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item
        score += 12.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin residual deviates from mean residual (fragmentation control)
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).abs() * (1.0 + progress);

    // New-bin candidate: penalize slightly unless current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 20.0 - 25.0 * fragmentation * fragmentation * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class of residual magnitude (integer division thresholds on post_residual).
    let cls = post_residual / 10; // 0..=10 harmonic class
    score += match cls {
        0 => 40.0,           // tiny dead space: near-perfect packing
        1 => 10.0,           // 10-19 residual: useful for small items
        2 | 3 => 25.0,       // awkward mid-range gap
        4 | 5 => 15.0,
        6 => 5.0,            // half-bin residual: very reusable
        _ => 0.0,            // large residual: fine
    };

    // Reward residuals that exactly match the next item size (lookahead harmony).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: strong chaining bonus
            score -= 80.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += (next_item_size as f64).min(post_residual as f64) * 0.5;
        }
    }

    // Modulo-arithmetic harmony: residual divisible by common item sizes is reusable.
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when it enables a great future fit,
    // otherwise penalize so existing bins are preferred.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        } else {
            score += 120.0;
        }
    }

    // Progress-scaled tie-breaking: later in the stream, prefer tighter closures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;

    // Spread pressure: when many bins are open, prefer filling the emptiest gaps.
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (too small for typical future items) are heavily penalized.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills post_residual,
    // strongly prefer this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item cannot fit into post_residual (wasteful chain break).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.05 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // a fresh bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3;

    // New-bin candidate: make it attractive only when the fit into open bins is bad
    // (large post_residual relative to capacity) or few bins are open.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - fit_quality);
        score += open_bins_count as f64 * 1.5;
        score -= mean_residual * 0.2;
    } else {
        // Penalize placements into bins that deviate badly from mean residual
        // (keeps residual distribution balanced).
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
