    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: next item closes this bin
        } else if next_item_size < post_residual {
            // next item fits; reward proportionally to how well it fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill * fill;
            // leftover after the next item
            let after2 = post_residual - next_item_size;
            score += after2 as f64 * 0.35;
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 12.0 + over * 0.5;
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable to fill
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables perfect lookahead chain
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 0.8 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size == post_residual {
            score += base_penalty - 70.0; // opening new bin enables perfect chain
        } else {
            score += base_penalty;
        }
    }

    // Slight phase adaptation: early in stream, be more willing to open bins
    if total_items > 0 {
        let phase = step_index as f64 / total_items as f64;
        score += phase * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * (item_size as f64) / (bin_capacity as f64);
    }

    // Penalize dead space that is too small for typical items (1..100 unknown dist).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward; if it wastes the space, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into fuller bins.
    let mean_res_gap = (bin_residual as f64 - mean_residual).abs();
    score += mean_res_gap * 0.15;

    if mean_residual > (bin_capacity as f64) * 0.5 {
        score -= 4.0;
    }

    // Time horizon: early on, be more willing to open new bins (explore); later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses.
        score += 15.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin useful if next item is also large
        }
    } else {
        // Late stream: reward filling existing bins aggressively.
        score -= 10.0 * progress;
    }

    // Mild penalty for proliferation of open bins when placing into an existing bin.
    if bin_residual < bin_capacity && open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress) + 0.5 * pr_norm * pr_norm * cap * (1.0 - progress);

    // Penalize dead space that is too small to be useful, smoothly
    let dead = if pr < 10.0 { (10.0 - pr) * (10.0 - pr) * 0.8 } else { 0.0 };
    score += dead;

    // Reward tight fits (small post_residual relative to item), smoothly coupled with progress
    score -= item_size as f64 * (1.0 - pr_norm) * 0.6 * (0.5 + progress);

    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fits_next * next_item_size as f64 * 0.25 * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Prefer filling bins below mean residual (larger-than-average holes first)
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Mild new-bin penalty early, decaying with progress
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue class mod 10
    let residue_class = post_residual % 10;
    // Small dead-space classes are worse than "clean" classes (0, 10)
    let class_penalty = match residue_class {
        0 => 0.0,
        5 => 2.0,
        1 | 9 => 4.0,
        2 | 8 => 5.0,
        3 | 7 => 6.5,
        _ => 8.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 6.0; // tiny leftover, hard to reuse
    } else if post_residual < 2 * quarter {
        score -= 2.0; // moderate leftover, reusable
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain-perfect fit
        } else if next_item_size <= post_residual {
            score -= 12.0; // next item still fits here
        } else {
            // next item won't fit: penalize proportional to wasted potential
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0; // mild penalty to spread among many options
    }

    // New-bin candidate handling: empty bin should only win if residuals are poor
    if bin_residual == bin_capacity {
        // neutral base slightly above decent fits
        score += 25.0;
        // but if mean residual is small (open bins nearly full), new bin is attractive
        if mean_residual < 15.0 {
            score -= 35.0;
        }
        // late in stream, prefer consolidating into open bins less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Prefer tighter bins overall (deviation from mean residual)
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Modulo harmonic coupling on item_size vs post_residual
    if (item_size % 10) == (post_residual % 10) && post_residual > 0 {
        score -= 3.0; // harmonic alignment suggests future divisibility
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (dead space below min item size 1..10 is worthless;
    // gaps that can't fit typical items are wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Soft penalty for gaps that are too small for the next item (lookahead-aware dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward tight fits (post_residual near zero but usable)
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward exact fit of next item into post_residual (perfect chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    // Mild bonus when this bin's residual is below mean (already tight bin)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }
    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let match_gap = (post_residual as f64 - next_item_size as f64).abs();
        // Perfect chain (next item exactly fills leftover)
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward closeness of the chain
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
            // leftover after chaining
            let chain_left = post_residual - next_item_size;
            if chain_left < 10 {
                score -= 20.0; // near-perfect two-item packing
            }
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 0.8 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin chains well with next item
        } else {
            score += 25.0 + 5.0 * open_bins_count as f64;
        }
        // Late in stream: avoid opening unnecessary bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}
